def _serialize_replenishment(
    row: Optional[DeliveryDeviceReplenishmentDemandModel],
) -> Optional[dict]:
    """Credential-free fixed DTO shared by BUSINESS and device views."""
    if row is None:
        return None
    # Even short upstream diagnostics can contain a bearer token, callback URL
    # or OTP.  Length limiting alone is not a credential boundary.
    error = _safe_invite_diagnostic(row.error or "").strip()
    # All writers use a closed set of Chinese summaries.  Keep a final length
    # bound so an accidentally propagated upstream exception can never turn a
    # status endpoint into a credential/log exfiltration surface.
    if len(error) > 200:
        error = "自动补位需要人工复核"
    return {
        "demand_id": str(row.id),
        "state": str(row.state or "pending"),
        "stage": str(row.stage or "queued"),
        "provider": str(row.provider or ""),
        "device_id": int(row.device_id or 0),
        "parent_id": int(row.business_parent_id or 0),
        "seat_type": str(row.seat_type or ""),
        "next_check_at": _iso_utc(row.next_check_at) if row.next_check_at else "",
        "resume_at": _iso_utc(row.resume_at) if row.resume_at else "",
        "last_checked_at": (
            _iso_utc(row.last_checked_at) if row.last_checked_at else ""
        ),
        "attempt_count": int(row.attempt_count or 0),
        "fill_job_id": str(row.fill_job_id or ""),
        "created_at": _iso_utc(row.created_at),
        "updated_at": _iso_utc(row.updated_at),
        "completed_at": _iso_utc(row.completed_at) if row.completed_at else "",
        "error": error,
    }


def _latest_replenishments_by_parent(
    session: Session,
    parent_ids: List[int],
) -> Dict[int, DeliveryDeviceReplenishmentDemandModel]:
    ids = sorted({int(value) for value in parent_ids if int(value) > 0})
    if not ids:
        return {}
    try:
        rows = session.exec(
            select(DeliveryDeviceReplenishmentDemandModel)
            .where(
                DeliveryDeviceReplenishmentDemandModel.business_parent_id.in_(ids)  # type: ignore[union-attr]
            )
            .order_by(
                col(DeliveryDeviceReplenishmentDemandModel.created_at).desc(),
                col(DeliveryDeviceReplenishmentDemandModel.updated_at).desc(),
            )
        ).all()
    except OperationalError:
        # Rolling deployments may serve one read while the new table is still
        # being created.  Status enrichment is optional and must fail closed
        # to ``null`` rather than break the account directory.
        session.rollback()
        return {}
    result: Dict[int, DeliveryDeviceReplenishmentDemandModel] = {}
    for row in rows:
        parent_id = int(row.business_parent_id)
        current = result.get(parent_id)
        if current is None:
            result[parent_id] = row
            continue
        # A more recently completed/cancelled demand must not hide an older
        # demand which is still waiting for cooldown/candidate/fill.  Within
        # each class rows are already newest-first, so only replace a terminal
        # choice with the first non-terminal row encountered.
        if (
            str(current.state or "") in _REPLENISHMENT_TERMINAL_STATES
            and str(row.state or "") not in _REPLENISHMENT_TERMINAL_STATES
        ):
            result[parent_id] = row
    return result


def _extra_get(acc: "GptBusinessAccountModel", key: str, default=None):
    try:
        return json.loads(acc.extra_json or "{}").get(key, default)
    except Exception:
        return default


def _burned_count_for_biz(account_id: int, acc: "Optional[GptBusinessAccountModel]" = None) -> int:
    """该 BUSINESS 母号已退 PRO 数量（仅用于历史统计/兼容展示）。
    若账号 extra_json 里有手动覆盖 pro_burn_manual_count(界面可改)则以其为准, 否则按实际焚过的自动统计。"""
    try:
        if acc is None:
            with Session(engine) as s:
                acc = s.get(GptBusinessAccountModel, account_id)
        if acc is not None:
            try:
                ov = json.loads(acc.extra_json or "{}").get("pro_burn_manual_count")
                if isinstance(ov, int) and ov >= 0:
                    return ov
            except Exception:
                pass
        from api.business_masters import _burned_count
        return _burned_count(f"biz{account_id}")
    except Exception:
        return 0


def _business_cookie_at_team(blob: str):
    """从 BUSINESS 账号 cookie_blob 取 oai-access-token(AT)+ 解出 team account_id + plan。
    返回 (at, team_id, plan)。"""
    import base64 as _b64
    at = ""
    for part in (blob or "").split(";"):
        if "=" in part:
            k, v = part.split("=", 1)
            if k.strip() == "oai-access-token":
                at = v.strip()
    team = ""
    plan = ""
    if at:
        try:
            seg = at.split(".")[1]
            seg += "=" * (-len(seg) % 4)
            claims = json.loads(_b64.urlsafe_b64decode(seg))
            auth = claims.get("https://api.openai.com/auth", {})
            team = auth.get("chatgpt_account_id", "") or ""
            plan = auth.get("chatgpt_plan_type", "") or ""
        except Exception:
            pass
    return at, team, plan


_BUSINESS_TEAM_PLAN_TYPES = frozenset({
    "team",
    "business",
    "chatgptteamplan",
    "chatgptbusinessplan",
})


def _business_team_session_status(
    blob: str,
    *,
    now: Optional[datetime] = None,
    ever_logged: Optional[bool] = None,
) -> dict:
    """Validate a saved BUSINESS Team session without making a network call.

    A non-empty ``cookie_blob`` or persisted ``cookie_updated_at`` is the durable
    *ever logged in* marker used by the account tabs.  It is intentionally
    different from ``usable``: an old, cleared, or malformed cookie remains in
    the logged-in tab but must never start workspace refresh, allocation,
    OAuth, or CPA automation.

    A token with less than one minute remaining is treated as expired.  Remote
    workspace operations can take several requests, so accepting a token at the
    very end of its lifetime would turn a local preflight into an ambiguous
    partial mutation.
    """
    import base64 as _b64

    raw_blob = str(blob or "")
    saved_before = bool(raw_blob.strip()) if ever_logged is None else bool(
        ever_logged or raw_blob.strip()
    )
    result = {
        "ever_logged": saved_before,
        "usable": False,
        "reason": "never_logged",
        "access_token": "",
        "team_id": "",
        "plan_type": "",
        "expires_at": "",
    }
    if not result["ever_logged"]:
        return result
    if not raw_blob.strip():
        result["reason"] = "missing_access_token"
        return result

    access_token = ""
    for part in raw_blob.split(";"):
        if "=" not in part:
            continue
        key, value = part.split("=", 1)
        if key.strip() == "oai-access-token":
            access_token = value.strip()
            break
    if not access_token:
        result["reason"] = "missing_access_token"
        return result
    result["access_token"] = access_token

    try:
        parts = access_token.split(".")
        if len(parts) != 3:
            raise ValueError("JWT segment count")
        payload = parts[1] + "=" * (-len(parts[1]) % 4)
        claims = json.loads(_b64.urlsafe_b64decode(payload))
        if not isinstance(claims, dict):
            raise ValueError("JWT payload")
        auth = claims.get("https://api.openai.com/auth") or {}
        if not isinstance(auth, dict):
            raise ValueError("JWT auth claims")
        expires_at = int(claims.get("exp") or 0)
    except Exception:
        result["reason"] = "invalid_access_token"
        return result

    team_id = str(auth.get("chatgpt_account_id") or "").strip()
    plan_type = str(auth.get("chatgpt_plan_type") or "").strip()
    result["team_id"] = team_id
    result["plan_type"] = plan_type
    if expires_at > 0:
        result["expires_at"] = datetime.fromtimestamp(
            expires_at, tz=timezone.utc,
        ).isoformat()
    if not team_id:
        result["reason"] = "missing_workspace"
        return result
    if plan_type.lower() not in _BUSINESS_TEAM_PLAN_TYPES:
        result["reason"] = "invalid_team_plan"
        return result

    current = _aware(now) or _utcnow()
    if expires_at <= int(current.timestamp()) + 60:
        result["reason"] = "expired_access_token"
        return result

    result["usable"] = True
    result["reason"] = "usable"
    return result


def _business_account_team_session_status(
    account: GptBusinessAccountModel,
    *,
    now: Optional[datetime] = None,
) -> dict:
    blob = str(getattr(account, "cookie_blob", "") or "")
    status = _business_team_session_status(
        blob,
        now=now,
        ever_logged=bool(
            blob.strip() or getattr(account, "cookie_updated_at", None) is not None
        ),
    )
    persisted_expiry = _aware(getattr(account, "cookie_expires_at", None))
    current = _aware(now) or _utcnow()
    if (
        bool(status.get("usable"))
        and persisted_expiry is not None
        and persisted_expiry <= current + timedelta(seconds=60)
    ):
        status["usable"] = False
        status["reason"] = "expired_access_token"
        status["expires_at"] = persisted_expiry.isoformat()
    # A JWT's exp is not proof that the server still accepts it. Evidence is
    # tied to the exact saved cookie and automatically expires on a new login.
    from services.business_session_health import public_health
    health = public_health(account)
    if health["status"] in {"invalid", "unauthorized"}:
        status["usable"] = False
        status["reason"] = "remote_session_invalid"
    return status


def _business_team_session_error(status: dict) -> dict:
    reason = str(status.get("reason") or "invalid_team_session")
    messages = {
        "never_logged": "该 BUSINESS 母号从未登录，请先登录并进入 Team 工作区",
        "missing_access_token": "该 BUSINESS 母号没有可用 Access Token，请重新登录",
        "invalid_access_token": "该 BUSINESS 母号的登录会话无效，请重新登录",
        "expired_access_token": "该 BUSINESS 母号的 AT 已到期，请检查会话以尝试刷新，或重新登录",
        "missing_workspace": "登录会话缺少 Team 工作区 ID，请重新登录并选择 BUSINESS 工作区",
        "invalid_team_plan": "当前登录会话不是 Team/BUSINESS 工作区，请重新登录并选择正确工作区",
        "remote_session_invalid": "BUSINESS 会话已被远端拒绝，请检查会话以尝试刷新，或重新登录母号",
    }
    result = {
        "code": "business_team_session_unavailable",
        "reason": reason,
        "message": messages.get(reason, "该 BUSINESS 母号缺少可用 Team 会话，请重新登录"),
    }
    return result


def _business_cpa_device_binding_eligibility(
    account: GptBusinessAccountModel,
    status: Optional[dict] = None,
) -> dict:
    """Use the same durable login classification as the logged-in account tab."""
    team_session = status or _business_account_team_session_status(account)
    logged_in = bool(team_session.get("ever_logged"))
    blockers: List[dict] = []
    if not logged_in:
        blockers.append({
            "code": "never_logged",
            "message": "该 BUSINESS 母号不在已登录 Tab，不能新绑定 CPA 设备",
        })
    if not bool(account.enabled):
        blockers.append({"code": "disabled", "message": "母号已禁用"})
    if bool(account.dangerous):
        blockers.append({"code": "dangerous", "message": "母号已标记 dangerous/dead"})
    if str(account.refund_status or "").strip():
        blockers.append({"code": "refund", "message": "母号正在退款流程"})
    if logged_in and not bool(team_session.get("usable")):
        detail = _business_team_session_error(team_session)
        blockers.append({
            "code": "invalid_team_session",
            "reason": str(team_session.get("reason") or "invalid_team_session"),
            "message": str(detail.get("message") or "Team 登录会话不可用"),
        })
    result = {
        "logged_in": logged_in,
        "eligible": not blockers,
        "blockers": blockers,
    }
    return result


def _assert_business_team_session_usable(
    account_id: int,
    *,
    status_code: int = 409,
) -> tuple[str, str, str, str]:
    """Return the local Team credentials or fail before any remote call."""
    with Session(engine) as session:
        account = session.get(GptBusinessAccountModel, int(account_id))
        if not account:
            raise HTTPException(404, "BUSINESS 母号不存在")
        status = _business_account_team_session_status(account)
    if not bool(status.get("usable")):
        raise HTTPException(status_code, _business_team_session_error(status))
    from core.config_store import config_store
    proxy = str(config_store.get("default_proxy", "") or "").strip()
    return (
        str(status["access_token"]),
        str(status["team_id"]),
        str(status["plan_type"]),
        proxy,
    )


def business_parent_ids_with_usable_team_sessions() -> set[int]:
    """Local-only allow-list used by schedulers before BUSINESS child work."""
    with Session(engine) as session:
        parents = session.exec(select(GptBusinessAccountModel)).all()
    return {
        int(parent.id)
        for parent in parents
        if parent.id is not None
        and bool(parent.enabled)
        and not bool(parent.dangerous)
        and not str(parent.refund_status or "").strip()
        and bool(
            _business_account_team_session_status(parent).get("usable")
        )
    }


def _biz_openai(method: str, url: str, at: str, team: str, proxy: str = "",
                json_body=None, params=None):
    """用 BUSINESS 账号 cookie 的 AT 调 chatgpt.com 后台。返回 (status, json|text)。"""
    from curl_cffi import requests as cr
    headers = {"Authorization": f"Bearer {at}", "chatgpt-account-id": team,
               "Content-Type": "application/json", "Accept": "*/*",
               "Origin": "https://chatgpt.com", "Referer": "https://chatgpt.com/"}
    prox = {"http": proxy, "https": proxy} if proxy else None
    fn = getattr(cr, method.lower())
    request_started_at = _utcnow()
    kw = dict(headers=headers, impersonate="chrome131", proxies=prox, timeout=30)
    if json_body is not None:
        kw["json"] = json_body
    if params is not None:
        kw["params"] = params
    r = fn(url, **kw)
    st = int(getattr(r, "status_code", 0) or 0)
    if st == 401:
        # Preserve status/body: callers must still release reservations for a
        # definite rejected POST. Never silently replay an invite or deletion.
        try:
            from services.business_session_health import note_unauthorized
            note_unauthorized(at, team, request_started_at=request_started_at)
        except Exception:
            pass
    try:
        return st, r.json()
    except Exception:
        return st, (getattr(r, "text", "") or "")[:300]


def _iso_utc(value: Optional[datetime]) -> str:
    """带 UTC 标记的 ISO 字符串。

    库里存的是 naive UTC(_utcnow() 写入时丢了 tzinfo), 直接 isoformat() 出去没有
    时区后缀, 前端 new Date() 会按**本地时间**解析 → 界面时间比真实时刻差一个时区。
    这里显式补上 +00:00, 前端才能正确换算成本地时间显示。
    """
    if not value:
        return ""
    dt = value if value.tzinfo else value.replace(tzinfo=timezone.utc)
    return dt.isoformat()


def _business_workspace_settings_url(team: str, setting: str = "") -> str:
    """Build the only allow-listed OpenAI Workspace settings URL.

    ``team`` originates in a saved JWT claim.  The token is authenticated by
    OpenAI on every request, but the claim is still untrusted path input here;
    constrain it before composing an outbound URL so it cannot add path/query
    components or redirect the settings request to another endpoint.
    """
    workspace_id = str(team or "").strip()
    if not _BUSINESS_WORKSPACE_ID_RE.fullmatch(workspace_id):
        raise HTTPException(409, {
            "code": "business_workspace_id_invalid",
            "message": "BUSINESS Team 会话中的 Workspace ID 格式无效，请重新登录",
        })
    suffix = ""
    if setting:
        if setting != "workspace_referrals_enabled":
            raise ValueError("unsupported BUSINESS workspace setting")
        suffix = f"/{setting}"
    return f"https://chatgpt.com/backend-api/accounts/{workspace_id}/settings{suffix}"


def _unknown_workspace_referrals_settings(*, checked_at: str = "") -> dict:
    """Return the explicit tri-state representation for an unverified read."""
    return {
        "workspace_referrals_enabled": None,
        "workspace_referrals_enabled_visible": None,
        "workspace_referrals_enabled_checked_at": str(checked_at or ""),
    }


def _workspace_referrals_settings_from_body(
    body: Any,
    *,
    checked_at: str,
) -> dict:
    """Allow-list the two Workspace referral booleans without coercion."""
    if not isinstance(body, dict):
        return _unknown_workspace_referrals_settings(checked_at=checked_at)
    enabled = body.get("workspace_referrals_enabled")
    visible = body.get("workspace_referrals_enabled_visible")
    return {
        "workspace_referrals_enabled": (
            enabled if isinstance(enabled, bool) else None
        ),
        "workspace_referrals_enabled_visible": (
            visible if isinstance(visible, bool) else None
        ),
        "workspace_referrals_enabled_checked_at": checked_at,
    }


def _fetch_workspace_referrals_settings(
    at: str,
    team: str,
    proxy: str = "",
) -> dict:
    """Read a credential-free, tri-state Workspace referral snapshot.

    A transport error, non-200 response, malformed JSON or missing field is
    represented by JSON ``null``.  In particular, none of those conditions may
    be collapsed to ``False`` because that would invent a remote setting.
    """
    checked_at = _iso_utc(_utcnow())
    url = _business_workspace_settings_url(team)
    try:
        status, body = _biz_openai("GET", url, at, team, proxy)
    except Exception:
        return _unknown_workspace_referrals_settings(checked_at=checked_at)
    if status != 200:
        return _unknown_workspace_referrals_settings(checked_at=checked_at)
    return _workspace_referrals_settings_from_body(body, checked_at=checked_at)


