# ── 导入任务存储 ─────────────────────────────────────────────

@dataclass
class GptBusinessImportTaskRecord:
    id: str
    total: int
    status: str = "pending"
    progress: str = "0/0"
    processed: int = 0
    success: int = 0
    failed: int = 0
    errors: list[str] = field(default_factory=list)
    created_at: float = field(default_factory=time.time)
    updated_at: float = field(default_factory=time.time)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "id": self.id,
            "status": self.status,
            "progress": self.progress,
            "total": self.total,
            "processed": self.processed,
            "success": self.success,
            "failed": self.failed,
            "errors": list(self.errors),
            "created_at": self.created_at,
            "updated_at": self.updated_at,
        }


class GptBusinessImportTaskStore:
    def __init__(self, *, max_finished_tasks: int = MAX_FINISHED_IMPORT_TASKS):
        self._lock = threading.Lock()
        self._records: Dict[str, GptBusinessImportTaskRecord] = {}
        self.max_finished_tasks = max_finished_tasks

    def create(self, task_id: str, *, total: int) -> GptBusinessImportTaskRecord:
        with self._lock:
            record = GptBusinessImportTaskRecord(
                id=task_id,
                total=total,
                progress=f"0/{total}",
            )
            self._records[task_id] = record
            return record

    def exists(self, task_id: str) -> bool:
        with self._lock:
            return task_id in self._records

    def snapshot(self, task_id: str) -> Dict[str, Any]:
        with self._lock:
            return self._records[task_id].to_dict()

    def list_snapshots(self) -> list[Dict[str, Any]]:
        with self._lock:
            records = list(self._records.values())
            records.sort(key=lambda r: r.updated_at, reverse=True)
            return [r.to_dict() for r in records]

    def mark_running(self, task_id: str) -> None:
        with self._lock:
            r = self._records[task_id]
            r.status = "running"
            r.updated_at = time.time()

    def update(
        self,
        task_id: str,
        *,
        processed: Optional[int] = None,
        success: Optional[int] = None,
        failed: Optional[int] = None,
        append_error: Optional[str] = None,
    ) -> None:
        with self._lock:
            r = self._records[task_id]
            if processed is not None:
                r.processed = processed
                r.progress = f"{processed}/{r.total}"
            if success is not None:
                r.success = success
            if failed is not None:
                r.failed = failed
            if append_error:
                r.errors.append(append_error)
            r.updated_at = time.time()

    def finish(self, task_id: str, *, status: str = "done") -> None:
        with self._lock:
            r = self._records[task_id]
            r.status = status
            r.progress = f"{r.processed}/{r.total}"
            r.updated_at = time.time()
            self._cleanup_finished_locked()

    def fail(self, task_id: str, message: str) -> None:
        with self._lock:
            r = self._records[task_id]
            r.status = "failed"
            r.errors.append(message)
            r.updated_at = time.time()
            self._cleanup_finished_locked()

    def _cleanup_finished_locked(self) -> None:
        finished = [rid for rid, r in self._records.items() if r.status in {"done", "failed"}]
        overflow = len(finished) - self.max_finished_tasks
        if overflow <= 0:
            return
        finished.sort(key=lambda rid: self._records[rid].updated_at)
        for rid in finished[:overflow]:
            self._records.pop(rid, None)


_import_task_store = GptBusinessImportTaskStore()


def _count_import_lines(data: str) -> int:
    total = 0
    for raw_line in (data or "").splitlines():
        line = str(raw_line or "").strip()
        if line and not line.startswith("#"):
            total += 1
    return total


def _ensure_import_task_exists(task_id: str) -> None:
    if not _import_task_store.exists(task_id):
        raise HTTPException(404, "导入任务不存在")


# ── OAuth 后台任务存储(实时日志轮询) ─────────────────────────
_OAUTH_TASKS: Dict[str, Dict[str, Any]] = {}
_OAUTH_LOCK = threading.Lock()
_OAUTH_MAX_LINES = 800
_OAUTH_RETAIN_SECONDS = 2 * 60 * 60


def _create_oauth_task() -> str:
    task_id = _uuid.uuid4().hex
    with _OAUTH_LOCK:
        _OAUTH_TASKS[task_id] = {
            "status": "running",
            "logs": [],
            "result": None,
            "error": None,
            "progress": None,
            "started_at": _utcnow().isoformat(),
            "finished_at": "",
        }
        cutoff = time.time() - _OAUTH_RETAIN_SECONDS
        stale = []
        for tid, t in _OAUTH_TASKS.items():
            if tid == task_id:
                continue
            fin = t.get("finished_at") or ""
            if not fin:
                continue
            try:
                ts = datetime.fromisoformat(fin).timestamp()
            except Exception:
                ts = 0
            if ts and ts < cutoff:
                stale.append(tid)
        for tid in stale:
            _OAUTH_TASKS.pop(tid, None)
    return task_id


def _sanitize_business_oauth_task_text(value: Any) -> str:
    """Apply the same token/OTP/phone redaction as GPT PRO OAuth tasks."""
    text = str(value or "")
    try:
        from api.gpt_plan_operations import _sanitize_background_task_text

        text = _sanitize_background_task_text(text)
    except Exception:
        # Fail closed even during an unusual partial-import state.
        text = re.sub(
            r"(?i)\bBearer\s+[A-Za-z0-9._~+/=-]+",
            "Bearer [redacted]",
            text,
        )
        text = re.sub(
            r"(?i)(access|refresh|id|session)[_-]?token\s*[:=]\s*[^\s,;]+",
            lambda match: f"{match.group(1)}_token=[redacted]",
            text,
        )
        text = re.sub(
            r"(?i)(otp|verification[_ -]?code|验证码)\s*[:=：]?\s*\d{4,8}",
            lambda match: f"{match.group(1)}=[redacted]",
            text,
        )
    return text[:1000]


def _oauth_task_log(task_id: str, msg: str) -> None:
    safe_msg = _sanitize_business_oauth_task_text(msg)
    line = f"[{datetime.now().strftime('%H:%M:%S')}] {safe_msg}"
    with _OAUTH_LOCK:
        t = _OAUTH_TASKS.get(task_id)
        if not t:
            return
        t["logs"].append(line)
        if len(t["logs"]) > _OAUTH_MAX_LINES:
            t["logs"] = t["logs"][-_OAUTH_MAX_LINES:]
    try:
        print(f"[gpt-business-oauth {task_id[:8]}] {safe_msg}", flush=True)
    except Exception:
        pass


def _oauth_task_finish(task_id: str, *, result: Optional[Dict[str, Any]] = None,
                       error: Optional[str] = None) -> None:
    with _OAUTH_LOCK:
        t = _OAUTH_TASKS.get(task_id)
        if not t:
            return
        t["status"] = "failed" if error else "done"
        t["result"] = result
        t["error"] = _sanitize_business_oauth_task_text(error) if error else error
        t["finished_at"] = _utcnow().isoformat()


def _snapshot_oauth_task(task_id: str, *, since: int) -> Optional[Dict[str, Any]]:
    with _OAUTH_LOCK:
        t = _OAUTH_TASKS.get(task_id)
        if not t:
            return None
        all_logs = list(t["logs"])
        tail = all_logs[max(0, int(since or 0)):]
        return {
            "status": t["status"],
            "logs": tail,
            "since": len(all_logs),
            "result": t["result"],
            "error": t["error"],
            "progress": t.get("progress"),
            "started_at": t["started_at"],
            "finished_at": t["finished_at"],
        }


def _resolve_action_proxy(body: Optional["GptBusinessActionRequest"]) -> str:
    if body and body.proxy is not None:
        return str(body.proxy or "").strip()
    try:
        from core.config_store import config_store
        return str(config_store.get("default_proxy", "") or "").strip()
    except Exception:
        return ""


# ── Microsoft Outlook 网页登录后台任务(实时日志轮询) ─────────────
#
# 网页登录会把 Chromium 留给用户完成 MFA/验证码，因此不能把「线程已启动」
# 当作「登录成功」。任务状态只保存在内存中，限制任务数量和日志行数，避免
# 长时间运行的服务因浏览器任务日志无限增长而耗尽内存。
_MS_WEB_TASKS: Dict[str, Dict[str, Any]] = {}
_MS_WEB_LOCK = threading.RLock()
_MS_WEB_ACTIVE: Dict[int, str] = {}
_MS_WEB_MAX_TASKS = 100
_MS_WEB_MAX_LOG_LINES = 800
_MS_WEB_RETAIN_SECONDS = 2 * 60 * 60
_MS_WEB_TERMINAL_STATUSES = {"logged_in", "needs_manual", "failed", "exception"}


def _ms_web_redact(value: Any, *secrets: str) -> str:
    """把任务日志/错误转换成安全文本，绝不回传保存的邮箱密码。"""
    text = str(value or "")
    for secret in secrets:
        secret = str(secret or "")
        if secret:
            text = text.replace(secret, "[REDACTED]")
    return text[:2000]


_MS_WEB_URL_RE = re.compile(r"https?://[^\s<>\"']+")


def _ms_web_redact_urls(text: str, *, password: str = "", proxy: str = "") -> str:
    """清理日志中的绝对 URL，去掉 userinfo、query 和 fragment。"""
    def _replace(match: re.Match[str]) -> str:
        raw = match.group(0)
        trailing = ""
        while raw and raw[-1] in ".,;:)]}>":
            trailing = raw[-1] + trailing
            raw = raw[:-1]
        return _ms_web_safe_url(raw, password=password, proxy=proxy) + trailing

    return _MS_WEB_URL_RE.sub(_replace, text)


def _ms_web_cleanup_locked() -> None:
    """清理过期/超量的已完成任务；调用方必须持有 ``_MS_WEB_LOCK``。"""
    now = time.time()
    # 先按保留时间清理终态任务。running 任务永远不会被此处删除。
    for task_id, task in list(_MS_WEB_TASKS.items()):
        if task.get("status") == "running":
            continue
        finished_at = float(task.get("finished_ts") or task.get("updated_ts") or 0)
        if finished_at and now - finished_at > _MS_WEB_RETAIN_SECONDS:
            _MS_WEB_TASKS.pop(task_id, None)

    # 再限制总数。优先淘汰最旧的终态任务，绝不淘汰运行中的任务。
    overflow = len(_MS_WEB_TASKS) - _MS_WEB_MAX_TASKS
    if overflow <= 0:
        return
    finished = [
        (float(t.get("finished_ts") or t.get("updated_ts") or 0), tid)
        for tid, t in _MS_WEB_TASKS.items()
        if t.get("status") != "running"
    ]
    finished.sort()
    for _, task_id in finished[:overflow]:
        _MS_WEB_TASKS.pop(task_id, None)


def _ms_web_new_task(account_id: int) -> Dict[str, Any]:
    """创建一个状态为 running 的任务并返回其内部记录。"""
    task_id = _uuid.uuid4().hex
    now = _utcnow().isoformat()
    task = {
        "task_id": task_id,
        "account_id": int(account_id),
        "status": "running",
        "stage": "starting",
        "logs": [],
        "log_offset": 0,
        "url": "",
        "error": "",
        "result": None,
        "created_at": now,
        "updated_at": now,
        "finished_at": "",
        "updated_ts": time.time(),
        "finished_ts": 0.0,
    }
    _MS_WEB_TASKS[task_id] = task
    _MS_WEB_ACTIVE[int(account_id)] = task_id
    _ms_web_cleanup_locked()
    return task


def _ms_web_log(
    task_id: str,
    message: Any,
    *,
    password: str = "",
    proxy: str = "",
) -> None:
    """追加一条不包含密码或代理凭据的任务日志。"""
    safe = _ms_web_redact(message, password, proxy)
    safe = _ms_web_redact_urls(safe, password=password, proxy=proxy)
    if not safe:
        return
    with _MS_WEB_LOCK:
        task = _MS_WEB_TASKS.get(task_id)
        if not task:
            return
        task["logs"].append(safe)
        if len(task["logs"]) > _MS_WEB_MAX_LOG_LINES:
            dropped = len(task["logs"]) - _MS_WEB_MAX_LOG_LINES
            del task["logs"][:dropped]
            task["log_offset"] = int(task.get("log_offset") or 0) + dropped
        task["updated_at"] = _utcnow().isoformat()
        task["updated_ts"] = time.time()


def _ms_web_safe_url(value: Any, *, password: str = "", proxy: str = "") -> str:
    """保留登录页面路径但去掉 query/fragment，避免回传挑战参数或凭据。"""
    raw = _ms_web_redact(value, password, proxy)
    if not raw:
        return ""
    try:
        parsed = urlsplit(raw)
        if parsed.scheme and parsed.netloc:
            # URL 中可能出现 user:password@host；只保留主机和端口。
            host = parsed.hostname or ""
            if ":" in host and not host.startswith("["):
                host = f"[{host}]"
            try:
                port = parsed.port
            except ValueError:
                port = None
            netloc = host + (f":{port}" if port else "")
            return urlunsplit((parsed.scheme, netloc, parsed.path, "", ""))[:2000]
    except Exception:
        pass
    return raw[:2000]


def _ms_web_finish(
    task_id: str,
    *,
    status: str,
    stage: str,
    url: str = "",
    result: Optional[Dict[str, Any]] = None,
    error: str = "",
    password: str = "",
    proxy: str = "",
) -> None:
    """写入终态并释放该账号的 active 标记。"""
    with _MS_WEB_LOCK:
        task = _MS_WEB_TASKS.get(task_id)
        if not task:
            return
        safe_error = _ms_web_redact(error, password, proxy)
        safe_error = _ms_web_redact_urls(safe_error, password=password, proxy=proxy)
        task["status"] = status
        task["stage"] = _ms_web_redact(stage, password, proxy)
        task["url"] = _ms_web_safe_url(url, password=password, proxy=proxy)
        task["error"] = safe_error
        # 只保存自动化返回的非敏感元数据，不保存 cookies/token/密码。
        if isinstance(result, dict):
            task["result"] = {
                "ok": bool(result.get("ok")),
                "stage": _ms_web_redact(result.get("stage"), password, proxy),
                "url": _ms_web_safe_url(result.get("url"), password=password, proxy=proxy),
            }
        else:
            task["result"] = None
        now = _utcnow()
        task["updated_at"] = now.isoformat()
        task["finished_at"] = now.isoformat()
        task["updated_ts"] = time.time()
        task["finished_ts"] = task["updated_ts"]
        account_id = int(task.get("account_id") or 0)
        if _MS_WEB_ACTIVE.get(account_id) == task_id:
            _MS_WEB_ACTIVE.pop(account_id, None)
        _ms_web_cleanup_locked()


def _ms_web_snapshot(task_id: str, *, since: int = 0) -> Optional[Dict[str, Any]]:
    """返回任务快照以及从 ``since`` 开始的增量日志。"""
    try:
        offset = max(0, int(since or 0))
    except (TypeError, ValueError):
        offset = 0
    with _MS_WEB_LOCK:
        task = _MS_WEB_TASKS.get(task_id)
        if not task:
            return None
        logs = list(task.get("logs") or [])
        log_offset = int(task.get("log_offset") or 0)
        # ``since`` is an absolute log cursor. If the caller asks for a cursor
        # older than the retained window, return the oldest retained entries.
        local_since = max(0, offset - log_offset)
        return {
            "task_id": task_id,
            "account_id": task.get("account_id"),
            "status": task.get("status", "running"),
            "stage": task.get("stage", "starting"),
            "logs": logs[local_since:],
            "since": log_offset + len(logs),
            "url": task.get("url", ""),
            "error": task.get("error", ""),
            "result": task.get("result"),
            "created_at": task.get("created_at", ""),
            "updated_at": task.get("updated_at", ""),
            "finished_at": task.get("finished_at", ""),
        }


def _ms_web_provider(acc: "GptBusinessAccountModel") -> str:
    """读取 BUSINESS 账号 provider；缺失/非法 JSON 默认 Outlook。"""
    try:
        metadata = json.loads(getattr(acc, "extra_json", "") or "{}")
    except Exception:
        metadata = {}
    if not isinstance(metadata, dict):
        return "outlook"
    value = metadata.get("mail_provider", metadata.get("provider", "outlook"))
    return str(value or "outlook").strip().lower() or "outlook"


def _business_mail_snapshot(account) -> dict:
    """Mailbox credentials stay local; Gmail carries only its immutable binding."""
    from services.gmail_plan_support import account_mail_provider, gmail_binding_extra
    return {
        "email": account.email,
        "password": account.password or "",
        "client_id": account.client_id or "",
        "refresh_token": account.refresh_token or "",
        "mail_access_type": account.mail_access_type or "",
        "mail_provider": account_mail_provider(account),
        **gmail_binding_extra(account),
    }


def _run_ms_web_login_task(
    task_id: str,
    account_id: int,
    email: str,
    password: str,
    *,
    proxy: str,
    headless: bool,
) -> None:
    """后台执行 Outlook 网页登录并将结果写入任务注册表。"""
    def _log(message: Any) -> None:
        _ms_web_log(task_id, message, password=password, proxy=proxy)

    try:
        # 延迟导入，便于测试替换真实浏览器自动化函数。
        from platforms.chatgpt.gpt_pro_login import run_ms_web_login

        result = run_ms_web_login(
            email,
            password,
            proxy=proxy,
            headless=bool(headless),
            log_fn=_log,
        )
        payload = result if isinstance(result, dict) else {}
        stage = str(payload.get("stage") or "").strip().lower()
        url = str(payload.get("url") or "")
        if bool(payload.get("ok")) and stage in {"logged_in", "needs_manual"}:
            _ms_web_finish(
                task_id,
                status=stage,
                stage=stage,
                url=url,
                result=payload,
                password=password,
                proxy=proxy,
            )
        else:
            # 自动化函数报告 ok=False、返回空值或未知 stage 均视为失败。
            message = str(payload.get("error") or payload.get("message") or "微软网页登录未完成")
            _log(f"[MS登录] 未完成: {message}")
            _ms_web_finish(
                task_id,
                status="failed",
                stage=stage or "failed",
                url=url,
                result=payload,
                error=message,
                password=password,
                proxy=proxy,
            )
    except Exception as exc:
        _log(f"[MS登录] 异常: {exc}")
        _ms_web_finish(
            task_id,
            status="failed",
            stage="exception",
            error=str(exc),
            password=password,
            proxy=proxy,
        )


# ── 列表 & 统计 ──────────────────────────────────────────────

_BUSINESS_LOGIN_STATES = {"logged", "never_logged"}


def _normalize_business_login_state(value: Optional[str]) -> str:
    state = str(value or "").strip().lower()
    if state and state not in _BUSINESS_LOGIN_STATES:
        raise HTTPException(400, "login_state 只能是 logged 或 never_logged")
    return state


def _business_has_saved_cookie_predicate():
    return or_(
        GptBusinessAccountModel.cookie_updated_at.is_not(None),  # type: ignore[union-attr]
        func.length(func.trim(func.coalesce(
            GptBusinessAccountModel.cookie_blob, "",
        ))) > 0,
    )


def _apply_business_account_list_filters(
    query,
    *,
    keyword: Optional[str] = None,
    mail_access_type: Optional[str] = None,
    enabled: Optional[bool] = None,
    refund_status: Optional[str] = None,
    exclude_refund_pending: Optional[bool] = None,
    login_state: Optional[str] = None,
):
    """Keep list and destructive "delete current filter" semantics identical."""
    if keyword:
        query = query.where(col(GptBusinessAccountModel.email).contains(keyword))
    if mail_access_type is not None:
        query = query.where(GptBusinessAccountModel.mail_access_type == mail_access_type)
    if enabled is not None:
        query = query.where(GptBusinessAccountModel.enabled == enabled)
    if refund_status is not None and refund_status != "":
        query = query.where(GptBusinessAccountModel.refund_status == refund_status)
    if exclude_refund_pending:
        query = query.where(
            func.coalesce(GptBusinessAccountModel.refund_status, "")
            != "refunded_pending_credit"
        )
    state = _normalize_business_login_state(login_state)
    if state == "logged":
        query = query.where(_business_has_saved_cookie_predicate())
    elif state == "never_logged":
        query = query.where(~_business_has_saved_cookie_predicate())
    return query

@router.get("/accounts")
def list_gpt_business_accounts(
    page: int = Query(1, ge=1),
    page_size: int = Query(50, ge=1, le=500),
    keyword: Optional[str] = Query(None),
    mail_access_type: Optional[str] = Query(None),
    enabled: Optional[bool] = Query(None),
    refund_status: Optional[str] = Query(None, description="按退款状态过滤,如 refunded_pending_credit"),
    exclude_refund_pending: Optional[bool] = Query(None, description="True=排除已退款未到账账号(用于已登录等非退款视图)"),
    login_state: Optional[str] = Query(None, description="logged=曾保存 Cookie；never_logged=从未保存 Cookie"),
    account_id: Optional[int] = Query(None, ge=1, description="按本地母号 ID 精确定位"),
):
    with Session(engine) as session:
        query = _apply_business_account_list_filters(
            select(GptBusinessAccountModel),
            keyword=keyword,
            mail_access_type=mail_access_type,
            enabled=enabled,
            refund_status=refund_status,
            exclude_refund_pending=exclude_refund_pending,
            login_state=login_state,
        )
        # FastAPI resolves Query(None) to int/None over HTTP.  Direct internal
        # callers and unit tests receive the Query metadata object when they
        # omit this optional argument, which must behave like None.
        resolved_account_id = (
            int(account_id)
            if isinstance(account_id, int) and not isinstance(account_id, bool)
            else None
        )
        if resolved_account_id is not None:
            # Deep links are ID-only.  A stale ID must return an empty page;
            # never fall back to an email/keyword match and risk opening the
            # wrong BUSINESS mother.
            query = query.where(GptBusinessAccountModel.id == resolved_account_id)

        total = session.exec(select(func.count()).select_from(query.subquery())).one()
        items_query = query.order_by(col(GptBusinessAccountModel.id).desc())
        items_query = items_query.offset((page - 1) * page_size).limit(page_size)
        items = session.exec(items_query).all()
        # 候选池完全来自本地数据库，而且所有母号共享同一批“当前可用”账号；
        # 每页只计算一次，避免为了决定按钮状态逐个请求母号或远端 workspace。
        invite_candidate_summary = _database_business_invite_candidate_summary(session)
        replenishments = _latest_replenishments_by_parent(
            session,
            [int(acc.id or 0) for acc in items],
        )
        return {
            "total": total,
            "page": page,
            "page_size": page_size,
            # 列表恢复只读取本地数据库：完整 workspace 快照来自最近一次人工
            # 刷新，历史操作审计则根据持久化流水实时重算，绝不请求 OpenAI。
            "items": [
                _serialize_business_account_with_workspace_cache(
                    session,
                    acc,
                    invite_candidate_summary=invite_candidate_summary,
                    replenishment=replenishments.get(int(acc.id or 0)),
                )
                for acc in items
            ],
        }


@router.get("/accounts/stats")
def gpt_business_stats():
    with Session(engine) as session:
        total = session.exec(select(func.count()).select_from(GptBusinessAccountModel)).one()
        logged_count = session.exec(
            select(func.count()).select_from(GptBusinessAccountModel)
            .where(_business_has_saved_cookie_predicate())
        ).one()
        # “已登录”Tab 会把已退款未到账账号移到独立退款工作区；单独返回与
        # 该 Tab 完全一致的数量，同时保留 logged 原有的“所有曾登录账号”语义。
        logged_excluding_refund_pending_count = session.exec(
            select(func.count()).select_from(GptBusinessAccountModel)
            .where(_business_has_saved_cookie_predicate())
            .where(
                func.coalesce(GptBusinessAccountModel.refund_status, "")
                != "refunded_pending_credit"
            )
        ).one()
        never_logged_count = session.exec(
            select(func.count()).select_from(GptBusinessAccountModel)
            .where(~_business_has_saved_cookie_predicate())
        ).one()
        enabled_count = session.exec(
            select(func.count()).select_from(GptBusinessAccountModel)
            .where(GptBusinessAccountModel.enabled == True)  # noqa: E712
        ).one()
        dangerous_count = session.exec(
            select(func.count()).select_from(GptBusinessAccountModel)
            .where(GptBusinessAccountModel.dangerous == True)  # noqa: E712
        ).one()
        policy_warning_count = session.exec(
            select(func.count()).select_from(GptBusinessAccountModel)
            .where(GptBusinessAccountModel.policy_warning == True)  # noqa: E712
        ).one()
        untyped_count = session.exec(
            select(func.count()).select_from(GptBusinessAccountModel)
            .where(GptBusinessAccountModel.mail_access_type == "")
        ).one()
        return {
            "total": total,
            "logged": logged_count,
            "logged_excluding_refund_pending": logged_excluding_refund_pending_count,
            "never_logged": never_logged_count,
            "enabled": enabled_count,
            "disabled": total - enabled_count,
            "dangerous": dangerous_count,
            "policy_warning": policy_warning_count,
            "untyped": untyped_count,
        }


