@router.get("/accounts/export")
def export_gpt_business_accounts(
    keyword: Optional[str] = Query(None),
    mail_access_type: Optional[str] = Query(None),
    enabled: Optional[bool] = Query(None),
    refund_status: Optional[str] = Query(None),
    exclude_refund_pending: Optional[bool] = Query(None),
    login_state: Optional[str] = Query(None),
):
    with Session(engine) as session:
        query = _apply_business_account_list_filters(
            select(GptBusinessAccountModel),
            keyword=keyword,
            mail_access_type=mail_access_type,
            enabled=enabled,
            refund_status=refund_status,
            exclude_refund_pending=exclude_refund_pending,
            login_state=login_state,
        )
        accounts = session.exec(query.order_by(col(GptBusinessAccountModel.id))).all()

    lines = []
    for acc in accounts:
        parts = [acc.email, acc.password]
        if acc.refresh_token or acc.client_id:
            parts.extend([acc.refresh_token, acc.client_id, acc.mail_access_type or ""])
        lines.append("----".join(parts))
    return {"total": len(lines), "data": "\n".join(lines)}


# ── 单条操作 ─────────────────────────────────────────────────

def _delete_business_binding_policies(
    session: Session,
    parent_ids: List[int],
) -> int:
    """Delete local-only device bindings with their deleted mother rows.

    This is deliberately a database cascade only.  It never contacts a device,
    removes a child, or creates a cleanup/migration job.
    """
    wanted = sorted({int(value) for value in parent_ids if int(value) > 0})
    if not wanted:
        return 0
    rows = session.exec(
        select(GptBusinessAutomationPolicyModel).where(
            GptBusinessAutomationPolicyModel.business_account_id.in_(wanted)  # type: ignore[union-attr]
        )
    ).all()
    for row in rows:
        session.delete(row)
    return len(rows)

@router.get("/accounts/{account_id}")
def get_gpt_business_account(account_id: int):
    with Session(engine) as session:
        acc = session.get(GptBusinessAccountModel, account_id)
        if not acc:
            raise HTTPException(404, "账号不存在")
        item = _serialize(acc)
        item["invite_quota"] = _invite_quota(session, account_id)
        return item


@router.put("/accounts/{account_id}")
def update_gpt_business_account(account_id: int, body: GptBusinessAccountUpdateRequest):
    with Session(engine) as session:
        if body.enabled is not None:
            acc = _lock_business_parent_state_mutation(session, [account_id]).get(account_id)
        else:
            acc = session.get(GptBusinessAccountModel, account_id)
        if not acc:
            raise HTTPException(404, "账号不存在")
        for field_name in (
            "password", "client_id", "refresh_token", "mail_access_type",
            "note", "enabled",
        ):
            value = getattr(body, field_name, None)
            if value is not None:
                setattr(acc, field_name, value)
        # business_upgraded_at: 单独处理(字符串 → datetime; 空串 = 清空)
        if body.business_upgraded_at is not None:
            text = str(body.business_upgraded_at).strip()
            if not text:
                acc.business_upgraded_at = None
            else:
                try:
                    if text.endswith("Z"):
                        text = text[:-1] + "+00:00"
                    dt = datetime.fromisoformat(text)
                    acc.business_upgraded_at = dt if dt.tzinfo else dt.replace(tzinfo=timezone.utc)
                except Exception:
                    raise HTTPException(400, f"无法解析升级时间: {body.business_upgraded_at}")
        acc.updated_at = _utcnow()
        session.add(acc)
        session.commit()
        session.refresh(acc)
        item = _serialize(acc)
        item["invite_quota"] = _invite_quota(session, account_id)
        return item


@router.delete("/accounts/{account_id}")
def delete_gpt_business_account(account_id: int):
    cpa_child_ids: List[int] = []
    purge_candidates: list[tuple[int, int, str]] = []
    with Session(engine) as session:
        acc = _lock_business_parent_state_mutation(session, [account_id]).get(account_id)
        if not acc:
            raise HTTPException(404, "账号不存在")
        _assert_no_active_children_before_parent_delete(session, [account_id])
        purge_candidates = _released_dead_children_for_parent_delete(
            session, [account_id],
        )
        _release_all_managed_children(session, [account_id], cpa_child_ids)
        _delete_business_binding_policies(session, [account_id])
        session.delete(acc)
        session.commit()
    _disable_released_children_cpa(cpa_child_ids, reason="business_parent_deleted")
    for child_id, parent_id, child_email in purge_candidates:
        _purge_released_dead_business_child_best_effort(
            child_id, parent_id=parent_id, email=child_email,
        )
    return {"ok": True}


# ── 批量操作 ─────────────────────────────────────────────────

@router.post("/accounts/batch-delete")
def batch_delete_gpt_business(body: GptBusinessBatchDeleteRequest):
    deleted = 0
    cpa_child_ids: List[int] = []
    purge_candidates: list[tuple[int, int, str]] = []
    with Session(engine) as session:
        parents = _lock_business_parent_state_mutation(session, body.ids)
        existing_ids = sorted(parents)
        _assert_no_active_children_before_parent_delete(session, existing_ids)
        purge_candidates = _released_dead_children_for_parent_delete(
            session, existing_ids,
        )
        _release_all_managed_children(session, existing_ids, cpa_child_ids)
        _delete_business_binding_policies(session, existing_ids)
        for aid in existing_ids:
            acc = session.get(GptBusinessAccountModel, aid)
            if acc:
                session.delete(acc)
                deleted += 1
        session.commit()
    _disable_released_children_cpa(cpa_child_ids, reason="business_parent_deleted")
    for child_id, parent_id, child_email in purge_candidates:
        _purge_released_dead_business_child_best_effort(
            child_id, parent_id=parent_id, email=child_email,
        )
    return {"deleted": deleted}


@router.post("/accounts/batch-update")
def batch_update_gpt_business(body: GptBusinessBatchUpdateRequest):
    updated = 0
    with Session(engine) as session:
        locked = (
            _lock_business_parent_state_mutation(session, body.ids)
            if body.enabled is not None else {}
        )
        for aid in body.ids:
            acc = locked.get(int(aid)) if body.enabled is not None else session.get(
                GptBusinessAccountModel, aid,
            )
            if not acc:
                continue
            if body.note is not None:
                acc.note = body.note
            if body.enabled is not None:
                acc.enabled = body.enabled
            acc.updated_at = _utcnow()
            session.add(acc)
            updated += 1
        session.commit()
    return {"updated": updated}


@router.post("/accounts/delete-all")
def delete_all_gpt_business(
    keyword: Optional[str] = Query(None),
    mail_access_type: Optional[str] = Query(None),
    enabled: Optional[bool] = Query(None),
    refund_status: Optional[str] = Query(None),
    exclude_refund_pending: Optional[bool] = Query(None),
    login_state: Optional[str] = Query(None),
):
    cpa_child_ids: List[int] = []
    purge_candidates: list[tuple[int, int, str]] = []
    with Session(engine) as session:
        query = _apply_business_account_list_filters(
            select(GptBusinessAccountModel),
            keyword=keyword,
            mail_access_type=mail_access_type,
            enabled=enabled,
            refund_status=refund_status,
            exclude_refund_pending=exclude_refund_pending,
            login_state=login_state,
        )
        accounts = session.exec(query).all()
        locked = _lock_business_parent_state_mutation(
            session,
            [int(acc.id) for acc in accounts if acc.id is not None],
        )
        accounts = [locked[int(acc.id)] for acc in accounts if int(acc.id) in locked]
        deleted = len(accounts)
        _assert_no_active_children_before_parent_delete(
            session, [int(acc.id) for acc in accounts if acc.id is not None])
        purge_candidates = _released_dead_children_for_parent_delete(
            session, [int(acc.id) for acc in accounts if acc.id is not None],
        )
        _release_all_managed_children(
            session, [int(acc.id) for acc in accounts if acc.id is not None], cpa_child_ids)
        _delete_business_binding_policies(
            session, [int(acc.id) for acc in accounts if acc.id is not None])
        for acc in accounts:
            session.delete(acc)
        session.commit()
    _disable_released_children_cpa(cpa_child_ids, reason="business_parent_deleted")
    for child_id, parent_id, child_email in purge_candidates:
        _purge_released_dead_business_child_best_effort(
            child_id, parent_id=parent_id, email=child_email,
        )
    return {"deleted": deleted}


# ── 批量导入(后台任务) ────────────────────────────────────────

_UUID_RE = re.compile(
    r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$",
    re.IGNORECASE,
)


def _execute_gpt_business_batch_import(task_id: str, request: GptBusinessBatchImportRequest) -> None:
    _import_task_store.mark_running(task_id)

    lines = (request.data or "").splitlines()
    processed = 0
    success = 0
    failed = 0

    try:
        for idx, raw_line in enumerate(lines, start=1):
            line = str(raw_line or "").strip()
            if not line or line.startswith("#"):
                continue

            error_message = ""
            parts = [p.strip() for p in line.split("----")]

            email = ""
            password = ""
            refresh_token = ""
            client_id = ""

            if len(parts) == 2:
                email, password = parts
            elif len(parts) >= 4:
                email, password, third, fourth = parts[0], parts[1], parts[2], parts[3]
                if _UUID_RE.match(third) and not _UUID_RE.match(fourth):
                    client_id, refresh_token = third, fourth
                else:
                    refresh_token, client_id = third, fourth
            else:
                failed += 1
                error_message = (
                    f"行 {idx}: 格式错误,应为 邮箱----密码 或 "
                    f"邮箱----密码----refresh_token----client_id"
                )

            if not error_message:
                if not email or "@" not in email:
                    failed += 1
                    error_message = f"行 {idx}: 无效的邮箱地址: {email}"
                else:
                    try:
                        # 入库 + 自动 probe mail_access_type (有 OAuth 凭证时)
                        # probe 失败不影响入库 success, 只是 mail_access_type 留空
                        probed_type = ""
                        if client_id and refresh_token:
                            try:
                                from core.outlook_probe import classify_mail_access_type
                                probed_type = classify_mail_access_type(
                                    email, refresh_token, client_id,
                                ) or ""
                            except Exception:
                                probed_type = ""
                        with Session(engine) as session:
                            existing = session.exec(
                                select(GptBusinessAccountModel)
                                .where(GptBusinessAccountModel.email == email)
                            ).first()
                            if existing:
                                existing = _lock_business_parent_state_mutation(
                                    session, [int(existing.id)],
                                ).get(int(existing.id))
                                if not existing:
                                    raise HTTPException(404, "账号不存在")
                                existing.password = password or existing.password
                                if refresh_token:
                                    existing.refresh_token = refresh_token
                                if client_id:
                                    existing.client_id = client_id
                                if probed_type and not existing.mail_access_type:
                                    existing.mail_access_type = probed_type
                                existing.enabled = bool(request.enabled)
                                existing.updated_at = _utcnow()
                                session.add(existing)
                            else:
                                account = GptBusinessAccountModel(
                                    email=email,
                                    password=password,
                                    refresh_token=refresh_token,
                                    client_id=client_id,
                                    mail_access_type=probed_type,
                                    enabled=bool(request.enabled),
                                    created_at=_utcnow(),
                                    updated_at=_utcnow(),
                                )
                                session.add(account)
                            session.commit()
                        success += 1
                    except Exception as e:
                        failed += 1
                        error_message = f"行 {idx}: 入库失败: {e}"

            processed += 1
            _import_task_store.update(
                task_id,
                processed=processed,
                success=success,
                failed=failed,
                append_error=error_message or None,
            )

        _import_task_store.finish(task_id, status="done")
    except Exception as e:
        _import_task_store.fail(task_id, f"导入任务异常: {e}")


@router.post("/batch-import")
def batch_import_gpt_business(request: GptBusinessBatchImportRequest):
    """批量导入 GPT BUSINESS 账号。

    格式(每行一个,字段用 ---- 分隔):
        邮箱----密码
      或
        邮箱----密码----refresh_token----client_id
      或
        邮箱----密码----client_id----refresh_token  (UUID 自动识别)
    """
    total = _count_import_lines(request.data)
    task_id = f"gpt_business_import_{int(time.time() * 1000)}"
    _import_task_store.create(task_id, total=total)
    thread = threading.Thread(
        target=_execute_gpt_business_batch_import,
        args=(task_id, request),
        daemon=True,
        name=f"gpt-business-import-{task_id}",
    )
    thread.start()
    return {"task_id": task_id, "total": total}


