# ── 取码类型探测 ─────────────────────────────────────────────

@router.post("/accounts/probe-untyped")
def probe_untyped_accounts():
    """一键探测所有 mail_access_type 为空且有 OAuth 凭证的账号。

    使用 ThreadPoolExecutor 并发跑 (max_workers=8)。返回 {total, ok, failed, items}.
    """
    from concurrent.futures import ThreadPoolExecutor, as_completed
    from core.outlook_probe import classify_mail_access_type

    with Session(engine) as session:
        rows = session.exec(
            select(GptBusinessAccountModel)
            .where(
                (GptBusinessAccountModel.mail_access_type == None)  # noqa: E711
                | (GptBusinessAccountModel.mail_access_type == "")
            )
            .where(col(GptBusinessAccountModel.client_id) != "")
            .where(col(GptBusinessAccountModel.refresh_token) != "")
        ).all()
        candidates = [
            (acc.id, acc.email, acc.refresh_token, acc.client_id) for acc in rows
        ]
    if not candidates:
        return {"total": 0, "ok": 0, "failed": 0, "items": []}

    def _probe(item):
        aid, email, rt, cid = item
        try:
            return aid, email, classify_mail_access_type(email, rt, cid)
        except Exception:
            return aid, email, None

    results: list[dict] = []
    with ThreadPoolExecutor(max_workers=8) as pool:
        futures = [pool.submit(_probe, c) for c in candidates]
        for fut in as_completed(futures):
            aid, email, mt = fut.result()
            results.append({
                "id": aid,
                "email": email,
                "mail_access_type": mt or "",
                "ok": bool(mt),
            })

    ok_count = 0
    with Session(engine) as session:
        for r in results:
            if not r["ok"]:
                continue
            acc = session.get(GptBusinessAccountModel, r["id"])
            if not acc:
                continue
            acc.mail_access_type = r["mail_access_type"]
            acc.updated_at = _utcnow()
            session.add(acc)
            ok_count += 1
        session.commit()

    return {
        "total": len(results),
        "ok": ok_count,
        "failed": len(results) - ok_count,
        "items": results,
    }


# ── 取件辅助(供邮件监控复用) ─────────────────────────────────

def _build_mailbox_account(acc: GptBusinessAccountModel):
    """把 GptBusinessAccountModel 转成 OutlookMailbox 使用的 MailboxAccount。"""
    from core.base_mailbox import MailboxAccount

    return MailboxAccount(
        email=acc.email,
        account_id=str(acc.id or ""),
        extra={
            "provider": "outlook",
            "password": acc.password or "",
            "client_id": acc.client_id or "",
            "refresh_token": acc.refresh_token or "",
            "mail_access_type": acc.mail_access_type or "",
        },
    )


def _fetch_via_graph(mailbox, mb_account, limit: int) -> List[Dict[str, Any]]:
    """复用 OutlookMailbox._fetch_graph_messages,返回最近 limit 封。"""
    messages = mailbox._fetch_graph_messages(mb_account, top=max(1, min(limit, 50)))
    out: List[Dict[str, Any]] = []
    for m in messages:
        body = str(m.get("body") or "")
        is_html = "<html" in body.lower() or "<body" in body.lower() or "<div" in body.lower()
        out.append({
            "id": str(m.get("id") or ""),
            "from": str(m.get("from") or ""),
            "subject": str(m.get("subject") or ""),
            "preview": str(m.get("preview") or ""),
            "body": body,
            "is_html": is_html,
            "time": str(m.get("time") or ""),
            "folder": "",
        })
    out.sort(key=lambda x: x.get("time", ""), reverse=True)
    return out[:limit]


def _looks_like_html_body(value: str) -> bool:
    """兜底识别被邮件服务器错误标注为纯文本的 HTML 正文。"""
    text = str(value or "").lstrip().lower()
    return text.startswith((
        "<!doctype html", "<html", "<head", "<body", "<style", "<table",
    ))


def _fetch_via_imap(mailbox, mb_account, limit: int, folders: List[str]) -> List[Dict[str, Any]]:
    """通过 IMAP 读取 INBOX / Junk 最近 limit 封邮件。"""
    from email import message_from_bytes
    from email.policy import default as email_default_policy
    from email.utils import parseaddr

    imap_conn = mailbox._open_imap(mb_account)
    out: List[Dict[str, Any]] = []
    try:
        for folder in folders:
            try:
                status, _ = imap_conn.select(folder, readonly=True)
                if status != "OK":
                    continue
                status, data = imap_conn.uid("search", None, "ALL")
                if status != "OK":
                    continue
                ids = data[0].split() if data and data[0] else []
                ids = ids[-max(1, min(limit, 50)):]
                for uid in reversed(ids):
                    uid_str = uid.decode("utf-8", errors="ignore") if isinstance(uid, bytes) else str(uid)
                    status, msg_data = imap_conn.uid("fetch", uid, "(RFC822)")
                    if status != "OK":
                        continue
                    raw = None
                    for item in msg_data or []:
                        if isinstance(item, tuple) and item[1]:
                            raw = item[1]
                            break
                    if not raw:
                        continue
                    msg = message_from_bytes(raw, policy=email_default_policy)
                    subject = mailbox._decode_header_value(msg.get("Subject", ""))
                    sender_name, sender_addr = parseaddr(str(msg.get("From", "")))
                    date_str = str(msg.get("Date", ""))

                    plain_chunks: List[str] = []
                    html_chunks: List[str] = []
                    if msg.is_multipart():
                        for part in msg.walk():
                            ctype = part.get_content_type()
                            if ctype not in ("text/plain", "text/html"):
                                continue
                            payload = part.get_payload(decode=True)
                            if payload is None:
                                continue
                            charset = part.get_content_charset() or "utf-8"
                            try:
                                text = payload.decode(charset, errors="ignore")
                            except Exception:
                                text = payload.decode("utf-8", errors="ignore")
                            if ctype == "text/html":
                                html_chunks.append(text)
                            else:
                                plain_chunks.append(text)
                    else:
                        payload = msg.get_payload(decode=True)
                        ctype = (msg.get_content_type() or "").lower()
                        if isinstance(payload, bytes):
                            charset = msg.get_content_charset() or "utf-8"
                            try:
                                text = payload.decode(charset, errors="ignore")
                            except (LookupError, UnicodeDecodeError):
                                text = payload.decode("utf-8", errors="ignore")
                        elif payload:
                            text = str(payload)
                        else:
                            text = ""
                        if text:
                            if ctype == "text/html":
                                html_chunks.append(text)
                            else:
                                plain_chunks.append(text)

                    body_html = "\n".join(html_chunks).strip()
                    body_text = "\n".join(plain_chunks).strip()
                    # 少数邮件服务器会把完整 HTML 错标为 text/plain；避免前端
                    # 把 <html> 标签当普通文本显示。
                    if not body_html and _looks_like_html_body(body_text):
                        body_html, body_text = body_text, ""
                    body = body_html or body_text
                    is_html = bool(body_html)
                    preview = (body_text or body)[:200].replace("\n", " ").strip()

                    out.append({
                        "id": uid_str,
                        "from": sender_addr or sender_name,
                        "subject": subject,
                        "preview": preview,
                        "body": body,
                        "is_html": is_html,
                        "time": date_str,
                        "folder": folder,
                    })
            except Exception:
                continue
    finally:
        try:
            imap_conn.logout()
        except Exception:
            pass

    return out[:limit]


# ── 邮件监控(精简:仅 inbox + 铃铛报警 + dangerous/policy_warning,无退款)──

MAX_SEEN_IDS = 100
MAX_ALERTS_PER_ACCOUNT = 20
MAX_INBOX_PER_ACCOUNT = 100
MAX_FETCH_PER_ROUND = 15

# 封号(账号已停用)主题关键词 — 中英双语(OpenAI 2026 起对中文用户发中文封号邮件,
# 主题如 "OpenAI - 访问权限已停用 [C-xxxx]")。
DANGEROUS_SUBJECT_KEYWORDS = ("Access Deactivated", "访问权限已停用")
POLICY_WARNING_SUBJECT_KEYWORDS = (
    "Usage Policy Violation", "Deactivation Warning", "使用政策", "停用警告",
)
# 铃铛白名单: 只有 subject 含这些关键字的新邮件才推到 pending_alerts。
BELL_SUBJECT_KEYWORDS = DANGEROUS_SUBJECT_KEYWORDS

# 「升级 BUSINESS」确认邮件关键词(命中即用该邮件收件时间回填 business_upgraded_at)。
# 命中范围是 主题 + 正文/预览(确认文案在正文里, 如「你已成功创建 ChatGPT Business 工作空间」)。
# 可在配置里用 gpt_business_upgrade_subject_keywords(逗号分隔)覆盖。
_BUSINESS_UPGRADE_KEYWORDS_KEY = "gpt_business_upgrade_subject_keywords"
_DEFAULT_BUSINESS_UPGRADE_KEYWORDS = (
    "成功创建 ChatGPT Business",
    "ChatGPT Business 工作空间",
    "created a ChatGPT Business",       # 英文文案兜底
    "Welcome to ChatGPT Business",
)


def _business_upgrade_keywords() -> tuple:
    """升级确认邮件关键词(配置优先, 逗号分隔; 未配置用默认)。"""
    try:
        from core.config_store import config_store
        raw = str(config_store.get(_BUSINESS_UPGRADE_KEYWORDS_KEY, "") or "").strip()
    except Exception:
        raw = ""
    if raw:
        kws = tuple(k.strip() for k in raw.split(",") if k.strip())
        if kws:
            return kws
    return _DEFAULT_BUSINESS_UPGRADE_KEYWORDS


def _detect_business_upgrade_time(messages: List[Dict[str, Any]]) -> Optional[datetime]:
    """在邮件里找升级确认邮件(主题/正文/预览命中关键词), 返回最早一封的收件时间。

    确认文案通常在正文里, 所以同时扫 subject + preview + body。取最早一封 = 首次升级时刻。
    """
    upgrade_kws = _business_upgrade_keywords()
    best_dt: Optional[datetime] = None
    for msg in messages:
        haystack = " ".join([
            str(msg.get("subject") or ""),
            str(msg.get("preview") or ""),
            str(msg.get("body") or ""),
        ])
        if any(kw in haystack for kw in upgrade_kws):
            dt = _parse_mail_time(msg.get("time"))
            if dt is not None and (best_dt is None or dt < best_dt):
                best_dt = dt
    return best_dt


def _maybe_fill_upgrade_time(account: GptBusinessAccountModel, messages: List[Dict[str, Any]]) -> str:
    """若升级时间为空且命中确认邮件, 就地回填(不 commit, 由调用方提交)。返回回填的 ISO 值或 ""。"""
    if account.business_upgraded_at is not None:
        return ""
    dt = _detect_business_upgrade_time(messages)
    if dt is None:
        return ""
    account.business_upgraded_at = dt
    account.updated_at = _utcnow()
    return dt.isoformat()


def _parse_mail_time(value: Any) -> Optional[datetime]:
    """把邮件的 time 字段(ISO 8601 或 RFC 2822)解析成带时区的 datetime, 失败返回 None。"""
    text = str(value or "").strip()
    if not text:
        return None
    # 1) ISO 8601 (Graph 常见: 2026-07-28T15:04:05Z / +00:00)
    try:
        iso = text[:-1] + "+00:00" if text.endswith("Z") else text
        dt = datetime.fromisoformat(iso)
        return dt if dt.tzinfo else dt.replace(tzinfo=timezone.utc)
    except Exception:
        pass
    # 2) RFC 2822 (IMAP 常见: Mon, 28 Jul 2026 15:04:05 +0000)
    try:
        from email.utils import parsedate_to_datetime
        dt = parsedate_to_datetime(text)
        if dt is not None:
            return dt if dt.tzinfo else dt.replace(tzinfo=timezone.utc)
    except Exception:
        pass
    return None


_monitor_lock = threading.Lock()


def _safe_json_loads(text: str, default):
    if not text:
        return default
    try:
        return json.loads(text)
    except Exception:
        return default


def _fetch_recent(account: GptBusinessAccountModel) -> List[Dict[str, Any]]:
    """按 mail_access_type 取最近邮件,返回标准化 message list。"""
    # BUSINESS 导入也会携带 iCloud/HME 别名。原实现无条件
    # 构建 OutlookMailbox，导致这类母号虽被定时器选中，每轮却
    # 只能失败。复用 PRO 已验证的 QQ/iCloud 别名取件分发，
    # 让来源 owner 在两个界面都只保留一份队列。
    from api.gpt_plan_operations import _mail_provider_of

    if _mail_provider_of(account) == "gmail":
        from api.gpt_plan_operations import _fetch_gmail_recent
        return _fetch_gmail_recent(account, MAX_FETCH_PER_ROUND)

    if _mail_provider_of(account) == "icloud":
        from api.gpt_plan_operations import _fetch_icloud_recent

        return _fetch_icloud_recent(account, MAX_FETCH_PER_ROUND)

    from core.base_mailbox import OutlookMailbox

    mailbox = OutlookMailbox(platform="")
    mb_account = _build_mailbox_account(account)
    mail_type = (account.mail_access_type or "").strip().lower()

    # Graph 优先(只要有 OAuth)
    if mail_type == "graph" or (mail_type == "" and account.client_id and account.refresh_token):
        try:
            return _fetch_via_graph(mailbox, mb_account, MAX_FETCH_PER_ROUND)
        except Exception as exc:
            graph_err = f"Graph: {exc}"
            if mail_type == "graph":
                raise RuntimeError(graph_err) from exc

    # IMAP 兜底
    if mail_type in ("imap_pop", "") and (account.password or (account.client_id and account.refresh_token)):
        return _fetch_via_imap(mailbox, mb_account, MAX_FETCH_PER_ROUND, ["INBOX", "Junk"])

    raise RuntimeError("无可用取件方式(缺少 OAuth/密码)")


def _make_alert(msg: Dict[str, Any]) -> Dict[str, Any]:
    """从邮件 dict 中抽出 alert 元数据(不存正文)。"""
    return {
        "id": str(msg.get("id") or ""),
        "from": str(msg.get("from") or ""),
        "subject": str(msg.get("subject") or ""),
        "preview": str(msg.get("preview") or "")[:300],
        "time": str(msg.get("time") or ""),
        "folder": str(msg.get("folder") or ""),
        "is_html": bool(msg.get("is_html")),
        "detected_at": _utcnow().isoformat(),
    }


def _process_business_account(account: GptBusinessAccountModel) -> Dict[str, Any]:
    """对单个 BUSINESS 账号执行一轮监控(无退款逻辑),返回本轮统计。"""
    seen_ids: List[str] = _safe_json_loads(account.seen_mail_ids_json, [])
    seen_set = set(seen_ids)
    pending: List[Dict[str, Any]] = _safe_json_loads(account.pending_alerts_json, [])
    inbox: List[Dict[str, Any]] = _safe_json_loads(account.pending_inbox_json, [])

    messages = _fetch_recent(account)
    fresh_ids = [str(m.get("id") or "") for m in messages if m.get("id")]

    # 危险账号检测: subject 命中封号关键词(中英)→ dangerous=True (不受 first_scan 限制)
    if not account.dangerous:
        for msg in messages:
            subj = str(msg.get("subject") or "")
            if any(kw in subj for kw in DANGEROUS_SUBJECT_KEYWORDS):
                account.dangerous = True
                account.dangerous_detected_at = _utcnow()
                break

    # 政策告警检测: subject 命中政策告警关键词(中英)→ policy_warning=True
    if not account.policy_warning:
        for msg in messages:
            subj = str(msg.get("subject") or "")
            if any(kw in subj for kw in POLICY_WARNING_SUBJECT_KEYWORDS):
                account.policy_warning = True
                account.policy_warning_detected_at = _utcnow()
                break

    # 退款邮件检测: subject 命中退款模板 → refund_status=refunded_pending_credit(已退款未到账)
    # 复用 GPT PRO 的退款主题模板;已到账(refund_credited)不再改动。
    # ⚠️ 只认「当前订阅开始之后」到达的退款邮件 —— 这些账号收件箱里常有上一订阅周期
    #   的历史退款邮件(几个月前),不能据此把当前活跃订阅误标成已退款。
    if getattr(account, "refund_status", "") != "refund_credited":
        try:
            from services.chatgpt_mail_common import REFUND_SUBJECT_PATTERNS
            from email.utils import parsedate_to_datetime
            # 阈值: 当前订阅起始(升级时间); 没有就退回导入时间。二者都无则不自动标记。
            threshold = account.business_upgraded_at or account.created_at
            for msg in messages:
                subj = str(msg.get("subject") or "")
                if not any(pat in subj for pat in REFUND_SUBJECT_PATTERNS):
                    continue
                mt = None
                try:
                    mt = parsedate_to_datetime(str(msg.get("time") or "")).replace(tzinfo=None)
                except Exception:
                    mt = None
                # 必须能解析出邮件时间, 且晚于阈值, 才算当前订阅的退款
                if threshold is not None and mt is not None and mt > threshold:
                    if account.refund_status != "refunded_pending_credit":
                        account.refund_status = "refunded_pending_credit"
                        account.refund_detected_at = _utcnow()
                    break
        except Exception:
            pass

    # 升级 BUSINESS 时间自动回填: 仅当当前为空时, 命中确认邮件 → 用该邮件收件时间。
    # 不受 first_scan 限制(确认邮件通常在导入前就已到达)。
    if account.business_upgraded_at is None:
        best_dt = _detect_business_upgrade_time(messages)
        if best_dt is not None:
            account.business_upgraded_at = best_dt

    # 首次扫描: 全部视为已见,不产生任何 alert / inbox
    first_scan = not seen_ids
    new_alerts: List[Dict[str, Any]] = []
    new_inbox: List[Dict[str, Any]] = []
    if not first_scan:
        for msg in messages:
            mid = str(msg.get("id") or "")
            if not mid or mid in seen_set:
                continue
            subj = str(msg.get("subject") or "")
            alert = _make_alert(msg)
            if any(kw in subj for kw in BELL_SUBJECT_KEYWORDS):
                new_alerts.append(alert)
            new_inbox.append(alert)

    if new_alerts:
        existing_keys = {a.get("id") for a in pending if a.get("id")}
        for alert in new_alerts:
            if alert.get("id") not in existing_keys:
                pending.insert(0, alert)
                existing_keys.add(alert.get("id"))
        if len(pending) > MAX_ALERTS_PER_ACCOUNT:
            pending = pending[:MAX_ALERTS_PER_ACCOUNT]

    if new_inbox:
        existing_inbox_keys = {a.get("id") for a in inbox if a.get("id")}
        for alert in new_inbox:
            if alert.get("id") not in existing_inbox_keys:
                inbox.insert(0, alert)
                existing_inbox_keys.add(alert.get("id"))
        if len(inbox) > MAX_INBOX_PER_ACCOUNT:
            inbox = inbox[:MAX_INBOX_PER_ACCOUNT]

    merged_seen = list(dict.fromkeys(fresh_ids + seen_ids))[:MAX_SEEN_IDS]

    account.seen_mail_ids_json = json.dumps(merged_seen, ensure_ascii=False)
    account.pending_alerts_json = json.dumps(pending, ensure_ascii=False)
    account.pending_inbox_json = json.dumps(inbox, ensure_ascii=False)
    account.last_mail_check_at = _utcnow()
    account.last_mail_check_error = ""

    return {
        "email": account.email,
        "fetched": len(messages),
        "new_alerts": len(new_alerts),
        "new_inbox": len(new_inbox),
        "first_scan": first_scan,
        "pending_total": len(pending),
        "inbox_total": len(inbox),
    }


def _run_business_monitor_round(*, account_id: Optional[int] = None) -> Dict[str, Any]:
    """执行一轮监控。

    - account_id 为 None: 扫描所有 enabled 账号
    - account_id 指定: 只扫描该账号(用于「立即检查」按钮)
    """
    if not _monitor_lock.acquire(blocking=False):
        return {"skipped": True, "reason": "上一轮尚未结束"}

    started_at = time.time()
    summary: Dict[str, Any] = {
        "started_at": _utcnow().isoformat(),
        "scanned": 0,
        "success": 0,
        "failed": 0,
        "total_new_alerts": 0,
        "details": [],
        "errors": [],
    }

    try:
        with Session(engine) as session:
            query = select(GptBusinessAccountModel)
            if account_id is not None:
                query = query.where(GptBusinessAccountModel.id == account_id)
            else:
                query = query.where(GptBusinessAccountModel.enabled == True)  # noqa: E712
            accounts = session.exec(query).all()

            for account in accounts:
                summary["scanned"] += 1
                try:
                    detail = _process_business_account(account)
                    if (
                        bool(account.dangerous)
                        or bool(str(account.refund_status or "").strip())
                    ):
                        _lock_business_parent_state_mutation(
                            session, [int(account.id)],
                        )
                    session.add(account)
                    session.commit()
                    summary["success"] += 1
                    summary["total_new_alerts"] += detail["new_alerts"]
                    summary["details"].append(detail)
                except Exception as exc:
                    session.rollback()
                    try:
                        fresh = session.get(GptBusinessAccountModel, account.id)
                        if fresh:
                            fresh.last_mail_check_at = _utcnow()
                            fresh.last_mail_check_error = f"{exc}"[:300]
                            session.add(fresh)
                            session.commit()
                    except Exception:
                        session.rollback()
                    summary["failed"] += 1
                    summary["errors"].append({"email": account.email, "error": str(exc)})
    finally:
        _monitor_lock.release()

    summary["duration_seconds"] = round(time.time() - started_at, 2)
    return summary


@router.post("/accounts/{account_id}/check-mail-now")
def check_account_mail_now(account_id: int):
    """立即对指定账号执行一轮监控(不等定时轮询)。"""
    with Session(engine) as session:
        acc = session.get(GptBusinessAccountModel, account_id)
        if not acc:
            raise HTTPException(404, "账号不存在")
    return _run_business_monitor_round(account_id=account_id)


@router.post("/accounts/{account_id}/fetch-mail")
def fetch_account_mail(account_id: int, body: Optional[GptBusinessFetchMailRequest] = None):
    """读取指定账号最近 N 封邮件(Inbox + Junk)。

    根据 mail_access_type 自动选择 Graph API 或 IMAP:
    - graph: 调用 Microsoft Graph
    - imap_pop: 走 IMAP (XOAUTH2 优先, 密码兜底)
    - "": 有 OAuth 时尝试 Graph, 失败回退 IMAP
    """
    from core.base_mailbox import OutlookMailbox

    body = body or GptBusinessFetchMailRequest()
    limit = max(1, min(int(body.limit or 10), 50))

    with Session(engine) as session:
        acc = session.get(GptBusinessAccountModel, account_id)
        if not acc:
            raise HTTPException(404, "账号不存在")

        mailbox = OutlookMailbox(platform="")
        mb_account = _build_mailbox_account(acc)
        mail_type = (acc.mail_access_type or "").strip().lower()
        last_error = ""

        # 1) Graph 路径
        if mail_type == "graph" or (mail_type == "" and acc.client_id and acc.refresh_token):
            try:
                messages = _fetch_via_graph(mailbox, mb_account, limit)
                acc.last_used = _utcnow()
                # 顺手回填升级 BUSINESS 时间(仅当为空且命中确认邮件)
                filled = _maybe_fill_upgrade_time(acc, messages)
                session.add(acc)
                session.commit()
                return {
                    "email": acc.email,
                    "mail_access_type": mail_type or "graph",
                    "method": "graph",
                    "count": len(messages),
                    "messages": messages,
                    "business_upgraded_at_filled": filled,
                }
            except Exception as exc:
                last_error = f"Graph 取件失败: {exc}"

        # 2) IMAP 路径
        if mail_type == "imap_pop" or mail_type == "" or last_error:
            folders = [body.folder] if body.folder else ["INBOX", "Junk"]
            try:
                messages = _fetch_via_imap(mailbox, mb_account, limit, folders)
                acc.last_used = _utcnow()
                filled = _maybe_fill_upgrade_time(acc, messages)
                session.add(acc)
                session.commit()
                return {
                    "email": acc.email,
                    "mail_access_type": mail_type or "imap_pop",
                    "method": "imap",
                    "count": len(messages),
                    "messages": messages,
                    "business_upgraded_at_filled": filled,
                }
            except Exception as exc:
                last_error = f"{last_error + '; ' if last_error else ''}IMAP 取件失败: {exc}"

        raise HTTPException(400, last_error or "无可用取件方式")


# ── 铃铛报警 & 收件箱 ────────────────────────────────────────

@router.get("/alerts/summary")
def alerts_summary():
    """前端轮询用:返回每个有未读邮件的账号的 unread 数量。

    两个通道:
      - bell (pending_alerts_json): 仅"封禁报警" 白名单命中
      - inbox (pending_inbox_json): 所有新邮件
    """
    with Session(engine) as session:
        accounts = session.exec(select(GptBusinessAccountModel)).all()
        items = []
        total_unread = 0
        total_inbox = 0
        inbox_accounts = 0
        for acc in accounts:
            try:
                pending = json.loads(acc.pending_alerts_json or "[]")
            except Exception:
                pending = []
            try:
                inbox = json.loads(acc.pending_inbox_json or "[]")
            except Exception:
                inbox = []
            bell_count = len(pending)
            inbox_count = len(inbox)
            if bell_count:
                total_unread += bell_count
            if inbox_count:
                total_inbox += inbox_count
                inbox_accounts += 1
            if not bell_count and not inbox_count:
                continue
            items.append({
                "id": acc.id,
                "email": acc.email,
                "unread_count": bell_count,
                "inbox_unread_count": inbox_count,
                "latest_subject": (pending[0].get("subject") if pending
                                   else (inbox[0].get("subject") if inbox else "")),
                "latest_time": (pending[0].get("time") if pending
                                else (inbox[0].get("time") if inbox else "")),
            })
        return {
            "total_unread": total_unread,
            "account_count": sum(1 for it in items if it["unread_count"]),
            "total_inbox_unread": total_inbox,
            "inbox_account_count": inbox_accounts,
            "items": items,
        }


