# ── 登录(DrissionPage + 邮箱 OTP) ──────────────────────────

def _run_business_login(
    account_id: int,
    body: "GptBusinessActionRequest",
    *,
    is_signup: bool = False,
    log_fn: Optional[Any] = None,
) -> Dict[str, Any]:
    """对 BUSINESS 账号执行一次 DrissionPage 邮箱 OTP 登录/注册。

    只更新 last_used(无 PRO/订阅逻辑)。
    """
    from platforms.chatgpt.gpt_pro_login import (
        build_mailbox_for_account, login_with_email_otp, _collect_cookies)

    with Session(engine) as session:
        acc = session.get(GptBusinessAccountModel, account_id)
        if not acc:
            raise HTTPException(404, "账号不存在")
        if not acc.enabled:
            raise HTTPException(409, "账号已被禁用")
        snapshot = _business_mail_snapshot(acc)

    # 登录成功后抓取 chatgpt.com 会话 cookie(含 cf_clearance 等)+ 注入 access_token,
    # 组成 cookie_blob 供母号/成员/计费接口直接用。
    def _capture_cookie(page, result):
        try:
            ck = _collect_cookies(page) or {}
            at = getattr(result, "access_token", "") or ""
            # chatgpt.com 不把 access token 存成 cookie(它在 /api/auth/session);team 账号登录
            # 走了工作空间选择, result.access_token 常为空 → 直接在页面拉 session 拿 accessToken 最可靠。
            try:
                s = page.run_js(
                    "return fetch('/api/auth/session',{credentials:'include'})"
                    ".then(r=>r.json()).then(j=>(j&&j.accessToken)||'').catch(()=>'')")
                if s and str(s).strip():
                    at = str(s).strip()
            except Exception:
                pass
            if at:
                ck["oai-access-token"] = at    # 覆盖式写入, 保证有 AT
            blob = "; ".join(f"{k}={v}" for k, v in ck.items() if v)
            return {"ok": True, "cookie_blob": blob, "access_token": at, "cookie_names": sorted(ck.keys())}
        except Exception as exc:
            return {"ok": False, "error": str(exc)}

    proxy = _resolve_action_proxy(body)
    mailbox, mb_account = build_mailbox_for_account(snapshot, proxy=proxy)
    result = login_with_email_otp(
        email=snapshot["email"],
        mailbox=mailbox,
        mailbox_account=mb_account,
        headless=bool(body.headless),
        proxy=proxy,
        otp_timeout=int(body.otp_timeout or 180),
        keep_browser_open=bool(body.keep_browser_open),
        is_signup=is_signup,
        full_name=(body.full_name or ""),
        birthday=body.birthday,
        post_login_action=_capture_cookie,
        log_fn=log_fn,
    )

    if result.ok:
        action = result.action_result if isinstance(result.action_result, dict) else {}
        cookie_blob = str(action.get("cookie_blob") or "")
        at = str(action.get("access_token") or "") or (getattr(result, "access_token", "") or "")
        exp_dt = None
        if at:
            try:
                from platforms.chatgpt.utils import decode_jwt_payload
                claims = decode_jwt_payload(at) or {}
                exp = int(claims.get("exp") or 0)
                if exp:
                    from datetime import timezone as _tz
                    exp_dt = datetime.fromtimestamp(exp, tz=_tz.utc)
            except Exception:
                exp_dt = None
        now = _utcnow()
        with Session(engine) as session:
            acc = session.get(GptBusinessAccountModel, account_id)
            if acc:
                acc.last_used = now
                acc.updated_at = now
                if cookie_blob:
                    acc.cookie_blob = cookie_blob
                    acc.cookie_updated_at = now
                    acc.cookie_expires_at = exp_dt
                session.add(acc)
                session.commit()
        if cookie_blob and log_fn:
            log_fn(f"[BUSINESS 登录] 已抓取并保存会话 cookie ({len(action.get('cookie_names') or [])} 项)")
    return result.to_dict()


@router.post("/accounts/{account_id}/login")
def login_account(account_id: int, body: Optional[GptBusinessActionRequest] = None):
    """登录:DrissionPage + 邮箱 OTP。"""
    return _run_business_login(account_id, body or GptBusinessActionRequest())


@router.post("/accounts/{account_id}/ms-web-login")
def ms_web_login(account_id: int, body: Optional[GptBusinessMsLoginRequest] = None):
    """启动该 BUSINESS Outlook 账号的微软网页版登录任务。

    该接口只确认后台任务已创建；实际登录结果通过
    :func:`ms_web_login_status` 轮询。浏览器会保持打开，以便人工完成
    MFA、验证码或其他 Microsoft 安全挑战。
    """
    body = body or GptBusinessMsLoginRequest()

    # 先读取并校验账号。凭据只留在当前 worker 闭包中，不进入返回值或任务记录。
    with Session(engine) as session:
        acc = session.get(GptBusinessAccountModel, account_id)
        if not acc:
            raise HTTPException(404, "账号不存在")
        if not bool(getattr(acc, "enabled", True)):
            raise HTTPException(409, "账号已被禁用")
        email = str(getattr(acc, "email", "") or "").strip()
        password = str(getattr(acc, "password", "") or "").strip()
        mail_access_type = str(getattr(acc, "mail_access_type", "") or "").strip().lower()
        provider = _ms_web_provider(acc)

    if not email:
        raise HTTPException(400, "账号缺 email")
    if not password:
        raise HTTPException(400, "该账号没有保存密码, 无法自动登录网页版")
    if provider in {"icloud", "qqmail"}:
        raise HTTPException(400, "该邮箱 provider 不支持微软网页版登录")
    if mail_access_type not in {"", "imap_pop"}:
        raise HTTPException(400, "微软网页版登录仅支持 imap_pop 或未检测类型的 Outlook 账号")

    proxy = _resolve_action_proxy(body)
    account_key = int(account_id)
    with _MS_WEB_LOCK:
        active_id = _MS_WEB_ACTIVE.get(account_key)
        if active_id:
            active = _MS_WEB_TASKS.get(active_id)
            if active and active.get("status") == "running":
                raise HTTPException(409, "该账号已有微软网页登录任务正在运行")
            # 处理进程内任务记录被外部清理/终止但 active 标记残留的情况。
            _MS_WEB_ACTIVE.pop(account_key, None)
        task = _ms_web_new_task(account_key)
        task_id = str(task["task_id"])

    def _worker() -> None:
        _run_ms_web_login_task(
            task_id,
            account_key,
            email,
            password,
            proxy=proxy,
            headless=bool(body.headless),
        )

    try:
        thread = threading.Thread(
            target=_worker,
            name=f"gpt-business-ms-login-{task_id[:8]}",
            daemon=True,
        )
        thread.start()
    except Exception as exc:
        _ms_web_finish(
            task_id,
            status="failed",
            stage="exception",
            error=str(exc),
            password=password,
            proxy=proxy,
        )
        raise HTTPException(500, "无法启动微软网页登录任务") from exc

    snapshot = _ms_web_snapshot(task_id, since=0) or {}
    return {
        "ok": True,
        "task_id": task_id,
        "status": snapshot.get("status", "running"),
        "stage": snapshot.get("stage", "starting"),
        "email": email,
        "note": "已启动微软网页版登录浏览器, 请通过状态接口查看登录结果并完成人工验证。",
    }


@router.get("/accounts/{account_id}/ms-web-login/{task_id}")
def ms_web_login_status(
    account_id: int,
    task_id: str,
    since: int = Query(0, ge=0),
):
    """获取微软网页登录任务状态，并返回 ``since`` 之后的增量日志。"""
    snapshot = _ms_web_snapshot(task_id, since=since)
    if snapshot is None or int(snapshot.get("account_id") or 0) != int(account_id):
        raise HTTPException(404, "微软网页登录任务不存在")
    return snapshot


class GptBusinessProBurnRequest(BaseModel):
    account_ids: list = []
    concurrency: int = 2
    kick: bool = True


@router.post("/accounts/{account_id}/pro-refund-burn")
def business_pro_refund_burn(account_id: int, body: GptBusinessProBurnRequest):
    """用该 BUSINESS(team)账号自身的会话 cookie 当母号, 对选中 PRO 号跑「退款焚诀」:
    邀请 → PRO 登录入群 → transfer 去个人空间掉订阅 → 踢出 → 标记「已焚·待退款」。
    轮询同 GET /business-masters/pro-refund-burn/{task_id}。"""
    import base64 as _b64
    from core.config_store import config_store
    from api.business_masters import (
        _normalize_pro_refund_burn_ids,
        _start_pro_refund_burn,
    )
    ids = _normalize_pro_refund_burn_ids(body.account_ids or [])
    if not ids:
        raise HTTPException(400, "未选择 PRO 账号")
    with Session(engine) as session:
        acc = session.get(GptBusinessAccountModel, account_id)
        if not acc:
            raise HTTPException(404, "账号不存在")
        blob = getattr(acc, "cookie_blob", "") or ""
    at = ""
    for part in blob.split(";"):
        if "=" in part:
            k, v = part.split("=", 1)
            if k.strip() == "oai-access-token":
                at = v.strip()
    if not at:
        raise HTTPException(400, "该账号没有会话 cookie,请先「登录」该账号(登录会自动抓取并保存 cookie)")
    try:
        seg = at.split(".")[1]
        seg += "=" * (-len(seg) % 4)
        claims = json.loads(_b64.urlsafe_b64decode(seg))
        team = claims.get("https://api.openai.com/auth", {}).get("chatgpt_account_id", "")
    except Exception:
        team = ""
    if not team:
        raise HTTPException(400, "无法从 cookie 解析 team id(cookie 可能已过期,请重新登录该账号)")
    proxy = str(config_store.get("default_proxy", "") or "").strip()
    conc = max(1, min(int(body.concurrency or 2), 4))
    label = f"biz{account_id}"
    with Session(engine) as session:
        _assert_business_invite_cooldown_available(session, int(account_id))
    quota_operation_id = f"pro-burn-{account_id}-{_uuid.uuid4().hex}"
    quota_subjects = [f"pro:{value}" for value in ids]
    reservation = _reserve_business_invite_quota(
        account_id,
        quota_operation_id,
        quota_subjects,
        action="pro_refund_burn",
        seat_type="default",
    )
    try:
        task_id = _start_pro_refund_burn(
            at,
            team,
            ids,
            conc,
            bool(body.kick),
            proxy,
            label,
            business_account_id=account_id,
            invite_quota_operation_id=quota_operation_id,
        )
    except Exception:
        _release_business_invite_quota(
            account_id,
            quota_operation_id,
            quota_subjects,
            action="pro_refund_burn",
            reason="burn_task_not_started",
        )
        raise
    return {
        "task_id": task_id,
        "targets": len(ids),
        "requested": len(body.account_ids or []),
        "invite_quota": reservation["invite_quota"],
    }


class SetBurnedCountRequest(BaseModel):
    count: Optional[int] = None   # None = 清除手动覆盖, 恢复自动统计


@router.post("/accounts/{account_id}/set-burned-count")
def set_burned_count(account_id: int, body: SetBurnedCountRequest):
    """手动修改/覆盖该母号「已退 PRO 个数」。count=null 恢复自动统计。"""
    from api.business_masters import PRO_BURN_LIMIT_PER_MASTER
    with Session(engine) as s:
        acc = s.get(GptBusinessAccountModel, account_id)
        if not acc:
            raise HTTPException(404, "账号不存在")
        try:
            extra = json.loads(acc.extra_json or "{}")
        except Exception:
            extra = {}
        if body.count is None:
            extra.pop("pro_burn_manual_count", None)
        else:
            c = int(body.count)
            if c < 0:
                raise HTTPException(400, "个数不能为负")
            if c > PRO_BURN_LIMIT_PER_MASTER:
                raise HTTPException(400, f"个数不能超过上限 {PRO_BURN_LIMIT_PER_MASTER}")
            extra["pro_burn_manual_count"] = c
        acc.extra_json = json.dumps(extra, ensure_ascii=False)
        acc.updated_at = _utcnow()
        s.add(acc)
        s.commit()
    eff = _burned_count_for_biz(account_id)
    return {"ok": True, "pro_burned_count": eff,
            "pro_burn_manual": body.count is not None, "pro_burn_limit": PRO_BURN_LIMIT_PER_MASTER}


