class BizCpaDeviceParentsPutRequest(BaseModel):
    """Replace the complete BUSINESS-parent selection for one CPA device.

    ``expected_revisions`` is keyed by BUSINESS account id.  It must cover the
    union of the requested parents and the parents currently bound to the
    device, so an unseen concurrent bind/unbind cannot be partially overwritten.
    """

    parent_ids: List[int] = Field(default_factory=list)
    target_revision: int
    expected_revisions: Dict[int, int] = Field(default_factory=dict)


class BizSub2ApiDeviceParentsPutRequest(BaseModel):
    """Replace one Sub2API device's complete BUSINESS-parent selection."""

    parent_ids: List[int] = Field(default_factory=list)
    expected_device_updated_at: str = ""
    expected_revisions: Dict[int, int] = Field(default_factory=dict)


class BizCpaRotationScanRequest(BaseModel):
    parent_ids: List[int] = Field(default_factory=list)


class BizMasterDispatchRequest(BaseModel):
    """Idempotent manual dispatch for one bound CPA/Sub2API device."""

    operation_id: str
    # Device-refresh reconciliation uses this guarded mode so a refresh can
    # bootstrap a mother only when its active membership set is truly empty.
    # Manual "母号调度" keeps the existing free-seat behavior by default.
    empty_only: bool = False


class BizDeviceBindingMigrationRequest(BaseModel):
    """Move one mother's managed-child delivery and then switch its policy.

    ``operation_id`` is supplied by the caller and is permanently bound to the
    parent/source/target snapshot.  Replaying it resumes the same checkpoints;
    reusing it for a different request is rejected.
    """

    operation_id: str
    target_device_ref: str
    expected_policy_revision: Any


def _default_business_automation_policy(parent_id: int) -> dict:
    return {
        "business_account_id": int(parent_id),
        "auto_rotation_enabled": False,
        "enabled": False,
        "manual_invite_enabled": True,
        "delivery_type": "",
        "cpa_target_id": None,
        "sub2api_device_id": None,
        "delivery_target": None,
        "trigger_mode": "long_window_exhausted",
        "rotate_default": True,
        "rotate_prolite": False,
        "rotation_seat_type_mode": "derived_from_persisted_seat_summary",
        "rotate_fields_legacy_only": True,
        "revision": 0,
        "last_scan_at": "",
        "last_error": "",
        "created_at": "",
        "updated_at": "",
    }


def _serialize_business_automation_policy(
    row: Optional[GptBusinessAutomationPolicyModel],
    parent_id: int,
) -> dict:
    if row is None:
        return _default_business_automation_policy(parent_id)
    delivery_type = str(getattr(row, "delivery_type", "") or "").strip().lower()
    cpa_target_id = int(row.cpa_target_id) if row.cpa_target_id else None
    sub2api_device_id = (
        int(getattr(row, "sub2api_device_id", 0) or 0) or None
    )
    # Existing rows predate ``delivery_type``.  Separate id columns make this
    # inference deterministic while the additive migration converges.
    if delivery_type not in {"cpa", "sub2api"}:
        delivery_type = "sub2api" if sub2api_device_id else "cpa" if cpa_target_id else ""
    if delivery_type == "cpa" and not cpa_target_id:
        delivery_type = ""
    if delivery_type == "sub2api" and not sub2api_device_id:
        delivery_type = ""
    result = {
        "business_account_id": int(row.business_account_id),
        "auto_rotation_enabled": bool(row.auto_rotation_enabled),
        "enabled": bool(row.auto_rotation_enabled),
        "manual_invite_enabled": bool(row.manual_invite_enabled),
        "delivery_type": delivery_type,
        "cpa_target_id": cpa_target_id,
        "sub2api_device_id": sub2api_device_id,
        "trigger_mode": str(row.trigger_mode or "long_window_exhausted"),
        "rotate_default": bool(row.rotate_default),
        "rotate_prolite": bool(row.rotate_prolite),
        "rotation_seat_type_mode": "derived_from_persisted_seat_summary",
        "rotate_fields_legacy_only": True,
        "revision": int(row.revision or 0),
        "last_scan_at": _iso_utc(row.last_scan_at),
        "last_error": str(row.last_error or "")[:500],
        "created_at": _iso_utc(row.created_at),
        "updated_at": _iso_utc(row.updated_at),
    }
    result["delivery_target"] = None
    return result


def _business_automation_policy(parent_id: int) -> dict:
    try:
        with Session(engine) as session:
            result = _serialize_business_automation_policy(
                session.get(GptBusinessAutomationPolicyModel, int(parent_id)),
                int(parent_id),
            )
            result["delivery_target"] = _business_delivery_target(result)
            return result
    except OperationalError as exc:
        # Rolling deployment / narrowly-scoped test databases may observe code
        # before the additive table migration.  Fail to the safe policy defaults
        # (automation off, manual invite on), never to automation enabled.
        if "no such table" not in str(exc).lower():
            raise
        return _default_business_automation_policy(int(parent_id))


def _safe_cpa_target(target_id: Optional[int]) -> Optional[dict]:
    if not target_id:
        return None
    from api.gpt_plan_operations import _cpa_sync_target_by_id
    target = _cpa_sync_target_by_id(int(target_id))
    if not target:
        return None
    wanted = int(target.get("id") or target_id or 0)
    registry_enabled = target.get("enabled") is not False
    credentials_configured = bool(
        str(target.get("api_url") or "").strip()
        and str(target.get("api_key") or "").strip()
    )
    enabled = registry_enabled and credentials_configured
    return {
        "id": wanted,
        "name": _business_device_public_name(
            "cpa",
            wanted,
            target.get("name"),
            api_url=str(target.get("api_url") or ""),
        ),
        "enabled": enabled,
        "state": (
            "configured" if enabled
            else "disabled" if not registry_enabled
            else "unconfigured"
        ),
    }


def _safe_sub2api_target(
    device_id: Optional[int],
    *,
    session: Optional[Session] = None,
) -> Optional[dict]:
    """Resolve a credential-free ChatGPT Sub2API device identity."""
    try:
        wanted = int(device_id or 0)
    except (TypeError, ValueError):
        wanted = 0
    if wanted <= 0:
        return None

    def _read(db: Session) -> Optional[dict]:
        device = db.get(SyncDeviceModel, wanted)
        if not device:
            return None
        from api.gpt_plan_operations import _sub2api_device_type
        if (
            _sub2api_device_type(device.type) != "sub2api"
            or str(device.platform or "chatgpt").strip().lower()
            not in {"", "chatgpt"}
        ):
            return None
        registry_enabled = bool(device.enabled)
        credentials_configured = bool(
            str(device.api_url or "").strip()
            and str(device.api_key or "").strip()
        )
        enabled = registry_enabled and credentials_configured
        return {
            "id": int(device.id or 0),
            "name": _business_device_public_name(
                "sub2api", wanted, device.name, api_url=str(device.api_url or ""),
            ),
            "provider": "sub2api",
            "registry": "sync_devices",
            "enabled": enabled,
            "state": (
                "configured" if enabled
                else "disabled" if not registry_enabled
                else "unconfigured"
            ),
            "updated_at": _iso_utc(device.updated_at),
        }

    if session is not None:
        return _read(session)
    with Session(engine) as db:
        return _read(db)


def _business_delivery_target(policy: dict) -> Optional[dict]:
    provider = str(policy.get("delivery_type") or "").strip().lower()
    if provider == "sub2api":
        target = _safe_sub2api_target(policy.get("sub2api_device_id"))
        if target:
            return target
        target_id = int(policy.get("sub2api_device_id") or 0)
        return ({
            "id": target_id,
            "name": f"Sub2API {target_id}",
            "provider": "sub2api",
            "registry": "sync_devices",
            "enabled": False,
            "state": "missing",
            "updated_at": "",
        } if target_id > 0 else None)
    if provider == "cpa":
        target_id = int(policy.get("cpa_target_id") or 0)
        target = _safe_cpa_target(target_id)
        if target:
            return {
                **target,
                "provider": "cpa",
                "registry": "gpt_pro_cpa_targets",
                "enabled": target.get("enabled") is not False,
                "state": str(target.get("state") or "configured"),
            }
        return ({
            "id": target_id,
            "name": f"CPA {target_id}",
            "provider": "cpa",
            "registry": "gpt_pro_cpa_targets",
            "enabled": False,
            "state": "missing",
        } if target_id > 0 else None)
    return None


def _lock_business_parent_state_mutation(
    session: Session,
    parent_ids: List[int],
) -> Dict[int, GptBusinessAccountModel]:
    """Serialize parent/policy writes against an active allocation/rotation.

    The durable ``parent:<id>`` lease is held for the whole remote CPA delivery.
    Every local writer which can change the parent's automation eligibility must
    consult it in the same database critical section used to lock the parent row.
    """
    ids = sorted({int(value) for value in parent_ids if int(value) > 0})
    if not ids:
        return {}
    dialect = session.get_bind().dialect.name
    if dialect == "sqlite" and not session.in_transaction():
        session.connection().exec_driver_sql("BEGIN IMMEDIATE")
    if dialect == "sqlite":
        parents = session.exec(
            select(GptBusinessAccountModel).where(
                GptBusinessAccountModel.id.in_(ids)  # type: ignore[union-attr]
            )
        ).all()
    else:
        parents = session.exec(
            select(GptBusinessAccountModel)
            .where(GptBusinessAccountModel.id.in_(ids))  # type: ignore[union-attr]
            .with_for_update()
        ).all()
    now = _utcnow()
    active = session.exec(
        select(GptBusinessAllocationLeaseModel)
        .where(GptBusinessAllocationLeaseModel.resource_key.in_(  # type: ignore[union-attr]
            [f"parent:{parent_id}" for parent_id in ids]
        ))
        .where(GptBusinessAllocationLeaseModel.expires_at > now)
    ).first()
    if active:
        raise HTTPException(409, {
            "code": "business_parent_automation_busy",
            "message": "该母号正在执行自动分配或 CPA 轮换，暂不能修改账号安全状态或自动化策略",
            "job_id": str(active.job_id or ""),
            "expires_at": _iso_utc(active.expires_at),
        })
    return {int(parent.id): parent for parent in parents if parent.id is not None}


def _put_business_automation_policy(
    parent_id: int,
    body: BizAutomationPolicyUpdateRequest,
) -> dict:
    try:
        expected_revision = int(body.expected_revision)
    except (TypeError, ValueError):
        raise HTTPException(400, "expected_revision 无效")
    if expected_revision < 0:
        raise HTTPException(400, "expected_revision 不能为负数")
    if body.trigger_mode is not None:
        trigger_mode = str(body.trigger_mode or "").strip().lower()
        if trigger_mode not in BUSINESS_CPA_TRIGGER_MODES:
            raise HTTPException(400, "trigger_mode 只能是 long_window_exhausted 或 any_limit_reached")
    else:
        trigger_mode = None
    fields_set = getattr(body, "model_fields_set", None)
    if fields_set is None:  # Pydantic v1 compatibility
        fields_set = getattr(body, "__fields_set__", set())
    target_supplied = "cpa_target_id" in fields_set
    if body.cpa_target_id is not None:
        try:
            target_id = int(body.cpa_target_id)
        except (TypeError, ValueError):
            raise HTTPException(400, "cpa_target_id 无效")
        if target_id <= 0:
            raise HTTPException(400, "cpa_target_id 必须为正整数")
        if _safe_cpa_target(target_id) is None:
            raise HTTPException(404, "指定的 CPA 共享目标不存在")
    else:
        target_id = None

    ignored_legacy_fields = sorted(
        name for name in ("rotate_default", "rotate_prolite")
        if name in fields_set
    )
    effective_fields = set(fields_set) - {
        "expected_revision",
        "rotate_default",
        "rotate_prolite",
    }
    if ignored_legacy_fields and not effective_fields:
        with Session(engine) as session:
            parents = _lock_business_parent_state_mutation(session, [int(parent_id)])
            if int(parent_id) not in parents:
                raise HTTPException(404, "BUSINESS 母号不存在")
            row = session.get(GptBusinessAutomationPolicyModel, int(parent_id))
            current_revision = int(row.revision or 0) if row else 0
            if expected_revision != current_revision:
                raise HTTPException(409, {
                    "code": "business_automation_policy_revision_conflict",
                    "message": "母号自动化设置已被其他页面更新，请刷新后重试",
                    "expected_revision": expected_revision,
                    "current_revision": current_revision,
                })
            result = _serialize_business_automation_policy(row, int(parent_id))
        result["cpa_target"] = _safe_cpa_target(result.get("cpa_target_id"))
        result["ignored_legacy_fields"] = ignored_legacy_fields
        return result

    with Session(engine) as session:
        parents = _lock_business_parent_state_mutation(session, [int(parent_id)])
        parent = parents.get(int(parent_id))
        if not parent:
            raise HTTPException(404, "BUSINESS 母号不存在")
        row = session.get(GptBusinessAutomationPolicyModel, int(parent_id))
        current_revision = int(row.revision or 0) if row else 0
        if expected_revision != current_revision:
            raise HTTPException(409, {
                "code": "business_automation_policy_revision_conflict",
                "message": "母号自动化设置已被其他页面更新，请刷新后重试",
                "expected_revision": expected_revision,
                "current_revision": current_revision,
            })
        now = _utcnow()
        if row is None:
            row = GptBusinessAutomationPolicyModel(
                business_account_id=int(parent_id),
                created_at=now,
                updated_at=now,
            )
        # rotate_default / rotate_prolite remain accepted by the request model
        # for rolling-client compatibility, but intentionally do not mutate
        # policy state. Runtime seat types are derived from persisted capacity.
        for name in (
            "auto_rotation_enabled",
            "manual_invite_enabled",
        ):
            value = getattr(body, name)
            if value is not None:
                setattr(row, name, bool(value))
        if body.enabled is not None:
            row.auto_rotation_enabled = bool(body.enabled)
        if target_supplied:
            row.cpa_target_id = target_id
            if target_id is not None:
                row.delivery_type = "cpa"
                row.sub2api_device_id = None
            elif str(getattr(row, "delivery_type", "") or "").strip().lower() == "cpa":
                row.delivery_type = ""
        if trigger_mode is not None:
            row.trigger_mode = trigger_mode
        delivery_type = str(getattr(row, "delivery_type", "") or "").strip().lower()
        if delivery_type not in {"cpa", "sub2api"}:
            delivery_type = (
                "sub2api"
                if int(getattr(row, "sub2api_device_id", 0) or 0) > 0
                else "cpa" if int(row.cpa_target_id or 0) > 0
                else ""
            )
        delivery_target_id = (
            int(getattr(row, "sub2api_device_id", 0) or 0)
            if delivery_type == "sub2api"
            else int(row.cpa_target_id or 0)
            if delivery_type == "cpa"
            else 0
        )
        if bool(row.auto_rotation_enabled) and delivery_target_id <= 0:
            raise HTTPException(400, "开启自动轮换前必须绑定 CPA 或 Sub2API 设备")
        # Validate the prospective provider-specific target.  In particular,
        # editing the independent manual-invite switch on a Sub2API-bound mother
        # must not be rejected merely because it has no CPA target.
        if bool(row.auto_rotation_enabled):
            delivery_target = (
                _safe_sub2api_target(delivery_target_id)
                if delivery_type == "sub2api"
                else _safe_cpa_target(delivery_target_id)
            )
            target_configured = bool(
                delivery_target
                and str(delivery_target.get("state") or "configured")
                == "configured"
            )
            if not target_configured:
                if delivery_type == "cpa":
                    raise HTTPException(409, {
                        "code": "business_cpa_target_missing",
                        "message": "已选择的 CPA 设备配置不存在，请重新选择后再开启自动轮换",
                        "cpa_target_id": delivery_target_id or None,
                    })
                raise HTTPException(409, {
                    "code": "business_sub2api_device_unavailable",
                    "message": "已绑定的 Sub2API 设备不存在、已停用或配置不完整",
                    "sub2api_device_id": delivery_target_id or None,
                })
        if bool(row.auto_rotation_enabled):
            if not bool(parent.enabled):
                raise HTTPException(409, "BUSINESS 母号已禁用，不能开启自动轮换")
            if bool(parent.dangerous):
                raise HTTPException(409, "BUSINESS 母号已标记 dangerous/dead，不能开启自动轮换")
            if str(parent.refund_status or "").strip():
                raise HTTPException(409, "BUSINESS 母号正在退款流程，不能开启自动轮换")
            team_session = _business_account_team_session_status(parent)
            if not bool(team_session.get("usable")):
                detail = _business_team_session_error(team_session)
                detail["message"] += "，不能开启自动轮换"
                raise HTTPException(409, detail)
        row.revision = current_revision + 1
        row.updated_at = now
        session.add(row)
        session.commit()
        session.refresh(row)
        result = _serialize_business_automation_policy(row, int(parent_id))
    result["cpa_target"] = _safe_cpa_target(result.get("cpa_target_id"))
    result["delivery_target"] = _business_delivery_target(result)
    return result


def get_business_automation_policy(account_id: int):
    with Session(engine) as session:
        if not session.get(GptBusinessAccountModel, int(account_id)):
            raise HTTPException(404, "BUSINESS 母号不存在")
    result = _business_automation_policy(account_id)
    result["cpa_target"] = _safe_cpa_target(result.get("cpa_target_id"))
    result["delivery_target"] = _business_delivery_target(result)
    return result


def put_business_automation_policy(
    account_id: int,
    body: BizAutomationPolicyUpdateRequest,
):
    return _put_business_automation_policy(account_id, body)


def get_business_cpa_automation_policy(account_id: int):
    return get_business_automation_policy(account_id)


def put_business_cpa_automation_policy(
    account_id: int,
    body: BizAutomationPolicyUpdateRequest,
):
    return _put_business_automation_policy(account_id, body)


def put_business_automation_policies_batch(body: BizAutomationPolicyBatchRequest):
    if not body.items:
        raise HTTPException(400, "未选择母号")
    if len(body.items) > 500:
        raise HTTPException(400, "单次最多更新 500 个母号")
    results = []
    for item in body.items:
        # Preserve PATCH-like batch semantics.  In particular, an omitted
        # cpa_target_id must not become an explicit null and silently detach the
        # parent's shared device while toggling another field.
        dump = getattr(item, "model_dump", None)
        values = (
            dump(exclude={"business_account_id"}, exclude_unset=True)
            if callable(dump)
            else item.dict(exclude={"business_account_id"}, exclude_unset=True)
        )
        payload = BizAutomationPolicyUpdateRequest(**values)
        results.append(_put_business_automation_policy(int(item.business_account_id), payload))
    return {"ok": True, "items": results, "total": len(results)}


def put_business_cpa_automation_policies_batch(body: BizAutomationPolicyBatchRequest):
    return put_business_automation_policies_batch(body)


def _business_cpa_target_registry_snapshot_in_session(
    session: Session,
) -> tuple[List[dict], int]:
    """Read the shared GPT PRO CPA target registry in the caller transaction.

    Only public identity fields leave this helper.  Reading through the same
    database transaction lets the device-parent replacement endpoint compare
    the registry revision without ever accepting a deleted/replaced target.
    """
    from api.gpt_plan_operations import (
        _CPA_SYNC_TARGETS_KEY,
        _CPA_SYNC_TARGETS_REVISION_KEY,
        _get_cpa_sync_targets,
    )
    if session.get_bind().dialect.name == "sqlite":
        target_item = session.get(ConfigItem, _CPA_SYNC_TARGETS_KEY)
        revision_item = session.get(ConfigItem, _CPA_SYNC_TARGETS_REVISION_KEY)
    else:
        config_rows = session.exec(
            select(ConfigItem)
            .where(ConfigItem.key.in_([  # type: ignore[union-attr]
                _CPA_SYNC_TARGETS_KEY,
                _CPA_SYNC_TARGETS_REVISION_KEY,
            ]))
            .with_for_update()
        ).all()
        config_by_key = {str(row.key): row for row in config_rows}
        target_item = config_by_key.get(_CPA_SYNC_TARGETS_KEY)
        revision_item = config_by_key.get(_CPA_SYNC_TARGETS_REVISION_KEY)
    try:
        raw_targets = (
            json.loads(target_item.value)
            if target_item is not None and target_item.value
            else _get_cpa_sync_targets()
        )
    except Exception:
        raw_targets = []
    if not isinstance(raw_targets, list):
        raw_targets = []
    try:
        revision = int(revision_item.value or 0) if revision_item else 0
    except (TypeError, ValueError):
        revision = 0

    public: List[dict] = []
    seen: set[int] = set()
    for row in raw_targets:
        if not isinstance(row, dict):
            continue
        try:
            target_id = int(row.get("id") or 0)
        except (TypeError, ValueError):
            continue
        if target_id <= 0 or target_id in seen:
            continue
        if (
            row.get("enabled") is False
            or not str(row.get("api_url") or "").strip()
            or not str(row.get("api_key") or "").strip()
        ):
            # The legacy whole-device assignment endpoint must enforce the
            # same configured-target rule as the migration endpoint/UI.
            continue
        seen.add(target_id)
        public.append({
            "id": target_id,
            "name": _business_device_public_name(
                "cpa",
                target_id,
                row.get("name"),
                api_url=str(row.get("api_url") or ""),
            ),
        })
    return public, revision


def put_business_cpa_device_parents(
    target_id: int,
    body: BizCpaDeviceParentsPutRequest,
):
    """Atomically replace all BUSINESS parents assigned to one CPA device.

    Deselecting a parent also disables its automatic rotation in the same
    commit.  Selecting a parent already attached to another device migrates the
    binding while preserving its other policy switches.  No remote CPA or
    OpenAI mutation is performed here.
    """
    try:
        wanted_target_id = int(target_id)
        expected_target_revision = int(body.target_revision)
    except (TypeError, ValueError):
        raise HTTPException(400, "CPA 设备 ID 或 target_revision 无效")
    if wanted_target_id <= 0:
        raise HTTPException(400, "CPA 设备 ID 必须为正整数")
    if expected_target_revision < 0:
        raise HTTPException(400, "target_revision 不能为负数")

    desired_ids: List[int] = []
    seen: set[int] = set()
    for value in body.parent_ids:
        try:
            parent_id = int(value)
        except (TypeError, ValueError):
            raise HTTPException(400, f"无效的 BUSINESS 母号 ID: {value}")
        if parent_id <= 0:
            raise HTTPException(400, f"无效的 BUSINESS 母号 ID: {value}")
        if parent_id not in seen:
            seen.add(parent_id)
            desired_ids.append(parent_id)
    if len(desired_ids) > 500:
        raise HTTPException(400, "单个 CPA 设备最多选择 500 个母号")
    desired = set(desired_ids)
    try:
        expected_revisions = {
            int(parent_id): int(revision)
            for parent_id, revision in body.expected_revisions.items()
        }
    except (TypeError, ValueError):
        raise HTTPException(400, "expected_revisions 无效")
    if any(parent_id <= 0 or revision < 0 for parent_id, revision in expected_revisions.items()):
        raise HTTPException(400, "expected_revisions 中的母号 ID 和版本必须为非负整数")

    # Use the same in-process registry lock as GPT PRO target editing.  SQLite's
    # BEGIN IMMEDIATE below is the cross-process writer fence.
    from api.gpt_plan_operations import _CPA_CONFIG_WRITE_LOCK

    with _CPA_CONFIG_WRITE_LOCK:
        with Session(engine) as session:
            if session.get_bind().dialect.name == "sqlite":
                session.connection().exec_driver_sql("BEGIN IMMEDIATE")

            configured_targets, current_target_revision = (
                _business_cpa_target_registry_snapshot_in_session(session)
            )
            if expected_target_revision != current_target_revision:
                raise HTTPException(409, {
                    "code": "cpa_sync_targets_revision_conflict",
                    "message": "CPA 设备配置已被其他页面更新，请刷新后重试",
                    "expected_revision": expected_target_revision,
                    "current_revision": current_target_revision,
                })
            target = next(
                (row for row in configured_targets if int(row["id"]) == wanted_target_id),
                None,
            )
            # A stale/removed device still needs a safe escape hatch: an empty
            # or reduced desired selection is cleanup-only and may detach some
            # or all remaining parents.  It can never attach or migrate a new
            # parent to a missing target.
            target_state = "configured" if target is not None else "missing"

            policy_query = select(GptBusinessAutomationPolicyModel).where(
                GptBusinessAutomationPolicyModel.cpa_target_id == wanted_target_id
            )
            if desired:
                policy_query = select(GptBusinessAutomationPolicyModel).where(or_(
                    GptBusinessAutomationPolicyModel.cpa_target_id == wanted_target_id,
                    GptBusinessAutomationPolicyModel.business_account_id.in_(desired),  # type: ignore[union-attr]
                ))
            if session.get_bind().dialect.name != "sqlite":
                policy_query = policy_query.with_for_update()
            policy_rows = session.exec(policy_query).all()
            policies = {int(row.business_account_id): row for row in policy_rows}
            currently_bound = {
                parent_id
                for parent_id, row in policies.items()
                if int(row.cpa_target_id or 0) == wanted_target_id
                and str(getattr(row, "delivery_type", "") or "cpa").strip().lower()
                in {"", "cpa"}
            }
            missing_target_additions = sorted(desired - currently_bound)
            if target is None and missing_target_additions:
                raise HTTPException(404, {
                    "code": "business_cpa_target_missing",
                    "message": "指定的 CPA 设备已被删除，只能从该设备移除已绑定母号",
                    "cpa_target_id": wanted_target_id,
                    "new_parent_ids": missing_target_additions,
                })
            affected = desired | currently_bound

            missing_expected = sorted(affected - set(expected_revisions))
            if missing_expected:
                raise HTTPException(409, {
                    "code": "business_cpa_device_selection_revision_required",
                    "message": "母号选择已变化，请刷新后重新保存整组选择",
                    "missing_parent_ids": missing_expected,
                })

            parents = _lock_business_parent_state_mutation(
                session,
                sorted(affected),
            )
            missing_parents = sorted(desired - set(parents))
            if missing_parents:
                raise HTTPException(404, {
                    "code": "business_parent_not_found",
                    "message": "部分 BUSINESS 母号不存在",
                    "parent_ids": missing_parents,
                })

            for parent_id in sorted(affected):
                row = policies.get(parent_id)
                current_revision = int(row.revision or 0) if row else 0
                if expected_revisions[parent_id] != current_revision:
                    raise HTTPException(409, {
                        "code": "business_automation_policy_revision_conflict",
                        "message": "母号自动化设置已被其他页面更新，请刷新后重试",
                        "business_account_id": parent_id,
                        "expected_revision": expected_revisions[parent_id],
                        "current_revision": current_revision,
                    })

            # Device selection is the automation switch. New/migrated parents
            # must come from the exact durable "logged" tab population and have
            # a currently usable/safe Team session. Existing bindings may be
            # retained or removed after their session later becomes unusable.
            binding_eligibility: Dict[int, dict] = {}
            for parent_id in sorted(desired):
                row = policies.get(parent_id)
                parent = parents[parent_id]
                team_session = _business_account_team_session_status(parent)
                eligibility = _business_cpa_device_binding_eligibility(
                    parent,
                    team_session,
                )
                binding_eligibility[parent_id] = eligibility
                already_bound_here = bool(
                    row is not None
                    and int(row.cpa_target_id or 0) == wanted_target_id
                    and str(getattr(row, "delivery_type", "") or "cpa").strip().lower()
                    in {"", "cpa"}
                )
                if (
                    target is not None
                    and not already_bound_here
                    and not bool(eligibility.get("eligible"))
                ):
                    raise HTTPException(409, {
                        "code": "business_parent_not_eligible_for_device_binding",
                        "message": "只能将已登录且当前可用的 BUSINESS 母号新绑定到 CPA 设备",
                        "business_account_id": parent_id,
                        "logged_in": bool(eligibility.get("logged_in")),
                        "blockers": list(eligibility.get("blockers") or []),
                    })

            now = _utcnow()
            added: List[int] = []
            moved: List[int] = []
            removed: List[int] = []
            unchanged: List[int] = []
            enabled: List[int] = []
            disabled: List[int] = []
            for parent_id in sorted(affected):
                row = policies.get(parent_id)
                before_target = int(row.cpa_target_id or 0) if row else 0
                before_provider = (
                    str(getattr(row, "delivery_type", "") or "").strip().lower()
                    if row else ""
                )
                before_sub2api = int(
                    getattr(row, "sub2api_device_id", 0) or 0
                ) if row else 0
                if parent_id in desired:
                    if row is None:
                        row = GptBusinessAutomationPolicyModel(
                            business_account_id=parent_id,
                            created_at=now,
                            updated_at=now,
                        )
                        policies[parent_id] = row
                    if (
                        before_target == wanted_target_id
                        and before_provider in {"", "cpa"}
                        and before_sub2api <= 0
                    ):
                        row.delivery_type = "cpa"
                        row.sub2api_device_id = None
                        unchanged.append(parent_id)
                        # A retained stale binding is useful for showing which
                        # parents belonged to the deleted device, but it must
                        # never remain runnable without a real delivery target.
                        if target is None and bool(row.auto_rotation_enabled):
                            row.auto_rotation_enabled = False
                            row.revision = int(row.revision or 0) + 1
                            row.updated_at = now
                            session.add(row)
                            disabled.append(parent_id)
                        elif (
                            target is not None
                            and not bool(row.auto_rotation_enabled)
                        ):
                            row.auto_rotation_enabled = True
                            row.revision = int(row.revision or 0) + 1
                            row.updated_at = now
                            session.add(row)
                            enabled.append(parent_id)
                        continue
                    row.cpa_target_id = wanted_target_id
                    row.sub2api_device_id = None
                    row.delivery_type = "cpa"
                    row.auto_rotation_enabled = True
                    row.revision = int(row.revision or 0) + 1
                    row.updated_at = now
                    session.add(row)
                    enabled.append(parent_id)
                    if before_target > 0 or before_sub2api > 0 or before_provider == "sub2api":
                        moved.append(parent_id)
                    else:
                        added.append(parent_id)
                else:
                    # ``currently_bound`` guarantees a persisted row here.
                    if bool(row.auto_rotation_enabled):  # type: ignore[union-attr]
                        disabled.append(parent_id)
                    row.cpa_target_id = None  # type: ignore[union-attr]
                    row.delivery_type = ""  # type: ignore[union-attr]
                    row.auto_rotation_enabled = False  # type: ignore[union-attr]
                    row.revision = int(row.revision or 0) + 1  # type: ignore[union-attr]
                    row.updated_at = now  # type: ignore[union-attr]
                    session.add(row)
                    removed.append(parent_id)
            session.commit()

            serialized = []
            for parent_id in sorted(affected):
                row = policies[parent_id]
                result = _serialize_business_automation_policy(row, parent_id)
                result["cpa_target"] = (
                    target if result.get("cpa_target_id") == wanted_target_id else None
                )
                serialized.append(result)

    return {
        "ok": True,
        "cpa_target": target,
        "cpa_target_state": target_state,
        "cpa_target_id": wanted_target_id,
        "target_revision": current_target_revision,
        "parent_ids": sorted(desired),
        "added_parent_ids": added,
        "moved_parent_ids": moved,
        "removed_parent_ids": removed,
        "unchanged_parent_ids": unchanged,
        "enabled_parent_ids": enabled,
        "disabled_parent_ids": disabled,
        "items": serialized,
        "total": len(serialized),
        # Kept as a compatibility-shaped status for older clients.  Binding a
        # device is configuration only and must never populate an empty mother.
        "initial_fill": {
            "ok": True,
            "enabled": False,
            "created": 0,
            "existing": 0,
            "job_ids": [],
            "existing_job_ids": [],
            "blocked": [],
        },
    }


def put_business_sub2api_device_parents(
    device_id: int,
    body: BizSub2ApiDeviceParentsPutRequest,
):
    """Atomically replace one Sub2API device's BUSINESS mother bindings.

    Binding is the automatic-rotation switch.  A mother can belong to exactly
    one CPA or Sub2API delivery target; migration clears the other namespace in
    the same commit.  Disabled/missing devices are cleanup-only.
    """
    try:
        wanted_device_id = int(device_id)
    except (TypeError, ValueError):
        raise HTTPException(400, "Sub2API 设备 ID 无效")
    if wanted_device_id <= 0:
        raise HTTPException(400, "Sub2API 设备 ID 必须为正整数")

    desired_ids: List[int] = []
    seen: set[int] = set()
    for value in body.parent_ids:
        try:
            parent_id = int(value)
        except (TypeError, ValueError):
            raise HTTPException(400, f"无效的 BUSINESS 母号 ID: {value}")
        if parent_id <= 0:
            raise HTTPException(400, f"无效的 BUSINESS 母号 ID: {value}")
        if parent_id not in seen:
            seen.add(parent_id)
            desired_ids.append(parent_id)
    if len(desired_ids) > 500:
        raise HTTPException(400, "单个 Sub2API 设备最多选择 500 个母号")
    desired = set(desired_ids)
    try:
        expected_revisions = {
            int(parent_id): int(revision)
            for parent_id, revision in body.expected_revisions.items()
        }
    except (TypeError, ValueError):
        raise HTTPException(400, "expected_revisions 无效")
    if any(
        parent_id <= 0 or revision < 0
        for parent_id, revision in expected_revisions.items()
    ):
        raise HTTPException(400, "expected_revisions 中的母号 ID 和版本必须为非负整数")

    with Session(engine) as session:
        dialect = session.get_bind().dialect.name
        if dialect == "sqlite":
            session.connection().exec_driver_sql("BEGIN IMMEDIATE")
            device = session.get(SyncDeviceModel, wanted_device_id)
        else:
            device = session.exec(
                select(SyncDeviceModel)
                .where(SyncDeviceModel.id == wanted_device_id)
                .with_for_update()
            ).first()
        current_updated_at = _iso_utc(device.updated_at) if device else ""
        expected_updated_at = str(body.expected_device_updated_at or "").strip()
        if device and expected_updated_at != current_updated_at:
            raise HTTPException(409, {
                "code": "sub2api_device_revision_conflict",
                "message": "Sub2API 设备配置已被其他页面更新，请刷新后重试",
                "expected_updated_at": expected_updated_at,
                "current_updated_at": current_updated_at,
            })

        public_target = _safe_sub2api_target(
            wanted_device_id,
            session=session,
        )
        configured = bool(
            device
            and public_target
            and bool(device.enabled)
            and str(device.api_url or "").strip()
            and str(device.api_key or "").strip()
        )
        target_state = (
            "configured" if configured
            else "disabled" if device and public_target
            else "missing"
        )

        policy_query = select(GptBusinessAutomationPolicyModel).where(
            GptBusinessAutomationPolicyModel.sub2api_device_id
            == wanted_device_id
        )
        if desired:
            policy_query = select(GptBusinessAutomationPolicyModel).where(or_(
                GptBusinessAutomationPolicyModel.sub2api_device_id
                == wanted_device_id,
                GptBusinessAutomationPolicyModel.business_account_id.in_(desired),  # type: ignore[union-attr]
            ))
        if dialect != "sqlite":
            policy_query = policy_query.with_for_update()
        policy_rows = session.exec(policy_query).all()
        policies = {int(row.business_account_id): row for row in policy_rows}
        currently_bound = {
            parent_id
            for parent_id, row in policies.items()
            if int(getattr(row, "sub2api_device_id", 0) or 0)
            == wanted_device_id
            and str(getattr(row, "delivery_type", "") or "sub2api").strip().lower()
            in {"", "sub2api"}
        }
        new_to_unavailable = sorted(desired - currently_bound)
        if not configured and new_to_unavailable:
            raise HTTPException(409 if device else 404, {
                "code": "business_sub2api_device_unavailable",
                "message": "指定的 Sub2API 设备不可用，只能移除已绑定母号",
                "sub2api_device_id": wanted_device_id,
                "state": target_state,
                "new_parent_ids": new_to_unavailable,
            })
        affected = desired | currently_bound
        missing_expected = sorted(affected - set(expected_revisions))
        if missing_expected:
            raise HTTPException(409, {
                "code": "business_sub2api_device_selection_revision_required",
                "message": "母号选择已变化，请刷新后重新保存整组选择",
                "missing_parent_ids": missing_expected,
            })

        parents = _lock_business_parent_state_mutation(session, sorted(affected))
        missing_parents = sorted(desired - set(parents))
        if missing_parents:
            raise HTTPException(404, {
                "code": "business_parent_not_found",
                "message": "部分 BUSINESS 母号不存在",
                "parent_ids": missing_parents,
            })
        for parent_id in sorted(affected):
            row = policies.get(parent_id)
            current_revision = int(row.revision or 0) if row else 0
            if expected_revisions[parent_id] != current_revision:
                raise HTTPException(409, {
                    "code": "business_automation_policy_revision_conflict",
                    "message": "母号自动化设置已被其他页面更新，请刷新后重试",
                    "business_account_id": parent_id,
                    "expected_revision": expected_revisions[parent_id],
                    "current_revision": current_revision,
                })

        binding_eligibility: Dict[int, dict] = {}
        for parent_id in sorted(desired):
            row = policies.get(parent_id)
            parent = parents[parent_id]
            eligibility = _business_cpa_device_binding_eligibility(
                parent,
                _business_account_team_session_status(parent),
            )
            binding_eligibility[parent_id] = eligibility
            already_bound_here = bool(
                row
                and int(getattr(row, "sub2api_device_id", 0) or 0)
                == wanted_device_id
                and str(getattr(row, "delivery_type", "") or "sub2api").strip().lower()
                in {"", "sub2api"}
            )
            if configured and not already_bound_here and not eligibility.get("eligible"):
                raise HTTPException(409, {
                    "code": "business_parent_not_eligible_for_device_binding",
                    "message": "只能将已登录且当前可用的 BUSINESS 母号新绑定到 Sub2API 设备",
                    "business_account_id": parent_id,
                    "logged_in": bool(eligibility.get("logged_in")),
                    "blockers": list(eligibility.get("blockers") or []),
                })

        now = _utcnow()
        added: List[int] = []
        moved: List[int] = []
        removed: List[int] = []
        unchanged: List[int] = []
        enabled: List[int] = []
        disabled: List[int] = []
        for parent_id in sorted(affected):
            row = policies.get(parent_id)
            before_provider = (
                str(getattr(row, "delivery_type", "") or "").strip().lower()
                if row else ""
            )
            before_sub = int(
                getattr(row, "sub2api_device_id", 0) or 0
            ) if row else 0
            before_cpa = int(getattr(row, "cpa_target_id", 0) or 0) if row else 0
            if parent_id in desired:
                if row is None:
                    row = GptBusinessAutomationPolicyModel(
                        business_account_id=parent_id,
                        created_at=now,
                        updated_at=now,
                    )
                    policies[parent_id] = row
                same_target = bool(
                    before_sub == wanted_device_id
                    and before_provider in {"", "sub2api"}
                    and before_cpa <= 0
                )
                row.cpa_target_id = None
                row.sub2api_device_id = wanted_device_id
                row.delivery_type = "sub2api"
                should_enable = configured
                changed = not same_target or bool(row.auto_rotation_enabled) != should_enable
                row.auto_rotation_enabled = should_enable
                if changed:
                    row.revision = int(row.revision or 0) + 1
                    row.updated_at = now
                    session.add(row)
                if same_target:
                    unchanged.append(parent_id)
                    if changed:
                        (enabled if should_enable else disabled).append(parent_id)
                else:
                    (moved if before_cpa > 0 or before_sub > 0 or before_provider else added).append(parent_id)
                    if should_enable:
                        enabled.append(parent_id)
            else:
                if bool(row.auto_rotation_enabled):  # type: ignore[union-attr]
                    disabled.append(parent_id)
                row.sub2api_device_id = None  # type: ignore[union-attr]
                row.delivery_type = ""  # type: ignore[union-attr]
                row.auto_rotation_enabled = False  # type: ignore[union-attr]
                row.revision = int(row.revision or 0) + 1  # type: ignore[union-attr]
                row.updated_at = now  # type: ignore[union-attr]
                session.add(row)
                removed.append(parent_id)
        session.commit()

        serialized = [
            _serialize_business_automation_policy(policies[parent_id], parent_id)
            for parent_id in sorted(affected)
        ]

    return {
        "ok": True,
        "provider": "sub2api",
        "sub2api_device": public_target,
        "sub2api_device_state": target_state,
        "sub2api_device_id": wanted_device_id,
        "device_updated_at": current_updated_at,
        "parent_ids": sorted(desired),
        "added_parent_ids": added,
        "moved_parent_ids": moved,
        "removed_parent_ids": removed,
        "unchanged_parent_ids": unchanged,
        "enabled_parent_ids": enabled,
        "disabled_parent_ids": disabled,
        "items": serialized,
        "total": len(serialized),
        # Compatibility only: Sub2API binding does not auto-invite an account.
        "initial_fill": {
            "ok": True,
            "enabled": False,
            "created": 0,
            "existing": 0,
            "job_ids": [],
            "blocked": [],
        },
    }


# -- Safe BUSINESS mother delivery-device migration -------------------------

def _business_device_public_name(
    provider: str,
    device_id: int,
    value: Any,
    *,
    api_url: str = "",
) -> str:
    """Return a non-endpoint device label safe for migration DTOs.

    CPA's legacy registry used the API URL as the name fallback.  A private
    endpoint must not become public merely because it was persisted in a
    display-name field, including for old durable migration jobs.
    """
    normalized_provider = str(provider or "").strip().lower()
    fallback = "Sub2API" if normalized_provider == "sub2api" else "CPA"
    fallback = f"{fallback} {int(device_id)}"
    raw = str(value or "").strip()
    endpoint = str(api_url or "").strip().rstrip("/")
    raw_without_slash = raw.rstrip("/")
    looks_like_url = bool(re.match(r"(?i)^[a-z][a-z0-9+.-]*://", raw))
    if (
        not raw
        or looks_like_url
        or (endpoint and raw_without_slash.casefold() == endpoint.casefold())
    ):
        return fallback
    return raw[:200]


def _safe_business_device_migration_diagnostic(
    value: Any,
    *,
    limit: int = 1000,
) -> str:
    """Redact transport credentials/endpoints before durable job storage.

    Migration adapters can include their request URL, response headers or API
    key in an exception.  Jobs are recoverable and their errors are returned to
    the browser, so both persistence and serialization use this fail-closed
    boundary.
    """
    text = str(value or "")
    try:
        from api.gpt_plan_operations import _sanitize_background_task_text

        text = _sanitize_background_task_text(text)
    except Exception:
        text = re.sub(
            r"(?i)\bBearer\s+[A-Za-z0-9._~+/=-]+",
            "Bearer [redacted]",
            text,
        )
    text = re.sub(r"(?i)https?://[^\s\"'<>]+", "[device-endpoint]", text)
    text = re.sub(
        r"(?i)\b(api[_ -]?key|x-api-key|authorization|client[_ -]?secret|secret)"
        r"\b\s*[\"']?\s*[:=]\s*[\"']?[^\s,;\"'}]+",
        lambda match: f"{match.group(1)}=[redacted]",
        text,
    )
    bounded = max(0, min(int(limit), 2000))
    return text[:bounded]


def _parse_business_delivery_device_ref(value: Any) -> tuple[str, int, str]:
    raw = str(value or "").strip().lower()
    match = re.fullmatch(r"(cpa|sub2api):([1-9][0-9]*)", raw)
    if not match:
        raise HTTPException(400, "target_device_ref 必须是 cpa:<id> 或 sub2api:<id>")
    provider = str(match.group(1))
    device_id = int(match.group(2))
    return provider, device_id, f"{provider}:{device_id}"


def _business_delivery_target_snapshot(provider: str, device_id: int) -> dict:
    """Resolve one configured target without copying credentials into a job."""
    normalized = str(provider or "").strip().lower()
    wanted = int(device_id)
    if normalized == "cpa":
        from api.gpt_plan_operations import _cpa_sync_target_by_id

        target = _cpa_sync_target_by_id(wanted)
        if not isinstance(target, dict):
            raise HTTPException(404, "指定的 CPA 设备不存在")
        api_url = str(target.get("api_url") or "").strip().rstrip("/")
        api_key = str(target.get("api_key") or "").strip()
        if not api_url or not api_key:
            raise HTTPException(409, "指定的 CPA 设备配置不完整")
        name = _business_device_public_name(
            "cpa", wanted, target.get("name"), api_url=api_url,
        )
        epoch_source = (
            f"cpa:{wanted}:{api_url.casefold()}:"
            f"{hashlib.sha256(api_key.encode('utf-8')).hexdigest()}"
        )
    elif normalized == "sub2api":
        from api.gpt_plan_operations import _sub2api_device_or_error

        target = _sub2api_device_or_error(wanted)
        api_url = str(target.get("api_url") or "").strip().rstrip("/")
        api_key = str(target.get("api_key") or "").strip()
        if not api_url or not api_key:
            raise HTTPException(409, "指定的 Sub2API 设备配置不完整")
        name = _business_device_public_name(
            "sub2api", wanted, target.get("name"), api_url=api_url,
        )
        epoch_source = (
            f"sub2api:{wanted}:{api_url.casefold()}:"
            f"{hashlib.sha256(api_key.encode('utf-8')).hexdigest()}"
        )
    else:
        raise HTTPException(400, "设备类型仅支持 CPA 或 Sub2API")
    return {
        "provider": normalized,
        "device_id": wanted,
        "device_ref": f"{normalized}:{wanted}",
        "name": name,
        "state": "configured",
        # The hash fences endpoint repoints without exposing URL/API key.
        "epoch": hashlib.sha256(epoch_source.encode("utf-8")).hexdigest(),
    }


def _business_policy_device_snapshot(
    row: Optional[GptBusinessAutomationPolicyModel],
    parent_id: int,
) -> dict:
    policy = _serialize_business_automation_policy(row, int(parent_id))
    provider = str(policy.get("delivery_type") or "").strip().lower()
    if provider == "cpa":
        device_id = int(policy.get("cpa_target_id") or 0)
    elif provider == "sub2api":
        device_id = int(policy.get("sub2api_device_id") or 0)
    else:
        provider, device_id = "", 0
    target = _business_delivery_target(policy) if device_id > 0 else None
    return {
        "provider": provider,
        "device_id": device_id or None,
        "device_ref": f"{provider}:{device_id}" if provider and device_id else "",
        "name": _business_device_public_name(
            provider,
            device_id,
            (target or {}).get("name"),
        ) if provider and device_id else "",
        "state": str((target or {}).get("state") or ("missing" if device_id else "unbound")),
        "revision": int(policy.get("revision") or 0),
        "auto_rotation_enabled": bool(policy.get("auto_rotation_enabled")),
    }


def _business_child_delivery_links(child: GptProAccountModel) -> tuple[List[dict], List[str]]:
    """Return exact persisted links and incomplete-link diagnostics."""
    extra = _json_dict(child.extra_json)
    links: List[dict] = []
    incomplete: List[str] = []
    try:
        cpa_id = int(extra.get("cpa_synced_to_id") or extra.get("cpa_device_id") or 0)
    except (TypeError, ValueError):
        cpa_id = 0
    cpa_auth = str(extra.get("cpa_auth_name") or "").strip()
    cpa_evidence = bool(extra.get("cpa_synced") or cpa_id or cpa_auth)
    if cpa_id > 0 and cpa_auth:
        links.append({
            "provider": "cpa",
            "device_id": cpa_id,
            "device_ref": f"cpa:{cpa_id}",
            "remote_id": cpa_auth,
            "link_epoch": str(extra.get("cpa_synced_at") or ""),
        })
    elif cpa_evidence:
        incomplete.append("CPA 本地关联缺少设备 ID 或精确凭据名")

    try:
        sub_id = int(extra.get("sub2api_device_id") or 0)
    except (TypeError, ValueError):
        sub_id = 0
    sub_remote = str(extra.get("sub2api_remote_account_id") or "").strip()
    sub_evidence = bool(sub_id or sub_remote or extra.get("sub2api_sync_pending"))
    if sub_id > 0 and sub_remote:
        links.append({
            "provider": "sub2api",
            "device_id": sub_id,
            "device_ref": f"sub2api:{sub_id}",
            "remote_id": sub_remote,
            "link_epoch": str(extra.get("sub2api_synced_at") or ""),
        })
    elif sub_evidence and not bool(extra.get("sub2api_sync_pending")):
        incomplete.append("Sub2API 本地关联缺少设备 ID 或远端账号 ID")
    return links, incomplete


def _business_child_remote_link_on_device(
    source_target: dict,
    email: str,
) -> Optional[dict]:
    """Resolve one child on a source device without trusting an email-only delete.

    The result is credential-free and is suitable for the immutable migration
    request.  A missing result means that the provider returned an authoritative
    complete inventory with no exact match.  Ambiguous or incomplete provider
    responses fail closed.
    """
    provider = str(source_target.get("provider") or "").strip().lower()
    device_id = int(source_target.get("device_id") or 0)
    device_ref = str(source_target.get("device_ref") or "")
    expected_email = str(email or "").strip()
    if (
        provider not in {"cpa", "sub2api"}
        or device_id <= 0
        or device_ref != f"{provider}:{device_id}"
        or not expected_email
        or not str(source_target.get("epoch") or "")
    ):
        raise HTTPException(409, "原设备核验快照不完整")
    current_target = _business_delivery_target_snapshot(provider, device_id)
    if str(current_target.get("epoch") or "") != str(source_target.get("epoch") or ""):
        raise HTTPException(409, "原设备配置在迁移核验期间已变化")

    if provider == "sub2api":
        from api.gpt_plan_operations import _sub2api_device_or_error
        from services.sub2api_admin import (
            Sub2ApiAccountAmbiguous,
            Sub2ApiAccountNotFound,
            Sub2ApiAdminError,
            find_account_exact,
        )

        device = _sub2api_device_or_error(device_id)
        try:
            identity = find_account_exact(
                device["api_url"], device["api_key"], email=expected_email,
            )
        except Sub2ApiAccountNotFound:
            return None
        except Sub2ApiAccountAmbiguous as exc:
            raise HTTPException(409, "原 Sub2API 设备存在多个同邮箱账号，请先去重") from exc
        except Sub2ApiAdminError as exc:
            raise HTTPException(502, "无法完整核验原 Sub2API 设备账号") from exc
        remote_id = str(identity.get("id") or "").strip()
        if not remote_id:
            raise HTTPException(502, "原 Sub2API 账号缺少可验证远端 ID")
        return {
            "provider": provider,
            "device_id": device_id,
            "device_ref": device_ref,
            "remote_id": remote_id,
            "link_epoch": "",
            "origin": "remote_probe",
        }

    from api.delivery_devices import _internal_device_or_error
    from services.cpa_manager import list_auth_files

    internal = _internal_device_or_error("cpa", device_id)
    try:
        files = list_auth_files(
            api_url=str(internal.get("api_url") or ""),
            api_key=str(internal.get("api_key") or ""),
        )
    except Exception as exc:
        raise HTTPException(502, "无法完整核验原 CPA 设备凭证") from exc
    normalized_email = expected_email.casefold()
    safe_email = re.sub(r"[^a-zA-Z0-9._-]", "_", expected_email).casefold()
    matches: List[dict] = []
    for raw in files:
        if not isinstance(raw, dict):
            continue
        embedded = str(raw.get("email") or raw.get("account") or "").strip().casefold()
        name = str(raw.get("name") or "").strip().replace("\\", "/").rsplit("/", 1)[-1]
        stem = name[:-5] if name.casefold().endswith(".json") else name
        matched = (
            embedded == normalized_email
            if embedded
            else stem.casefold() in {normalized_email, safe_email}
        )
        if matched:
            if not re.fullmatch(r"[A-Za-z0-9@._-]{1,255}", name):
                raise HTTPException(502, "原 CPA 凭证缺少可验证文件名")
            matches.append({"remote_id": name})
    remote_ids = {str(item["remote_id"]) for item in matches}
    if len(matches) > 1:
        raise HTTPException(409, "原 CPA 设备存在多个同邮箱凭证，请先去重")
    if not remote_ids:
        return None
    return {
        "provider": provider,
        "device_id": device_id,
        "device_ref": device_ref,
        "remote_id": next(iter(remote_ids)),
        "link_epoch": "",
        "origin": "remote_probe",
    }


_BUSINESS_DEVICE_MIGRATION_PENDING_FIELDS = (
    "cpa_sync_pending", "cpa_sync_compensation_pending", "cpa_cleanup_pending",
    "cpa_disable_pending", "cpa_auto_upload_pending", "cpa_migration_pending",
    "sub2api_sync_pending",
)


def _business_device_binding_migration_preview(
    parent_id: int,
    target_device_ref: str,
) -> dict:
    provider, target_id, canonical = _parse_business_delivery_device_ref(
        target_device_ref
    )
    target = _business_delivery_target_snapshot(provider, target_id)
    now = _utcnow()
    blockers: List[dict] = []
    warnings: List[dict] = []
    children: List[dict] = []
    with Session(engine) as session:
        parent = session.get(GptBusinessAccountModel, int(parent_id))
        if not parent:
            raise HTTPException(404, "BUSINESS 母号不存在")
        policy_row = session.get(GptBusinessAutomationPolicyModel, int(parent_id))
        source = _business_policy_device_snapshot(policy_row, int(parent_id))
        source_ref = str(source.get("device_ref") or "")
        policy_source_target: dict = {}
        policy_source_error = ""
        if source_ref and source_ref != canonical:
            try:
                policy_source_target = _business_delivery_target_snapshot(
                    str(source.get("provider") or ""),
                    int(source.get("device_id") or 0),
                )
            except HTTPException:
                policy_source_error = "母号原设备不存在或配置不完整，无法确认旧账号已清理"
        memberships = session.exec(
            select(GptBusinessChildMembershipModel)
            .where(GptBusinessChildMembershipModel.business_account_id == int(parent_id))
            .where(GptBusinessChildMembershipModel.ended_at.is_(None))  # type: ignore[union-attr]
            .order_by(col(GptBusinessChildMembershipModel.id))
        ).all()
        managed = [row for row in memberships if int(row.pro_account_id or 0) > 0]
        unmanaged = [row for row in memberships if int(row.pro_account_id or 0) <= 0]
        if unmanaged:
            warnings.append({
                "code": "unmanaged_members_not_migrated",
                "message": f"{len(unmanaged)} 个手动成员没有本地 OAuth 账号，不参与设备凭证迁移",
            })
        eligibility = _business_cpa_device_binding_eligibility(
            parent, _business_account_team_session_status(parent),
        )
        if canonical != str(source.get("device_ref") or "") and not bool(
            eligibility.get("eligible")
        ):
            blockers.append({
                "code": "parent_not_eligible",
                "message": "该母号当前不满足新设备绑定条件",
                "reasons": list(eligibility.get("blockers") or []),
            })
        parent_lease = session.get(
            GptBusinessAllocationLeaseModel, f"parent:{int(parent_id)}",
        )
        if parent_lease and (_aware(parent_lease.expires_at) or now) > now:
            blockers.append({
                "code": "parent_busy",
                "message": "母号正在执行邀请、轮换或其他设备操作",
                "job_id": str(parent_lease.job_id or ""),
            })

        for membership in managed:
            child_id = int(membership.pro_account_id or 0)
            child = session.get(GptProAccountModel, child_id)
            item = {
                "child_id": child_id,
                "membership_id": int(membership.id or 0),
                "email": str(membership.email or ""),
                "current_device_ref": "",
                "state": "pending",
                "can_migrate": True,
                "reason": "",
                "_source_link": None,
            }
            reason = ""
            links: List[dict] = []
            incomplete: List[str] = []
            if not child:
                reason = "本地 GPT 子号不存在"
            elif int(child.business_parent_id or 0) != int(parent_id):
                reason = "子号当前归属与母号不一致"
            elif not bool(child.enabled) or bool(child.dangerous) or str(child.refund_status or "").strip():
                reason = "子号已禁用、Dead 或处于退款状态"
            elif not str(membership.remote_user_id or "").strip():
                reason = "子号尚未成为工作区正式成员"
            else:
                links, incomplete = _business_child_delivery_links(child)
                extra = _json_dict(child.extra_json)
                pending = [
                    key for key in _BUSINESS_DEVICE_MIGRATION_PENDING_FIELDS
                    if bool(extra.get(key))
                ]
                claim = session.get(GptProAccountOperationLeaseModel, child_id)
                if claim and (_aware(claim.expires_at) or now) > now:
                    reason = f"子号正在执行 {claim.operation}"
                elif pending:
                    reason = "子号存在未完成设备操作: " + ", ".join(pending)
                elif incomplete:
                    reason = "；".join(incomplete)
                elif len(links) > 1:
                    reason = "子号同时存在 CPA 与 Sub2API 关联，需先人工核对"
                elif links:
                    link = links[0]
                    link["origin"] = "persisted"
                    item["current_device_ref"] = str(link.get("device_ref") or "")
                    item["_source_link"] = dict(link)
                    actual_ref = str(link.get("device_ref") or "")
                    policy_ref = str(source.get("device_ref") or "")
                    if actual_ref == canonical:
                        item["state"] = "already_target"
                    else:
                        try:
                            item["_source_target"] = _business_delivery_target_snapshot(
                                str(link.get("provider") or ""),
                                int(link.get("device_id") or 0),
                            )
                        except HTTPException:
                            reason = "子号原设备不存在或配置不完整，无法确认安全移除"
                    if not reason and actual_ref != policy_ref:
                        warnings.append({
                            "code": "child_policy_link_mismatch",
                            "message": "子号实际设备与母号策略不同，将以子号精确关联迁移",
                            "child_id": child_id,
                            "email": str(membership.email or ""),
                            "actual_device_ref": actual_ref,
                            "policy_device_ref": policy_ref,
                        })
                else:
                    if source_ref and source_ref != canonical:
                        if policy_source_error or not policy_source_target:
                            reason = policy_source_error or "母号原设备无法核验"
                        else:
                            try:
                                recovered = _business_child_remote_link_on_device(
                                    policy_source_target,
                                    str(child.email or membership.email or ""),
                                )
                            except HTTPException as exc:
                                reason = str(exc.detail or "原设备账号核验失败")
                            else:
                                item["_source_target"] = dict(policy_source_target)
                                if recovered:
                                    item["state"] = "source_recovered"
                                    item["current_device_ref"] = source_ref
                                    item["_source_link"] = dict(recovered)
                                    warnings.append({
                                        "code": "child_source_link_recovered",
                                        "message": "子号本地设备关联缺失，已从母号原设备唯一核验",
                                        "child_id": child_id,
                                        "email": str(membership.email or ""),
                                        "actual_device_ref": source_ref,
                                    })
                                else:
                                    item["state"] = "source_absent"
                                    item["_source_absence_confirmed"] = True
                    else:
                        item["state"] = "unsynced"
            if reason:
                item.update({"can_migrate": False, "state": "blocked", "reason": reason})
                blockers.append({
                    "code": "child_not_migratable",
                    "message": reason,
                    "child_id": child_id,
                    "email": str(membership.email or ""),
                })
            children.append(item)

    return {
        "ok": True,
        "allowed": not blockers,
        "parent_id": int(parent_id),
        "policy_revision": int(source.get("revision") or 0),
        "source": source,
        "target": target,
        "managed_child_count": len(children),
        "unmanaged_member_count": len(unmanaged),
        "membership_ids": [int(row.id or 0) for row in memberships],
        "children": children,
        "blockers": blockers,
        "warnings": warnings,
    }


def _public_business_device_migration_target(
    value: Any,
    *,
    include_revision: bool = False,
) -> dict:
    raw = dict(value) if isinstance(value, dict) else {}
    allowed = {"provider", "device_id", "device_ref", "name", "state"}
    if include_revision:
        allowed.add("revision")
    result = {key: item for key, item in raw.items() if key in allowed}
    provider = str(result.get("provider") or "")
    try:
        device_id = int(result.get("device_id") or 0)
    except (TypeError, ValueError):
        device_id = 0
    if provider and device_id:
        result["name"] = _business_device_public_name(
            provider, device_id, result.get("name"),
        )
    else:
        result["name"] = ""
    return result


def _public_business_device_migration_preview(preview: dict) -> dict:
    result = dict(preview)
    result["source"] = _public_business_device_migration_target(
        preview.get("source"), include_revision=True,
    )
    result["target"] = _public_business_device_migration_target(
        preview.get("target"),
    )
    result["children"] = [
        {key: value for key, value in dict(item).items() if not str(key).startswith("_")}
        for item in list(preview.get("children") or [])
    ]
    result.pop("membership_ids", None)
    return result


def preview_business_device_binding_migration(
    account_id: int,
    target_device_ref: str = Query(...),
):
    return _public_business_device_migration_preview(
        _business_device_binding_migration_preview(
            int(account_id), target_device_ref,
        )
    )


def _is_business_device_binding_migration_job(
    job: Optional[GptBusinessAllocationJobModel],
) -> bool:
    return bool(
        job
        and str(_json_dict(job.request_json).get("job_kind") or "")
        == _DEVICE_BINDING_MIGRATION_KIND
    )


def _business_device_migration_status(job: GptBusinessAllocationJobModel) -> dict:
    request = _json_dict(job.request_json)
    actions = _json_dict(job.action_state_json)
    raw_items = actions.get("children") if isinstance(actions.get("children"), dict) else {}
    requested_children = request.get("children") if isinstance(request.get("children"), list) else []
    children: List[dict] = []
    completed = 0
    failed = 0
    for child in requested_children:
        if not isinstance(child, dict):
            continue
        child_id = int(child.get("child_id") or 0)
        action = raw_items.get(str(child_id))
        action = action if isinstance(action, dict) else {}
        state = str(action.get("state") or "pending")
        if state == "completed":
            completed += 1
        elif state in {"failed", "action_required"}:
            failed += 1
        source_link = child.get("source_link") if isinstance(child.get("source_link"), dict) else {}
        children.append({
            "child_id": child_id,
            "membership_id": int(child.get("membership_id") or 0),
            "email": str(child.get("email") or ""),
            "state": state,
            "stage": str(action.get("stage") or "pending"),
            "error": _safe_business_device_migration_diagnostic(
                action.get("error"), limit=500,
            ),
            "source_device_ref": str(source_link.get("device_ref") or ""),
            "target_device_ref": str((request.get("target") or {}).get("device_ref") or ""),
            "checkpoints": {
                key: bool(action.get(key))
                for key in (
                    "old_cleanup_required", "source_removed",
                    "source_absence_confirmed", "new_uploaded",
                    "new_verified", "old_cleanup_confirmed", "remote_mutated",
                )
                if key in action
            },
        })
    total = len(children)
    return {
        "ok": True,
        "job_id": str(job.id),
        "operation_id": str(request.get("operation_id") or ""),
        "state": str(job.state or "queued"),
        "status": str(job.state or "queued"),
        "stage": str(job.stage or "preflight"),
        "retryable": bool(job.retryable),
        "error": _safe_business_device_migration_diagnostic(
            job.error, limit=1000,
        ),
        "parent_id": int(job.selected_business_account_id or 0),
        "expected_policy_revision": int(
            request.get("expected_policy_revision") or 0
        ),
        "attempt_count": int(job.attempt_count or 0),
        "remote_mutated": bool(job.remote_mutated),
        "source": _public_business_device_migration_target(
            request.get("source"), include_revision=True,
        ),
        "target": _public_business_device_migration_target(
            request.get("target"),
        ),
        "progress": {
            "total": total,
            "completed": completed,
            "failed": failed,
            "percent": 100 if total == 0 and job.state == "completed" else (
                int(completed * 100 / total) if total else 0
            ),
        },
        "children": children,
        "policy_switched": bool(actions.get("policy_switched")),
        "created_at": _iso_utc(job.created_at),
        "updated_at": _iso_utc(job.updated_at),
        "completed_at": _iso_utc(job.completed_at),
    }


def _get_business_device_migration_job_by_id(
    job_id: str,
) -> GptBusinessAllocationJobModel:
    """Load a migration job without relying on an untrusted parent id.

    Internal recovery paths only know the durable job id after a restart.  The
    parent is read from the job's immutable request and is validated by the
    public, parent-scoped wrapper below.
    """
    with Session(engine) as session:
        job = session.get(GptBusinessAllocationJobModel, str(job_id))
        if not _is_business_device_binding_migration_job(job):
            raise HTTPException(404, "母号设备迁移任务不存在")
        session.expunge(job)
        return job


def _get_business_device_migration_job(
    parent_id: int,
    job_id: str,
) -> GptBusinessAllocationJobModel:
    job = _get_business_device_migration_job_by_id(str(job_id))
    request = _json_dict(job.request_json)
    request_parent_id = int(request.get("parent_id") or 0)
    if (
        int(job.selected_business_account_id or 0) != int(parent_id)
        or request_parent_id != int(parent_id)
    ):
        raise HTTPException(404, "母号设备迁移任务不存在")
    return job


def list_business_device_binding_migrations(
    account_id: int,
    active_only: bool = True,
    operation_id: str = Query(""),
    limit: int = Query(20, ge=1, le=100),
):
    """List durable migration jobs so UI refreshes can recover progress.

    ``operation_id`` is optional.  When supplied it provides a stable recovery
    lookup without requiring the browser to retain the generated job id.
    """
    normalized_operation_id = str(operation_id or "").strip()
    if (
        normalized_operation_id
        and not _MASTER_DISPATCH_OPERATION_RE.fullmatch(normalized_operation_id)
    ):
        raise HTTPException(400, "operation_id 格式无效")
    with Session(engine) as session:
        query = select(GptBusinessAllocationJobModel).where(
            GptBusinessAllocationJobModel.selected_business_account_id
            == int(account_id)
        )
        if normalized_operation_id:
            query = query.where(
                GptBusinessAllocationJobModel.idempotency_key
                == (
                    "business-device-binding-migration:"
                    f"{int(account_id)}:{normalized_operation_id}"
                )
            )
        if active_only:
            query = query.where(
                GptBusinessAllocationJobModel.state.in_([
                    "queued", "retry_queued", "running", "action_required",
                    "failed", "partial",
                ])
            )
        # request_json is deliberately queried using both compact and default
        # JSON encodings because old rows can have either representation.
        query = query.where(or_(
            GptBusinessAllocationJobModel.request_json.contains(
                '"job_kind": "device_binding_migration"'
            ),
            GptBusinessAllocationJobModel.request_json.contains(
                '"job_kind":"device_binding_migration"'
            ),
        ))
        rows = session.exec(
            query.order_by(
                col(GptBusinessAllocationJobModel.updated_at).desc()
            ).limit(int(limit))
        ).all()
        items = [_business_device_migration_status(row) for row in rows]
    return {"ok": True, "items": items, "total": len(items)}


def get_business_device_binding_migration(
    account_id: int,
    job_id: str,
):
    return _business_device_migration_status(
        _get_business_device_migration_job(int(account_id), str(job_id))
    )


def _business_device_migration_request(
    preview: dict,
    operation_id: str,
) -> dict:
    source = dict(preview.get("source") or {})
    target = dict(preview.get("target") or {})
    children = []
    for item in list(preview.get("children") or []):
        if not isinstance(item, dict):
            continue
        source_link = item.get("_source_link")
        source_target = item.get("_source_target")
        children.append({
            "child_id": int(item.get("child_id") or 0),
            "membership_id": int(item.get("membership_id") or 0),
            "email": str(item.get("email") or ""),
            "source_link": dict(source_link) if isinstance(source_link, dict) else None,
            "source_target": dict(source_target) if isinstance(source_target, dict) else None,
            "source_absence_confirmed": bool(
                item.get("_source_absence_confirmed")
            ),
        })
    return {
        "job_kind": _DEVICE_BINDING_MIGRATION_KIND,
        "operation_id": str(operation_id),
        "parent_id": int(preview.get("parent_id") or 0),
        "expected_policy_revision": int(preview.get("policy_revision") or 0),
        "source": source,
        "target": target,
        "membership_ids": [int(value) for value in preview.get("membership_ids") or []],
        "children": children,
    }


def _business_device_migration_request_hash(request: dict) -> str:
    return hashlib.sha256(
        json.dumps(
            request, ensure_ascii=False, sort_keys=True, separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _claim_business_device_migration(job_id: str) -> str:
    now = _utcnow()
    expires = now + timedelta(seconds=ALLOCATION_LEASE_SECONDS)
    worker_token = f"device-migration-worker-{_uuid.uuid4().hex}"
    with Session(engine) as session:
        if session.get_bind().dialect.name == "sqlite":
            session.connection().exec_driver_sql("BEGIN IMMEDIATE")
            job = session.get(GptBusinessAllocationJobModel, str(job_id))
        else:
            job = session.exec(
                select(GptBusinessAllocationJobModel)
                .where(GptBusinessAllocationJobModel.id == str(job_id))
                .with_for_update()
            ).first()
        if not _is_business_device_binding_migration_job(job):
            raise HTTPException(404, "母号设备迁移任务不存在")
        if str(job.state or "") == "completed":
            session.rollback()
            return ""
        request = _json_dict(job.request_json)
        parent_id = int(request.get("parent_id") or 0)
        child_ids = sorted({
            int(item.get("child_id") or 0)
            for item in request.get("children") or []
            if isinstance(item, dict) and int(item.get("child_id") or 0) > 0
        })
        parent = session.get(GptBusinessAccountModel, parent_id)
        if not parent:
            raise HTTPException(404, "BUSINESS 母号不存在")
        policy = session.get(GptBusinessAutomationPolicyModel, parent_id)
        current = _business_policy_device_snapshot(policy, parent_id)
        expected_source = request.get("source") if isinstance(request.get("source"), dict) else {}
        if (
            int(current.get("revision") or 0)
            != int(request.get("expected_policy_revision") or 0)
            or str(current.get("device_ref") or "")
            != str(expected_source.get("device_ref") or "")
        ):
            raise HTTPException(409, {
                "code": "business_device_migration_policy_changed",
                "message": "母号设备绑定在迁移开始前已变化，请重新预览",
            })
        keys = [f"parent:{parent_id}", *[f"child:{value}" for value in child_ids]]
        for key in keys:
            lease = session.get(GptBusinessAllocationLeaseModel, key)
            if lease and (_aware(lease.expires_at) or now) <= now:
                session.delete(lease)
                session.flush()
                lease = None
            if lease:
                raise HTTPException(409, {
                    "code": "business_device_migration_busy",
                    "message": f"迁移资源正在被其他任务占用: {key}",
                    "job_id": str(lease.job_id or ""),
                })
            session.add(GptBusinessAllocationLeaseModel(
                resource_key=key,
                job_id=str(job_id),
                owner_token=worker_token,
                expires_at=expires,
                created_at=now,
                updated_at=now,
            ))
        for child_id in child_ids:
            claim = session.get(GptProAccountOperationLeaseModel, child_id)
            if claim and (_aware(claim.expires_at) or now) <= now:
                session.delete(claim)
                session.flush()
                claim = None
            if claim:
                raise HTTPException(409, {
                    "code": "business_device_migration_child_busy",
                    "message": f"子号 {child_id} 正在执行 {claim.operation}",
                })
            session.add(GptProAccountOperationLeaseModel(
                account_id=child_id,
                operation=_DEVICE_BINDING_MIGRATION_OPERATION,
                token=worker_token,
                expires_at=expires,
                created_at=now,
                updated_at=now,
            ))
        actions = _json_dict(job.action_state_json)
        action_children = actions.get("children") if isinstance(actions.get("children"), dict) else {}
        for child_id in child_ids:
            action_children.setdefault(str(child_id), {
                "state": "pending", "stage": "pending", "error": "",
            })
        actions["children"] = action_children
        job.state = "running"
        job.stage = "migrating_children"
        job.worker_token = worker_token
        job.attempt_count = int(job.attempt_count or 0) + 1
        job.started_at = job.started_at or now
        job.error = ""
        job.action_state_json = json.dumps(actions, ensure_ascii=False)
        job.updated_at = now
        session.add(job)
        try:
            session.commit()
        except IntegrityError as exc:
            session.rollback()
            raise HTTPException(409, "母号或子号刚被其他任务占用") from exc
    return worker_token


def _business_device_migration_claim_is_current(
    job_id: str,
    worker_token: str,
    child_ids: List[int],
) -> bool:
    now = _utcnow()
    with Session(engine) as session:
        job = session.get(GptBusinessAllocationJobModel, str(job_id))
        if (
            not job
            or str(job.state or "") != "running"
            or str(job.worker_token or "") != str(worker_token)
        ):
            return False
        request = _json_dict(job.request_json)
        parent_id = int(request.get("parent_id") or 0)
        for key in [f"parent:{parent_id}", *[f"child:{int(value)}" for value in child_ids]]:
            lease = session.get(GptBusinessAllocationLeaseModel, key)
            if not (
                lease
                and str(lease.job_id or "") == str(job_id)
                and str(lease.owner_token or "") == str(worker_token)
                and (_aware(lease.expires_at) or now) > now
            ):
                return False
        for child_id in child_ids:
            claim = session.get(GptProAccountOperationLeaseModel, int(child_id))
            if not (
                claim
                and str(claim.token or "") == str(worker_token)
                and str(claim.operation or "") == _DEVICE_BINDING_MIGRATION_OPERATION
                and (_aware(claim.expires_at) or now) > now
            ):
                return False
    return True


def _renew_business_device_migration_claim(
    job_id: str,
    worker_token: str,
    child_ids: List[int],
) -> None:
    if not _business_device_migration_claim_is_current(
        job_id, worker_token, child_ids,
    ):
        raise HTTPException(409, "母号设备迁移租约已失效")
    now = _utcnow()
    expires = now + timedelta(seconds=ALLOCATION_LEASE_SECONDS)
    with Session(engine) as session:
        session.exec(
            update(GptBusinessAllocationLeaseModel)
            .where(GptBusinessAllocationLeaseModel.job_id == str(job_id))
            .where(GptBusinessAllocationLeaseModel.owner_token == str(worker_token))
            .values(expires_at=expires, updated_at=now)
        )
        session.exec(
            update(GptProAccountOperationLeaseModel)
            .where(GptProAccountOperationLeaseModel.token == str(worker_token))
            .where(
                GptProAccountOperationLeaseModel.operation
                == _DEVICE_BINDING_MIGRATION_OPERATION
            )
            .values(expires_at=expires, updated_at=now)
        )
        session.commit()


def _release_business_device_migration_claim(
    job_id: str,
    worker_token: str,
) -> None:
    if not worker_token:
        return
    with Session(engine) as session:
        session.exec(
            delete(GptBusinessAllocationLeaseModel)
            .where(GptBusinessAllocationLeaseModel.job_id == str(job_id))
            .where(GptBusinessAllocationLeaseModel.owner_token == str(worker_token))
        )
        session.exec(
            delete(GptProAccountOperationLeaseModel)
            .where(GptProAccountOperationLeaseModel.token == str(worker_token))
            .where(
                GptProAccountOperationLeaseModel.operation
                == _DEVICE_BINDING_MIGRATION_OPERATION
            )
        )
        job = session.get(GptBusinessAllocationJobModel, str(job_id))
        if job and str(job.worker_token or "") == str(worker_token):
            job.worker_token = ""
            job.updated_at = _utcnow()
            session.add(job)
        session.commit()


def _update_business_device_migration(
    job_id: str,
    worker_token: str,
    *,
    state: Optional[str] = None,
    stage: Optional[str] = None,
    error: Optional[str] = None,
    child_id: int = 0,
    child_changes: Optional[dict] = None,
    policy_switched: Optional[bool] = None,
) -> None:
    with Session(engine) as session:
        job = session.get(GptBusinessAllocationJobModel, str(job_id))
        if not job or str(job.worker_token or "") != str(worker_token):
            raise HTTPException(409, "母号设备迁移任务已被其他 worker 接管")
        actions = _json_dict(job.action_state_json)
        children = actions.get("children") if isinstance(actions.get("children"), dict) else {}
        if child_id > 0 and child_changes is not None:
            current = children.get(str(child_id))
            current = dict(current) if isinstance(current, dict) else {}
            safe_child_changes = dict(child_changes)
            if "error" in safe_child_changes:
                safe_child_changes["error"] = (
                    _safe_business_device_migration_diagnostic(
                        safe_child_changes.get("error"), limit=500,
                    )
                )
            current.update(safe_child_changes)
            current["updated_at"] = _iso_utc(_utcnow())
            children[str(child_id)] = current
            actions["children"] = children
        if policy_switched is not None:
            actions["policy_switched"] = bool(policy_switched)
        if state is not None:
            job.state = str(state)
        if stage is not None:
            job.stage = str(stage)
        if error is not None:
            job.error = _safe_business_device_migration_diagnostic(
                error, limit=1500,
            )
        job.action_state_json = json.dumps(actions, ensure_ascii=False)
        job.remote_mutated = bool(
            job.remote_mutated
            or any(
                bool(value.get("remote_mutated"))
                for value in children.values() if isinstance(value, dict)
            )
        )
        job.updated_at = _utcnow()
        session.add(job)
        session.commit()


def _business_device_migration_child_action(job_id: str, child_id: int) -> dict:
    with Session(engine) as session:
        job = session.get(GptBusinessAllocationJobModel, str(job_id))
        actions = _json_dict(job.action_state_json) if job else {}
        children = actions.get("children") if isinstance(actions.get("children"), dict) else {}
        value = children.get(str(int(child_id)))
        return dict(value) if isinstance(value, dict) else {}


def _clear_business_child_cpa_link_after_delete(
    parent_id: int,
    child_id: int,
    *,
    expected_target_id: int,
    expected_auth_name: str,
    operation_token: str,
) -> None:
    """CAS-clear only the exact CPA link whose remote absence was confirmed."""
    with Session(engine) as session:
        if session.get_bind().dialect.name == "sqlite":
            session.connection().exec_driver_sql("BEGIN IMMEDIATE")
            child = session.get(GptProAccountModel, int(child_id))
        else:
            child = session.exec(
                select(GptProAccountModel)
                .where(GptProAccountModel.id == int(child_id))
                .with_for_update()
            ).first()
        if not child:
            raise HTTPException(404, "迁移子号不存在")
        claim = session.get(GptProAccountOperationLeaseModel, int(child_id))
        if not (
            claim
            and str(claim.token or "") == str(operation_token)
            and str(claim.operation or "") == _DEVICE_BINDING_MIGRATION_OPERATION
            and (_aware(claim.expires_at) or _utcnow()) > _utcnow()
            and int(child.business_parent_id or 0) == int(parent_id)
        ):
            raise HTTPException(409, "CPA 迁移子号归属或操作租约已变化")
        extra = _json_dict(child.extra_json)
        try:
            current_target = int(
                extra.get("cpa_synced_to_id") or extra.get("cpa_device_id") or 0
            )
        except (TypeError, ValueError):
            current_target = 0
        current_auth = str(extra.get("cpa_auth_name") or "").strip()
        if current_target <= 0 and not current_auth and not bool(extra.get("cpa_synced")):
            session.rollback()
            return
        if (
            current_target != int(expected_target_id)
            or current_auth != str(expected_auth_name or "").strip()
        ):
            raise HTTPException(409, "CPA 本地关联已变化，拒绝清除新关联")
        audit = {
            "target_id": current_target,
            "auth_name": current_auth,
            "removed_at": _iso_utc(_utcnow()),
            "reason": "business_device_binding_migration",
            "remote_deleted": True,
        }
        for key in (
            "cpa_synced", "cpa_synced_to_id", "cpa_synced_to_name",
            "cpa_device_id", "cpa_config_domain", "cpa_auth_name",
            "cpa_synced_at", "cpa_usage", "cpa_monitor_alert",
            "cpa_disabled", "cpa_disabled_at", "cpa_disabled_reason",
            "cpa_lifecycle_state", "cpa_monitor_suppressed",
            "cpa_migration_pending", "cpa_migration_target_id",
            "cpa_migration_source_disabled", "cpa_migration_started_at",
            "cpa_migration_last_error",
        ):
            extra.pop(key, None)
        extra["cpa_last_removed"] = audit
        child.extra_json = json.dumps(extra, ensure_ascii=False)
        child.updated_at = _utcnow()
        session.add(child)
        session.commit()


def _delete_business_child_cpa_remote_exact(
    parent_id: int,
    child_id: int,
    source_link: dict,
    source_target: dict,
    *,
    operation_token: str,
    guard: Callable[[], bool],
    clear_local_link: bool,
) -> None:
    provider = str(source_link.get("provider") or "")
    target_id = int(source_link.get("device_id") or 0)
    auth_name = str(source_link.get("remote_id") or "").strip()
    if provider != "cpa" or target_id <= 0 or not auth_name:
        raise HTTPException(409, "CPA 原设备关联快照不完整")
    current_target = _business_delivery_target_snapshot("cpa", target_id)
    if str(current_target.get("epoch") or "") != str(source_target.get("epoch") or ""):
        raise HTTPException(409, "CPA 原设备地址已变化，拒绝按旧快照删除")
    with Session(engine) as session:
        child = session.get(GptProAccountModel, int(child_id))
        if not child or int(child.business_parent_id or 0) != int(parent_id):
            raise HTTPException(409, "CPA 迁移子号归属已变化")
        email = str(child.email or "").strip()
    from api.delivery_devices import _delete_cpa_remote_exact, _internal_device_or_error

    internal = _internal_device_or_error("cpa", target_id)
    _delete_cpa_remote_exact(
        internal,
        {"remote_id": auth_name, "name": auth_name, "email": email},
        before_mutation=guard,
    )
    if clear_local_link:
        _clear_business_child_cpa_link_after_delete(
            parent_id,
            child_id,
            expected_target_id=target_id,
            expected_auth_name=auth_name,
            operation_token=operation_token,
        )


def _remove_business_child_migration_source_exact(
    parent_id: int,
    child_id: int,
    source_link: dict,
    source_target: dict,
    *,
    operation_token: str,
    guard: Callable[[], bool],
    clear_cpa_local_link: bool,
) -> dict:
    """Remove one immutable source identity and prove the email is now absent."""
    provider = str(source_link.get("provider") or "").strip().lower()
    device_id = int(source_link.get("device_id") or 0)
    remote_id = str(source_link.get("remote_id") or "").strip()
    expected_ref = f"{provider}:{device_id}"
    if (
        provider not in {"cpa", "sub2api"}
        or device_id <= 0
        or str(source_link.get("device_ref") or "") != expected_ref
        or not remote_id
    ):
        raise HTTPException(409, "原设备账号快照不完整")
    with Session(engine) as session:
        child = session.get(GptProAccountModel, int(child_id))
        if not child or int(child.business_parent_id or 0) != int(parent_id):
            raise HTTPException(409, "迁移子号归属已变化")
        email = str(child.email or "").strip()
        persisted_links, _incomplete = _business_child_delivery_links(child)
    exact_local = any(
        str(item.get("provider") or "") == provider
        and int(item.get("device_id") or 0) == device_id
        and str(item.get("remote_id") or "") == remote_id
        for item in persisted_links
    )
    live = _business_child_remote_link_on_device(source_target, email)
    if live is None:
        if exact_local:
            if provider == "sub2api":
                from api.gpt_plan_operations import _clear_sub2api_link_after_confirmed_delete

                _clear_sub2api_link_after_confirmed_delete(
                    int(child_id),
                    expected_device_id=device_id,
                    expected_remote_account_id=remote_id,
                    reason="business_device_binding_migration_remote_absent",
                    remote_deleted=True,
                    operation_token=operation_token,
                    expected_business_parent_id=int(parent_id),
                    state_guard=guard,
                )
            elif clear_cpa_local_link:
                _clear_business_child_cpa_link_after_delete(
                    int(parent_id), int(child_id),
                    expected_target_id=device_id,
                    expected_auth_name=remote_id,
                    operation_token=operation_token,
                )
        return {"deleted": False, "absence_confirmed": True}
    if (
        str(live.get("device_ref") or "") != expected_ref
        or str(live.get("remote_id") or "") != remote_id
    ):
        raise HTTPException(409, "原设备账号身份在迁移执行前已变化")
    if not guard():
        raise HTTPException(409, "母号设备迁移租约已失效")

    deleted = False
    if provider == "cpa":
        _delete_business_child_cpa_remote_exact(
            int(parent_id), int(child_id), source_link, source_target,
            operation_token=operation_token,
            guard=guard,
            clear_local_link=bool(clear_cpa_local_link),
        )
        deleted = True
    else:
        from api.gpt_plan_operations import (
            _clear_sub2api_link_after_confirmed_delete,
            _sub2api_device_or_error,
        )
        from services.sub2api_admin import Sub2ApiAdminError, delete_account

        device = _sub2api_device_or_error(device_id)
        try:
            confirmation = delete_account(
                device["api_url"], device["api_key"], remote_id,
                expected_email=email,
            )
        except Sub2ApiAdminError as exc:
            # A 404 can originate either from the identity GET or from a
            # deployment's DELETE route.  Only the independent exact-email
            # probe below is allowed to turn it into confirmed absence.
            if int(exc.status_code or 0) != 404:
                raise HTTPException(502, "原 Sub2API 账号删除未确认") from exc
            confirmation = {"deleted": False, "absence_confirmed": False}
        else:
            if not bool(confirmation.get("absence_confirmed")):
                raise HTTPException(502, "原 Sub2API 账号删除未确认")
            deleted = bool(confirmation.get("deleted"))
        if not guard():
            raise HTTPException(409, "母号设备迁移租约已失效")
        remaining = _business_child_remote_link_on_device(source_target, email)
        if remaining is not None:
            raise HTTPException(502, "原 Sub2API 账号删除后仍然存在")
        if exact_local:
            _clear_sub2api_link_after_confirmed_delete(
                int(child_id),
                expected_device_id=device_id,
                expected_remote_account_id=remote_id,
                reason="business_device_binding_migration",
                remote_deleted=bool(deleted),
                operation_token=operation_token,
                expected_business_parent_id=int(parent_id),
                state_guard=guard,
            )

    if not guard():
        raise HTTPException(409, "母号设备迁移租约已失效")
    if _business_child_remote_link_on_device(source_target, email) is not None:
        raise HTTPException(502, "原设备账号删除后仍然存在")
    return {"deleted": bool(deleted), "absence_confirmed": True}


def _confirm_business_child_migration_source_absent(
    parent_id: int,
    child_id: int,
    source_target: dict,
    *,
    guard: Callable[[], bool],
) -> None:
    if not guard():
        raise HTTPException(409, "母号设备迁移租约已失效")
    with Session(engine) as session:
        child = session.get(GptProAccountModel, int(child_id))
        if not child or int(child.business_parent_id or 0) != int(parent_id):
            raise HTTPException(409, "迁移子号归属已变化")
        email = str(child.email or "").strip()
    if _business_child_remote_link_on_device(source_target, email) is not None:
        raise HTTPException(409, "原设备在预检后出现了同邮箱账号，请重新发起迁移")
    if not guard():
        raise HTTPException(409, "母号设备迁移租约已失效")


def _verify_business_child_on_migration_target(
    parent_id: int,
    child_id: int,
    target: dict,
) -> None:
    with Session(engine) as session:
        child = session.get(GptProAccountModel, int(child_id))
        if not child or int(child.business_parent_id or 0) != int(parent_id):
            raise HTTPException(409, "迁移期间子号归属已变化")
        links, incomplete = _business_child_delivery_links(child)
    expected_ref = str(target.get("device_ref") or "")
    if incomplete or len(links) != 1 or str(links[0].get("device_ref") or "") != expected_ref:
        raise HTTPException(409, "新设备上传后本地精确关联未确认")


def _sync_business_child_to_migration_target(
    parent_id: int,
    child_id: int,
    target: dict,
    *,
    operation_token: str,
    guard: Callable[[], bool],
) -> dict:
    if not guard():
        raise HTTPException(409, "母号设备迁移租约已失效")
    with Session(engine) as session:
        child = session.get(GptProAccountModel, int(child_id))
        if not child or int(child.business_parent_id or 0) != int(parent_id):
            raise HTTPException(409, "迁移子号归属已变化")
    _assert_child_is_remote_member(int(parent_id), child)
    target_id = int(target.get("device_id") or 0)
    if str(target.get("provider") or "") == "cpa":
        from api.gpt_plan_operations import sync_account_to_cpa

        return sync_account_to_cpa(
            int(child_id), target_id,
            expected_business_parent_id=int(parent_id),
            operation_token=operation_token,
            delivery_guard=guard,
        )
    from api.gpt_plan_operations import sync_account_to_sub2api

    return sync_account_to_sub2api(
        int(child_id), target_id,
        expected_business_parent_id=int(parent_id),
        operation_token=operation_token,
        delivery_guard=guard,
    )


def _migrate_one_business_child_device(
    job_id: str,
    worker_token: str,
    request: dict,
    child_request: dict,
    all_child_ids: List[int],
) -> None:
    parent_id = int(request.get("parent_id") or 0)
    child_id = int(child_request.get("child_id") or 0)
    target = request.get("target") if isinstance(request.get("target"), dict) else {}
    target_ref = str(target.get("device_ref") or "")
    source_link = (
        child_request.get("source_link")
        if isinstance(child_request.get("source_link"), dict) else None
    )
    source_target = (
        child_request.get("source_target")
        if isinstance(child_request.get("source_target"), dict) else {}
    )
    source_absence_expected = bool(
        child_request.get("source_absence_confirmed")
    )
    source_ref = str((source_link or {}).get("device_ref") or "")
    policy_source = (
        request.get("source") if isinstance(request.get("source"), dict) else {}
    )
    policy_source_ref = str(policy_source.get("device_ref") or "")
    cleanup_required = bool(
        (source_ref and source_ref != target_ref)
        or source_absence_expected
    )

    def guard() -> bool:
        return _business_device_migration_claim_is_current(
            job_id, worker_token, all_child_ids,
        )

    _renew_business_device_migration_claim(
        job_id, worker_token, all_child_ids,
    )
    action = _business_device_migration_child_action(job_id, child_id)
    if str(action.get("state") or "") == "completed":
        if cleanup_required and not bool(action.get("old_cleanup_confirmed")):
            raise HTTPException(409, "旧设备清理尚未确认，拒绝完成迁移")
        _verify_business_child_on_migration_target(parent_id, child_id, target)
        return

    with Session(engine) as session:
        child = session.get(GptProAccountModel, child_id)
        membership = session.get(
            GptBusinessChildMembershipModel,
            int(child_request.get("membership_id") or 0),
        )
        if not (
            child and membership
            and int(child.business_parent_id or 0) == parent_id
            and int(membership.business_account_id or 0) == parent_id
            and int(membership.pro_account_id or 0) == child_id
            and membership.ended_at is None
        ):
            raise HTTPException(409, "迁移子号或成员流水已变化")
        current_links, incomplete = _business_child_delivery_links(child)
    if incomplete or len(current_links) > 1:
        raise HTTPException(409, "迁移子号当前设备关联不唯一")
    current_link = current_links[0] if current_links else None

    if (
        not source_link
        and not source_absence_expected
        and policy_source_ref
        and policy_source_ref != target_ref
    ):
        raise HTTPException(409, "原设备账号未经过精确核验，拒绝迁移")
    if cleanup_required and not source_target:
        raise HTTPException(409, "原设备核验快照缺失，拒绝迁移")
    if current_link and str(current_link.get("device_ref") or "") not in {
        target_ref, source_ref,
    }:
        raise HTTPException(409, "子号实际关联已偏离迁移源快照")

    def confirm_absent_source() -> None:
        _update_business_device_migration(
            job_id, worker_token, child_id=child_id,
            child_changes={
                "state": "running",
                "stage": "verifying_old_absence",
                "old_cleanup_required": True,
            },
        )
        _confirm_business_child_migration_source_absent(
            parent_id, child_id, source_target, guard=guard,
        )
        _update_business_device_migration(
            job_id, worker_token, child_id=child_id,
            child_changes={
                "source_absence_confirmed": True,
                "old_cleanup_confirmed": True,
            },
        )

    def remove_exact_source(*, clear_cpa_local_link: bool) -> None:
        provider = str((source_link or {}).get("provider") or "")
        stage = (
            "removing_old_sub2api" if provider == "sub2api"
            else "removing_old_cpa"
        )
        _update_business_device_migration(
            job_id, worker_token, child_id=child_id,
            child_changes={
                "state": "running", "stage": stage,
                "old_cleanup_required": True,
            },
        )
        result = _remove_business_child_migration_source_exact(
            parent_id, child_id, source_link or {}, source_target,
            operation_token=worker_token,
            guard=guard,
            clear_cpa_local_link=clear_cpa_local_link,
        )
        if not isinstance(result, dict) or not bool(result.get("absence_confirmed")):
            raise HTTPException(502, "原设备账号删除未确认")
        changes = {
            "source_absence_confirmed": True,
            "old_cleanup_confirmed": True,
        }
        if bool(result.get("deleted")):
            changes.update({"source_removed": True, "remote_mutated": True})
        _update_business_device_migration(
            job_id, worker_token, child_id=child_id,
            child_changes=changes,
        )

    if current_link and str(current_link.get("device_ref") or "") == target_ref:
        if cleanup_required and not bool(action.get("old_cleanup_confirmed")):
            if source_link:
                remove_exact_source(clear_cpa_local_link=False)
            else:
                confirm_absent_source()
        _verify_business_child_on_migration_target(parent_id, child_id, target)
        _update_business_device_migration(
            job_id, worker_token, child_id=child_id,
            child_changes={
                "state": "completed", "stage": "completed", "error": "",
                "new_verified": True,
            },
        )
        return

    if current_link:
        if not source_ref or str(current_link.get("device_ref") or "") != source_ref:
            raise HTTPException(409, "子号实际关联已偏离迁移源快照")

    # CPA→CPA uploads first so the existing CPA migration/compensation path can
    # establish the new exact link.  All other transitions clean the old device
    # before the target upload.
    defer_cpa_cleanup = bool(
        source_link
        and str(source_link.get("provider") or "") == "cpa"
        and str(target.get("provider") or "") == "cpa"
    )
    if cleanup_required and not bool(action.get("old_cleanup_confirmed")):
        if source_link and not defer_cpa_cleanup:
            remove_exact_source(clear_cpa_local_link=True)
        elif not source_link:
            confirm_absent_source()

    _renew_business_device_migration_claim(job_id, worker_token, all_child_ids)
    if str(_business_delivery_target_snapshot(
        str(target.get("provider") or ""), int(target.get("device_id") or 0),
    ).get("epoch") or "") != str(target.get("epoch") or ""):
        raise HTTPException(409, "目标设备地址在迁移期间已变化")
    _update_business_device_migration(
        job_id, worker_token, child_id=child_id,
        child_changes={"state": "running", "stage": "uploading_new"},
    )
    result = _sync_business_child_to_migration_target(
        parent_id, child_id, target,
        operation_token=worker_token, guard=guard,
    )
    if not isinstance(result, dict) or result.get("ok") is not True:
        raise HTTPException(502, "子号上传新设备未确认成功")
    _update_business_device_migration(
        job_id, worker_token, child_id=child_id,
        child_changes={
            "state": "running", "stage": "verifying_new",
            "new_uploaded": True, "remote_mutated": True,
        },
    )
    _verify_business_child_on_migration_target(parent_id, child_id, target)
    if defer_cpa_cleanup and not bool(
        _business_device_migration_child_action(job_id, child_id).get(
            "old_cleanup_confirmed"
        )
    ):
        remove_exact_source(clear_cpa_local_link=False)
    final_action = _business_device_migration_child_action(job_id, child_id)
    if cleanup_required and not bool(final_action.get("old_cleanup_confirmed")):
        raise HTTPException(409, "旧设备清理尚未确认，拒绝完成迁移")
    _update_business_device_migration(
        job_id, worker_token, child_id=child_id,
        child_changes={
            "state": "completed", "stage": "completed", "error": "",
            "new_verified": True,
        },
    )


def _commit_business_device_migration_policy(
    job_id: str,
    worker_token: str,
    request: dict,
    child_ids: List[int],
) -> None:
    parent_id = int(request.get("parent_id") or 0)
    source = request.get("source") if isinstance(request.get("source"), dict) else {}
    target = request.get("target") if isinstance(request.get("target"), dict) else {}
    target_now = _business_delivery_target_snapshot(
        str(target.get("provider") or ""), int(target.get("device_id") or 0),
    )
    if str(target_now.get("epoch") or "") != str(target.get("epoch") or ""):
        raise HTTPException(409, "目标设备地址在策略提交前已变化")
    now = _utcnow()
    with Session(engine) as session:
        if session.get_bind().dialect.name == "sqlite":
            session.connection().exec_driver_sql("BEGIN IMMEDIATE")
            parent = session.get(GptBusinessAccountModel, parent_id)
        else:
            parent = session.exec(
                select(GptBusinessAccountModel)
                .where(GptBusinessAccountModel.id == parent_id)
                .with_for_update()
            ).first()
        job = session.get(GptBusinessAllocationJobModel, str(job_id))
        if not (
            parent and job
            and str(job.state or "") == "running"
            and str(job.worker_token or "") == str(worker_token)
        ):
            raise HTTPException(409, "母号设备迁移提交已被 fencing")
        parent_lease = session.get(
            GptBusinessAllocationLeaseModel, f"parent:{parent_id}",
        )
        if not (
            parent_lease
            and str(parent_lease.job_id or "") == str(job_id)
            and str(parent_lease.owner_token or "") == str(worker_token)
            and (_aware(parent_lease.expires_at) or now) > now
        ):
            raise HTTPException(409, "母号设备迁移父租约已失效")
        policy = session.get(GptBusinessAutomationPolicyModel, parent_id)
        current = _business_policy_device_snapshot(policy, parent_id)
        if (
            int(current.get("revision") or 0)
            != int(request.get("expected_policy_revision") or 0)
            or str(current.get("device_ref") or "")
            != str(source.get("device_ref") or "")
        ):
            raise HTTPException(409, "母号设备策略在迁移期间发生变化")
        active_memberships = session.exec(
            select(GptBusinessChildMembershipModel)
            .where(GptBusinessChildMembershipModel.business_account_id == parent_id)
            .where(GptBusinessChildMembershipModel.ended_at.is_(None))  # type: ignore[union-attr]
        ).all()
        current_membership_ids = sorted(int(row.id or 0) for row in active_memberships)
        expected_membership_ids = sorted(
            int(value) for value in request.get("membership_ids") or []
        )
        if current_membership_ids != expected_membership_ids:
            raise HTTPException(409, "母号成员集合在迁移期间发生变化")
        current_child_ids = sorted({
            int(row.pro_account_id or 0)
            for row in active_memberships if int(row.pro_account_id or 0) > 0
        })
        if current_child_ids != sorted(child_ids):
            raise HTTPException(409, "母号管理子号集合在迁移期间发生变化")
        actions = _json_dict(job.action_state_json)
        child_actions = actions.get("children") if isinstance(actions.get("children"), dict) else {}
        expected_ref = str(target.get("device_ref") or "")
        child_requests = {
            int(item.get("child_id") or 0): item
            for item in request.get("children") or []
            if isinstance(item, dict) and int(item.get("child_id") or 0) > 0
        }
        for child_id in child_ids:
            action = child_actions.get(str(child_id))
            if not isinstance(action, dict) or str(action.get("state") or "") != "completed":
                raise HTTPException(409, f"子号 {child_id} 尚未完成设备迁移")
            child_request = child_requests.get(int(child_id), {})
            source_link = (
                child_request.get("source_link")
                if isinstance(child_request.get("source_link"), dict) else {}
            )
            cleanup_required = bool(
                (
                    str(source_link.get("device_ref") or "")
                    and str(source_link.get("device_ref") or "") != expected_ref
                )
                or child_request.get("source_absence_confirmed") is True
            )
            if cleanup_required and not (
                bool(action.get("old_cleanup_confirmed"))
                and (
                    bool(action.get("source_removed"))
                    or bool(action.get("source_absence_confirmed"))
                )
            ):
                raise HTTPException(
                    409, f"子号 {child_id} 原设备清理尚未权威确认",
                )
            child = session.get(GptProAccountModel, child_id)
            if not child or int(child.business_parent_id or 0) != parent_id:
                raise HTTPException(409, f"子号 {child_id} 归属已变化")
            links, incomplete = _business_child_delivery_links(child)
            if (
                incomplete or len(links) != 1
                or str(links[0].get("device_ref") or "") != expected_ref
            ):
                raise HTTPException(409, f"子号 {child_id} 新设备关联未确认")
        if policy is None:
            policy = GptBusinessAutomationPolicyModel(
                business_account_id=parent_id,
                created_at=now,
                updated_at=now,
            )
        provider = str(target.get("provider") or "")
        target_id = int(target.get("device_id") or 0)
        policy.delivery_type = provider
        policy.cpa_target_id = target_id if provider == "cpa" else None
        policy.sub2api_device_id = target_id if provider == "sub2api" else None
        policy.auto_rotation_enabled = True
        policy.revision = int(request.get("expected_policy_revision") or 0) + 1
        policy.updated_at = now
        session.add(policy)
        actions["policy_switched"] = True
        actions["policy_committed_at"] = _iso_utc(now)
        job.state = "completed"
        job.stage = "completed"
        job.retryable = False
        job.error = ""
        job.result_json = json.dumps({
            "ok": True,
            "parent_id": parent_id,
            "source_device_ref": str(source.get("device_ref") or ""),
            "target_device_ref": expected_ref,
            "policy_revision": int(policy.revision or 0),
            "migrated_children": len(child_ids),
        }, ensure_ascii=False)
        job.action_state_json = json.dumps(actions, ensure_ascii=False)
        job.completed_at = now
        job.updated_at = now
        session.add(job)
        session.commit()


def _run_business_device_binding_migration(job_id: str) -> dict:
    worker_token = _claim_business_device_migration(str(job_id))
    if not worker_token:
        return _business_device_migration_status(
            _get_business_device_migration_job_by_id(str(job_id))
        )
    try:
        with Session(engine) as session:
            job = session.get(GptBusinessAllocationJobModel, str(job_id))
            if not job:
                raise HTTPException(404, "母号设备迁移任务不存在")
            request = _json_dict(job.request_json)
        parent_id = int(request.get("parent_id") or 0)
        target = request.get("target") if isinstance(request.get("target"), dict) else {}
        source = request.get("source") if isinstance(request.get("source"), dict) else {}
        child_requests = [
            dict(item) for item in request.get("children") or []
            if isinstance(item, dict) and int(item.get("child_id") or 0) > 0
        ]
        child_ids = sorted(int(item["child_id"]) for item in child_requests)
        if str(source.get("device_ref") or "") == str(target.get("device_ref") or ""):
            for child_request in child_requests:
                child_id = int(child_request["child_id"])
                _update_business_device_migration(
                    job_id, worker_token, child_id=child_id,
                    child_changes={"state": "completed", "stage": "binding_unchanged", "error": ""},
                )
            with Session(engine) as session:
                job = session.get(GptBusinessAllocationJobModel, str(job_id))
                actions = _json_dict(job.action_state_json)
                actions["policy_switched"] = False
                job.action_state_json = json.dumps(actions, ensure_ascii=False)
                job.state = "completed"
                job.stage = "completed"
                job.retryable = False
                job.error = ""
                job.completed_at = _utcnow()
                job.updated_at = _utcnow()
                session.add(job)
                session.commit()
        else:
            for child_request in child_requests:
                child_id = int(child_request["child_id"])
                try:
                    _migrate_one_business_child_device(
                        job_id, worker_token, request, child_request, child_ids,
                    )
                except Exception as exc:
                    detail = _safe_business_device_migration_diagnostic(
                        exc.detail if isinstance(exc, HTTPException) else exc,
                        limit=500,
                    )
                    _update_business_device_migration(
                        job_id, worker_token,
                        state="action_required", stage="child_failed", error=detail,
                        child_id=child_id,
                        child_changes={
                            "state": "action_required", "stage": "failed", "error": detail,
                        },
                    )
                    raise
            _update_business_device_migration(
                job_id, worker_token, stage="committing_policy", error="",
            )
            _renew_business_device_migration_claim(
                job_id, worker_token, child_ids,
            )
            _commit_business_device_migration_policy(
                job_id, worker_token, request, child_ids,
            )
    except Exception as exc:
        detail = _safe_business_device_migration_diagnostic(
            exc.detail if isinstance(exc, HTTPException) else exc,
            limit=1000,
        )
        with Session(engine) as session:
            job = session.get(GptBusinessAllocationJobModel, str(job_id))
            if job and str(job.worker_token or "") == str(worker_token) and job.state != "completed":
                job.state = "action_required"
                if str(job.stage or "") not in {"child_failed", "committing_policy"}:
                    job.stage = "failed"
                job.retryable = True
                job.error = detail
                job.updated_at = _utcnow()
                session.add(job)
                session.commit()
    finally:
        _release_business_device_migration_claim(job_id, worker_token)
    job = _get_business_device_migration_job_by_id(str(job_id))
    return _business_device_migration_status(job)


def start_business_device_binding_migration(
    account_id: int,
    body: BizDeviceBindingMigrationRequest,
):
    operation_id = str(body.operation_id or "").strip()
    if not _MASTER_DISPATCH_OPERATION_RE.fullmatch(operation_id):
        raise HTTPException(400, "operation_id 格式无效")
    raw_revision = body.expected_policy_revision
    if isinstance(raw_revision, bool) or not isinstance(raw_revision, int):
        raise HTTPException(400, "expected_policy_revision 无效")
    expected_revision = raw_revision
    if expected_revision < 0 or expected_revision > 2_147_483_647:
        raise HTTPException(400, "expected_policy_revision 超出有效范围")
    _provider, _device_id, canonical = _parse_business_delivery_device_ref(
        body.target_device_ref
    )
    idempotency_key = (
        f"business-device-binding-migration:{int(account_id)}:{operation_id}"
    )
    with Session(engine) as session:
        existing = session.exec(
            select(GptBusinessAllocationJobModel).where(
                GptBusinessAllocationJobModel.idempotency_key == idempotency_key
            )
        ).first()
        if existing:
            request = _json_dict(existing.request_json)
            if (
                not _is_business_device_binding_migration_job(existing)
                or int(request.get("parent_id") or 0) != int(account_id)
                or str((request.get("target") or {}).get("device_ref") or "") != canonical
                or int(request.get("expected_policy_revision") or 0) != expected_revision
            ):
                raise HTTPException(409, "operation_id 已绑定另一份设备迁移请求")
            existing_id = str(existing.id)
        else:
            existing_id = ""
    if existing_id:
        return _run_business_device_binding_migration(existing_id)

    preview = _business_device_binding_migration_preview(
        int(account_id), canonical,
    )
    if int(preview.get("policy_revision") or 0) != expected_revision:
        raise HTTPException(409, {
            "code": "business_automation_policy_revision_conflict",
            "message": "母号设备绑定已变化，请重新预览",
            "expected_revision": expected_revision,
            "current_revision": int(preview.get("policy_revision") or 0),
        })
    if not bool(preview.get("allowed")):
        raise HTTPException(409, {
            "code": "business_device_migration_preflight_failed",
            "message": "母号设备迁移预检未通过",
            "preview": _public_business_device_migration_preview(preview),
        })
    request = _business_device_migration_request(preview, operation_id)
    request_hash = _business_device_migration_request_hash(request)
    now = _utcnow()
    job_id = f"device-migration-{_uuid.uuid4().hex}"
    action_children = {
        str(int(item.get("child_id") or 0)): {
            "state": "pending", "stage": "pending", "error": "",
        }
        for item in request.get("children") or [] if isinstance(item, dict)
    }
    with Session(engine) as session:
        job = GptBusinessAllocationJobModel(
            id=job_id,
            idempotency_key=idempotency_key,
            request_hash=request_hash,
            request_json=json.dumps(request, ensure_ascii=False),
            requested_business_account_id=int(account_id),
            selected_business_account_id=int(account_id),
            state="queued",
            stage="preflight",
            retryable=True,
            action_state_json=json.dumps({
                "children": action_children,
                "policy_switched": False,
            }, ensure_ascii=False),
            created_at=now,
            updated_at=now,
        )
        session.add(job)
        try:
            session.commit()
        except IntegrityError:
            session.rollback()
            winner = session.exec(
                select(GptBusinessAllocationJobModel).where(
                    GptBusinessAllocationJobModel.idempotency_key == idempotency_key
                )
            ).first()
            if not winner or str(winner.request_hash or "") != request_hash:
                raise HTTPException(409, "设备迁移 operation_id 幂等冲突")
            job_id = str(winner.id)
    return _run_business_device_binding_migration(job_id)


class BizInviteMemberRequest(BaseModel):
    emails: List[str] = Field(default_factory=list)
    # 仅“从 GPT PRO 普通账号选择”模式传。邮箱由后端按 ID 读取，不能由前端伪造。
    pro_account_ids: List[int] = Field(default_factory=list)
    # 账号池模式的明确标记。当该模式未指定 ID 时，后端在父锁内
    # 选择一个从未被当前母号邀请过的普通账号。不能仅根据空数组
    # 推断模式，否则会把“手动邮箱未填”误当成自动选号。
    pool_mode: bool = False
    # auto 按实际席位选择：普通 iCloud，高级 Gmail；明确选择的类型保持不变。
    candidate_mail_provider: str = "auto"
    seat_type: str = "default"          # default / prolite
    operation_id: str = ""
    _expected_seat_type: str = PrivateAttr(default="")
    _existing_selection: bool = PrivateAttr(default=False)


class BizRemoveMemberRequest(BaseModel):
    user_id: str
    email: str = ""
    pro_account_id: Optional[int] = None
    operation_id: str = ""


class BizReplaceChildRequest(BaseModel):
    old_kind: str = ""                  # member / invite
    old_user_id: str = ""
    old_email: str = ""
    old_pro_account_id: Optional[int] = None
    new_pro_account_id: Optional[int] = None
    pool_mode: bool = False
    auto_selected: bool = False
    candidate_mail_provider: str = "auto"
    operation_id: str = ""
    seat_type: str = "default"


class BizOperationStatusItemRequest(BaseModel):
    """One browser-side operation reference to reconcile against durable state."""

    operation_id: str
    parent_id: int = Field(gt=0)


class BizOperationStatusBatchRequest(BaseModel):
    """Bound reconciliation work so a page cannot issue an unbounded DB query."""

    operations: List[BizOperationStatusItemRequest] = Field(
        default_factory=list,
        max_length=200,
    )


def _business_membership_operation_status(
    row: GptBusinessChildMembershipModel,
) -> tuple[str, str]:
    """Return a public status/stage without exposing the persisted intent payload."""
    reason = str(row.end_reason or "").strip().lower()
    reason_parts = [part for part in reason.split(":") if part]
    base_reason = reason_parts[-1] if reason_parts else ""
    is_pending_reason = reason.startswith("pending:")
    is_replacement = bool(
        base_reason in {"replace", "replaced"}
        or row.replacement_pro_account_id is not None
        or str(row.replacement_email or "").strip()
    )

    # Releasing the old child is only the first half of a replacement.  Even if
    # the quota reservation is already consumed, the browser must retain the
    # operation until the replacement invite is durably marked complete.
    if is_replacement and row.replacement_completed_at is None:
        return "pending", "replacement_pending"
    if row.ended_at is None or is_pending_reason:
        if base_reason in {"remove", "removed"}:
            return "pending", "remove_pending"
        if base_reason in {"revoke", "revoked"}:
            return "pending", "revoke_pending"
        return "pending", "membership_pending"
    if is_replacement:
        return "completed", "replacement_completed"
    if base_reason in {"remove", "removed"}:
        return "completed", "remove_completed"
    if base_reason in {"revoke", "revoked"}:
        return "completed", "revoke_completed"
    return "completed", "membership_completed"


def _business_reservation_operation_status(
    row: GptBusinessRotationReservationModel,
) -> tuple[str, str]:
    state = str(row.state or "").strip().lower()
    action = str(row.action or "").strip().lower()
    action_label = {
        "remove": "remove",
        "revoke": "revoke",
        "replace": "replacement",
    }.get(action, "reservation")
    if state == "reserved":
        return "pending", f"{action_label}_reserved"
    if state in {"consumed", "released"}:
        return "completed", f"{action_label}_{state}"
    return "conflict", "reservation_state_conflict"


def _resolve_business_operation_status(
    operation_id: str,
    parent_id: int,
    memberships: List[GptBusinessChildMembershipModel],
    reservations: List[GptBusinessRotationReservationModel],
) -> dict:
    """Resolve one operation using only durable, non-secret database evidence."""
    item = {
        "operation_id": operation_id,
        "parent_id": int(parent_id),
        "status": "not_found",
        "stage": "not_found",
    }
    records: List[Any] = [*memberships, *reservations]
    if not records:
        return item

    record_parent_ids = {
        int(record.business_account_id)
        for record in records
    }
    if record_parent_ids != {int(parent_id)}:
        item.update(status="conflict", stage="parent_conflict")
        return item

    # operation_id is unique inside each table.  Multiple membership rows can
    # only come from corrupt/legacy data and cannot be reconciled safely.
    if len(memberships) > 1 or len(reservations) > 1:
        item.update(status="conflict", stage="duplicate_record_conflict")
        return item

    evidence: List[tuple[str, str, str]] = []
    if memberships:
        status, stage = _business_membership_operation_status(memberships[0])
        evidence.append(("membership", status, stage))
    if reservations:
        status, stage = _business_reservation_operation_status(reservations[0])
        evidence.append(("reservation", status, stage))

    conflict = next((entry for entry in evidence if entry[1] == "conflict"), None)
    if conflict:
        item.update(status="conflict", stage=conflict[2])
        return item

    pending = [entry for entry in evidence if entry[1] == "pending"]
    if pending:
        # Membership state is authoritative for the second half of replacement;
        # otherwise any pending durable evidence keeps the browser draft alive.
        replacement = next(
            (entry for entry in pending if entry[2] == "replacement_pending"),
            None,
        )
        membership = next(
            (entry for entry in pending if entry[0] == "membership"),
            None,
        )
        chosen = replacement or membership or pending[0]
        item.update(status="pending", stage=chosen[2])
        return item

    # Every surviving evidence row is terminal.  Prefer the membership stage so
    # a normal membership+reservation pair reports the user-visible operation,
    # not only the internal quota bookkeeping state.
    membership = next(
        (entry for entry in evidence if entry[0] == "membership"),
        None,
    )
    chosen = membership or evidence[0]
    item.update(status="completed", stage=chosen[2])
    return item


@router.post("/operations/status")
def reconcile_business_operation_statuses(body: BizOperationStatusBatchRequest):
    """Batch-reconcile browser drafts against durable server-side operation state.

    The response deliberately contains only the caller's operation reference and
    fixed status/stage values.  Membership emails, invite snapshots, result
    payloads, reservation reasons, cookies, and credentials never leave this API.
    """
    if len(body.operations) > 200:
        raise HTTPException(400, "单次最多对账 200 个操作")

    normalized: List[tuple[str, int]] = []
    for operation in body.operations:
        operation_id = str(operation.operation_id or "").strip()
        if not operation_id:
            raise HTTPException(400, "operation_id 不能为空")
        normalized.append((operation_id, int(operation.parent_id)))
    if not normalized:
        return {"items": []}

    operation_ids = sorted({operation_id for operation_id, _parent_id in normalized})
    with Session(engine) as session:
        membership_rows = session.exec(
            select(GptBusinessChildMembershipModel).where(
                GptBusinessChildMembershipModel.operation_id.in_(operation_ids)  # type: ignore[union-attr]
            )
        ).all()
        reservation_rows = session.exec(
            select(GptBusinessRotationReservationModel).where(
                GptBusinessRotationReservationModel.operation_id.in_(operation_ids)  # type: ignore[union-attr]
            )
        ).all()

    memberships_by_id: Dict[str, List[GptBusinessChildMembershipModel]] = {}
    for row in membership_rows:
        memberships_by_id.setdefault(str(row.operation_id or ""), []).append(row)
    reservations_by_id: Dict[str, List[GptBusinessRotationReservationModel]] = {}
    for row in reservation_rows:
        reservations_by_id.setdefault(str(row.operation_id or ""), []).append(row)

    items = [
        _resolve_business_operation_status(
            operation_id,
            parent_id,
            memberships_by_id.get(operation_id, []),
            reservations_by_id.get(operation_id, []),
        )
        for operation_id, parent_id in normalized
    ]
    return {"items": items}


# A Plans-originated regular child performs an OTP login before the remote
# invitation is sent.  That login may legitimately consume the full 180s OTP
# window, so the one-shot invitation's parent/child leases must outlive it.
INVITE_OPERATION_LEASE_SECONDS = 600


def _normalize_business_seat_type(value: str) -> str:
    seat_type = str(value or "default").strip().lower()
    if seat_type not in {"default", "prolite"}:
        raise HTTPException(400, "seat_type 只能是 default 或 prolite")
    return seat_type


def _normalize_business_candidate_mail_provider(value: Any) -> str:
    """Normalize the caller's ordinary-account mail-provider constraint."""
    provider = str(value or "auto").strip().lower()
    if provider not in {"auto", "gmail"}:
        raise HTTPException(
            400,
            "此独立项目的邀请候选仅支持 auto 或 gmail",
        )
    return provider


def _recognized_business_seat_type(value: Any) -> str:
    seat_type = str(value or "").strip().lower().replace("_", "-")
    if seat_type in {"default", "standard", "regular"}:
        return "default"
    if seat_type in {"prolite", "pro-lite"}:
        return "prolite"
    return ""


def _canonical_business_invite_request(
    account_id: int,
    body: BizInviteMemberRequest,
    *,
    operation_id: str,
) -> dict:
    """Normalize a direct invitation and attach its per-call correlation id."""
    emails: List[str] = []
    seen_emails: set[str] = set()
    for value in body.emails or []:
        email = str(value or "").strip().lower()
        if email and email not in seen_emails:
            emails.append(email)
            seen_emails.add(email)
    pro_account_ids: List[int] = []
    seen_ids: set[int] = set()
    for value in body.pro_account_ids or []:
        try:
            child_id = int(value)
        except (TypeError, ValueError):
            raise HTTPException(400, f"无效的 GPT PRO 子号 ID: {value}")
        if child_id <= 0:
            raise HTTPException(400, f"无效的 GPT PRO 子号 ID: {value}")
        if child_id not in seen_ids:
            pro_account_ids.append(child_id)
            seen_ids.add(child_id)
    if not emails and not pro_account_ids:
        raise HTTPException(400, "未填要邀请的邮箱或未选择 GPT PRO 普通账号")
    return {
        "operation_id": str(operation_id or "").strip(),
        "parent_id": int(account_id),
        "emails": emails,
        "pro_account_ids": pro_account_ids,
        "candidate_mail_provider": _normalize_business_candidate_mail_provider(
            body.candidate_mail_provider
        ),
        "seat_type": _normalize_business_seat_type(body.seat_type),
    }


def _normalized_business_invite_inputs(
    body: BizInviteMemberRequest,
) -> tuple[List[str], List[int]]:
    """Normalize caller-controlled targets without deriving server decisions."""
    emails: List[str] = []
    seen_emails: set[str] = set()
    for value in body.emails or []:
        email = str(value or "").strip().lower()
        if email and email not in seen_emails:
            emails.append(email)
            seen_emails.add(email)
    pro_account_ids: List[int] = []
    seen_ids: set[int] = set()
    for value in body.pro_account_ids or []:
        try:
            child_id = int(value)
        except (TypeError, ValueError):
            raise HTTPException(400, f"无效的 GPT PRO 子号 ID: {value}")
        if child_id <= 0:
            raise HTTPException(400, f"无效的 GPT PRO 子号 ID: {value}")
        if child_id not in seen_ids:
            pro_account_ids.append(child_id)
            seen_ids.add(child_id)
    return emails, pro_account_ids


def _derive_exact_business_invite_seat_type(
    seat_summary: dict,
    required_count: int = 1,
    *, invite_quota: Optional[dict] = None,
) -> str:
    """Choose an exact typed seat, preferring default when it can fit the batch."""
    try:
        needed = int(required_count)
    except (TypeError, ValueError):
        needed = 0
    if needed <= 0:
        raise HTTPException(400, "本次邀请人数必须大于 0")
    if not bool(seat_summary.get("seat_type_capacity_known")) or not bool(
        seat_summary.get("seat_type_occupancy_known")
    ):
        raise HTTPException(409, {
            "code": "seat_type_unknown",
            "message": "暂未取得可靠的分类席位总量和占用情况，无法安全推导本次邀请席位类型",
            "seat_summary": seat_summary,
        })

    by_type = seat_summary.get("by_type") or {}
    available_by_type: Dict[str, int] = {}
    for seat_type in ("default", "prolite"):
        item = by_type.get(seat_type) or {}
        available = item.get("available")
        if (
            item.get("availability_exact") is not True
            or not isinstance(available, int)
            or isinstance(available, bool)
        ):
            raise HTTPException(409, {
                "code": "seat_type_unknown",
                "message": "分类席位可用数不完整，无法安全推导本次邀请席位类型",
                "seat_type": seat_type,
                "seat_summary": seat_summary,
            })
        available_by_type[seat_type] = max(0, available)

    if sum(available_by_type.values()) <= 0:
        raise HTTPException(409, {
            "code": "no_invitable_seat",
            "message": "当前母号没有可邀请的空闲席位",
            "seat_summary": seat_summary,
        })
    # Stable default-first order avoids consuming an advanced entitlement when
    # a normal seat can truthfully fit the entire request.
    for seat_type in ("default", "prolite"):
        if available_by_type.get(seat_type, 0) >= needed:
            return seat_type
    raise HTTPException(409, {
        "code": "insufficient_typed_seat_capacity",
        "message": f"单一席位类型无法容纳本次 {needed} 个邀请",
        "required_count": needed,
        "available_by_type": available_by_type,
        "seat_summary": seat_summary,
    })


def _candidate_mail_provider(provider, seat_type, *, session=None) -> str:
    """Use the invitation database (and its transaction) for shared defaults."""
    if session is not None:
        return resolve_candidate_mail_provider(provider, seat_type, session=session)
    with Session(engine) as owned_session:
        return resolve_candidate_mail_provider(provider, seat_type, session=owned_session)


def _auto_select_unseen_regular_business_child(
    parent_id: int,
    *,
    excluded_ids: Optional[set[int]] = None,
    candidate_mail_provider: str = "auto",
    allowed_ids: Optional[set[int]] = None,
    seat_type: str = "",
) -> GptProAccountModel:
    """Pick healthy ready stock first, then never-invited ordinary stock.

    Completed BUSINESS memberships are audit history, not a reusable account
    pool. Candidate admission is delegated to the same global regular-pool
    query used by list, allocation, replenishment and TEAM 401 paths.
    ``parent_id`` remains for API compatibility but no longer affects priority.
    """
    del parent_id
    excluded = {
        int(value) for value in (excluded_ids or set()) if int(value) > 0
    }
    with Session(engine) as session:
        requested_provider = _candidate_mail_provider(
            _normalize_business_candidate_mail_provider(candidate_mail_provider), seat_type, session=session,
        )
        busy_ids = _active_gpt_pro_operation_account_ids(session)
        candidates = _regular_allocation_candidates(session, limit=0)
        for child in candidates:
            if (
                child.id is not None
                and int(child.id) not in excluded
                and (allowed_ids is None or int(child.id) in allowed_ids)
                and _is_business_child_candidate(child, busy_ids)
                and _business_child_matches_candidate_mail_provider(
                    child, requested_provider,
                )
            ):
                return child
    raise HTTPException(409, {
        "code": "no_eligible_regular_candidate",
        "message": (
            "暂无已注册 GPT、已关联普通号池且母号可用并完成收件授权的 Gmail 子号"
            if requested_provider == "gmail" else
            "暂无符合所选邮箱类型的 GPT 套餐普通账号"
            if requested_provider != "auto"
            else "暂无可自动选择的 GPT 套餐普通账号"
        ) + "（已排除已使用及占用/dead/告警/退款/PRO 账号）",
        "candidate_mail_provider": requested_provider,
    })


def _preflight_explicit_business_invite_children(
    parent_id: int,
    pro_account_ids: List[int],
    *,
    candidate_mail_provider: str = "auto",
) -> None:
    """Reject an explicitly selected unavailable/busy child before remote reads."""
    if not pro_account_ids:
        return
    requested_provider = _normalize_business_candidate_mail_provider(
        candidate_mail_provider
    )
    with Session(engine) as session:
        busy_ids = _active_gpt_pro_operation_account_ids(session)
        for child_id in pro_account_ids:
            child = session.get(GptProAccountModel, int(child_id))
            if child is None:
                raise HTTPException(404, f"GPT PRO 子号不存在: {child_id}")
            if not _business_child_matches_candidate_mail_provider(
                child, requested_provider,
            ):
                raise HTTPException(409, {
                    "code": "business_child_mail_provider_mismatch",
                    "message": (
                        f"所选子号邮箱类型不是 {requested_provider}："
                        f"{str(child.email or '').strip().lower()}"
                    ),
                    "pro_account_id": int(child_id),
                    "candidate_mail_provider": requested_provider,
                })
            parent = getattr(child, "business_parent_id", None)
            if parent == parent_id:
                continue
            if _business_child_has_completed_history(
                session,
                child_id=int(child_id),
                email=str(child.email or ""),
            ):
                raise HTTPException(409, {
                    "code": "business_child_not_reusable",
                    "message": f"该账号已退出可邀请普通账号池: {child.email}",
                    "pro_account_id": int(child_id),
                })
            if int(child_id) in busy_ids:
                lease = session.get(GptProAccountOperationLeaseModel, int(child_id))
                raise HTTPException(409, {
                    "code": "gpt_pro_account_busy",
                    "message": f"子号 {child_id} 正在执行 {str(getattr(lease, 'operation', '') or '其他操作')}",
                    "operation": str(getattr(lease, "operation", "") or ""),
                    "expires_at": _iso_utc(getattr(lease, "expires_at", None)),
                })
            if parent is not None or not _is_business_child_candidate(child, busy_ids):
                raise HTTPException(409, f"不可选择的子号: {child.email}")


def _resolve_public_business_invite_snapshot(
    account_id: int,
    body: BizInviteMemberRequest,
    *,
    operation_id: str,
    at: str,
    team: str,
    proxy: str,
    excluded_auto_candidate_ids: Optional[set[int]] = None,
) -> dict:
    """Derive one fresh invitation request from current input and workspace state."""
    emails, pro_account_ids = _normalized_business_invite_inputs(body)
    requested_pool_mode = bool(body.pool_mode)
    candidate_mail_provider = _normalize_business_candidate_mail_provider(
        body.candidate_mail_provider
    )
    if requested_pool_mode and emails:
        raise HTTPException(400, "账号池模式不能同时传入手动邮箱")
    if emails and candidate_mail_provider != "auto":
        raise HTTPException(
            400,
            "手动邮箱邀请不能指定 candidate_mail_provider",
        )
    if not requested_pool_mode and not emails and not pro_account_ids:
        raise HTTPException(400, "手动邀请未填邮箱；如需后端自动选号请传 pool_mode=true")

    pool_mode = bool(requested_pool_mode or (pro_account_ids and not emails))

    auto_selected_id: Optional[int] = None
    # The live seat decides the default mailbox before any automatic child is
    # selected or logged in. An empty Gmail/iCloud pool never changes that seat
    # decision or falls through to a different provider.
    automatic_selection = bool(requested_pool_mode and not pro_account_ids)
    if automatic_selection:
        with Session(engine) as candidate_session:
            local_candidates = _regular_allocation_candidates(candidate_session, limit=0)
        if not any(int(row.id or 0) not in (excluded_auto_candidate_ids or set())
                   and _business_child_matches_candidate_mail_provider(row, candidate_mail_provider)
                   for row in local_candidates):
            raise HTTPException(409, {"code": "no_eligible_regular_candidate",
                "message": "暂无符合条件且未占用的 GPT 套餐普通账号", "candidate_mail_provider": candidate_mail_provider})
    if not automatic_selection:
        _preflight_explicit_business_invite_children(
            account_id, pro_account_ids, candidate_mail_provider=candidate_mail_provider,
        )
    state = _fetch_workspace_state(account_id, at, team, proxy)
    if requested_pool_mode and not pro_account_ids:
        with Session(engine) as quota_session:
            invite_quota = _invite_quota(quota_session, account_id)
        selected_seat_type = _derive_exact_business_invite_seat_type(
            state.get("seat_summary") or {}, 1, invite_quota=invite_quota,
        )
        candidate_mail_provider = _candidate_mail_provider(candidate_mail_provider, selected_seat_type)
        selected = _auto_select_unseen_regular_business_child(
            account_id,
            excluded_ids=excluded_auto_candidate_ids,
            candidate_mail_provider=candidate_mail_provider,
        )
        auto_selected_id = int(selected.id)
        pro_account_ids = [auto_selected_id]
    remote_seat_type_by_email = {
        str(item.get("email") or "").strip().lower():
            _recognized_business_seat_type(item.get("seat_type"))
        for item in (state.get("members") or []) + (state.get("invites") or [])
        if str(item.get("email") or "").strip()
    }
    remote_emails = set(remote_seat_type_by_email)
    selected_email_by_id: Dict[int, str] = {}
    if pro_account_ids:
        with Session(engine) as session:
            for child_id in pro_account_ids:
                child = session.get(GptProAccountModel, int(child_id))
                if child is not None:
                    selected_email_by_id[int(child_id)] = str(
                        child.email or ""
                    ).strip().lower()
    target_emails = list(dict.fromkeys([
        *emails,
        *(
            selected_email_by_id.get(int(child_id), "")
            for child_id in pro_account_ids
        ),
    ]))
    target_emails = [email for email in target_emails if email]
    post_emails = [email for email in target_emails if email not in remote_emails]
    if post_emails:
        with Session(engine) as quota_session:
            invite_quota = _invite_quota(quota_session, account_id)
        seat_type = _derive_exact_business_invite_seat_type(
            state.get("seat_summary") or {}, len(post_emails),
            invite_quota=invite_quota,
        )
        seat_type_source = "live_exact_remaining_capacity"
    else:
        # A previous one-shot may have reached OpenAI and lost its local
        # checkpoint.  A fresh request must be able to attach that already
        # present target even when the workspace has no free seat.  The single
        # request-level value is only a fallback; the locked attach path stores
        # each pre-existing target's actual remote seat type independently.
        existing_types = [
            remote_seat_type_by_email.get(email, "")
            for email in target_emails
            if remote_seat_type_by_email.get(email, "")
        ]
        seat_type = existing_types[0] if existing_types else _normalize_business_seat_type(
            body.seat_type
        )
        seat_type_source = "existing_remote_target"

    expected_seat_type = _recognized_business_seat_type(body._expected_seat_type)
    if expected_seat_type and expected_seat_type != seat_type:
        raise HTTPException(409, {
            "code": "business_invite_seat_changed",
            "message": "母号可邀请席位类型已变化，未登录子号或发送邀请",
            "expected_seat_type": expected_seat_type,
            "seat_type": seat_type,
        })
    if pro_account_ids:
        new_ids = [child_id for child_id in pro_account_ids
                   if selected_email_by_id.get(child_id) in post_emails]
        if new_ids:
            if not (body._existing_selection and candidate_mail_provider == "auto"):
                candidate_mail_provider = _candidate_mail_provider(candidate_mail_provider, seat_type)
            _preflight_explicit_business_invite_children(
                account_id, new_ids, candidate_mail_provider=candidate_mail_provider,
            )
            if not body._existing_selection:
                from services.gmail_plan_support import gmail_registration_ready
                with Session(engine) as session:
                    for child_id in new_ids:
                        child = session.get(GptProAccountModel, child_id)
                        if child and _business_child_candidate_mail_provider(child) == "gmail" and not gmail_registration_ready(child):
                            raise HTTPException(409, {"code": "gmail_registration_not_ready",
                                "message": "Gmail 子号须已注册 GPT、已关联普通号池且母号可用并完成收件授权，未开始邀请",
                                "pro_account_id": child_id})

    resolved_body = BizInviteMemberRequest(
        emails=emails,
        pro_account_ids=pro_account_ids,
        pool_mode=pool_mode,
        candidate_mail_provider=candidate_mail_provider,
        seat_type=seat_type,
        operation_id=operation_id,
    )
    canonical = _canonical_business_invite_request(
        account_id, resolved_body, operation_id=operation_id,
    )
    canonical.update({
        "pool_mode": pool_mode,
        "candidate_mail_provider": candidate_mail_provider,
        "request_mode": (
            "pool_auto" if auto_selected_id is not None
            else "pool_explicit" if pool_mode and not emails
            else "manual" if emails and not pro_account_ids
            else "mixed_explicit"
        ),
        "auto_selected_pro_account_id": auto_selected_id,
        "seat_type_source": seat_type_source,
        "preexisting_remote_emails": sorted(
            set(target_emails) & remote_emails
        ),
        "preexisting_remote_pro_account_ids": [
            int(child_id)
            for child_id, email in selected_email_by_id.items()
            if email in remote_emails
        ],
    })
    return canonical


def _biz_at_team_or_400(account_id: int):
    # Bound GPT Plans mothers additionally verify server acceptance and renew
    # a stale AT through their saved browser session before any mutation.
    from services.business_session_health import ensure_session
    ensure_session(account_id)
    return _assert_business_team_session_usable(account_id, status_code=409)


def _active_gpt_pro_operation_account_ids(
    session: Session,
    *,
    ignore_token: str = "",
) -> set[int]:
    query = select(GptProAccountOperationLeaseModel).where(
        GptProAccountOperationLeaseModel.expires_at > _utcnow()
    )
    if ignore_token:
        query = query.where(GptProAccountOperationLeaseModel.token != ignore_token)
    from services.gpt_plan_preparation_store import preparation_busy_ids

    return (
        {int(row.account_id) for row in session.exec(query).all()}
        | preparation_busy_ids(session)
    )


def _acquire_business_child_operation_claims(
    account_ids: List[int],
    *,
    operation: str,
    token: str,
    ttl_seconds: int = ALLOCATION_LEASE_SECONDS,
) -> None:
    """邀请/替换和退款、升级 PRO 争用同一账号主键。"""
    ids = sorted({int(value) for value in account_ids if int(value) > 0})
    if not ids:
        return
    now = _utcnow()
    expires = now + timedelta(seconds=max(60, int(ttl_seconds or 60)))
    try:
        with Session(engine) as session:
            from services.gpt_plan_preparation_store import preparation_busy_ids

            preparing_ids = preparation_busy_ids(session)
            for account_id in ids:
                if not session.get(GptProAccountModel, account_id):
                    raise HTTPException(404, f"GPT PRO 子号不存在: {account_id}")
                if account_id in preparing_ids:
                    raise HTTPException(409, {
                        "code": "gpt_pro_account_busy",
                        "message": "子号正在准备账号登录与安全凭据，请等待准备完成",
                        "operation": "account_preparation",
                    })
                current = session.get(GptProAccountOperationLeaseModel, account_id)
                if current and (_aware(current.expires_at) or now) <= now:
                    session.delete(current)
                    session.flush()
                    current = None
                if current:
                    if current.token != token:
                        raise HTTPException(
                            409,
                            {
                                "code": "gpt_pro_account_busy",
                                "message": f"子号 {account_id} 正在执行 {current.operation}",
                                "operation": current.operation,
                                "expires_at": _iso_utc(current.expires_at),
                            },
                        )
                    current.operation = operation
                    current.expires_at = expires
                    current.updated_at = now
                    session.add(current)
                else:
                    session.add(GptProAccountOperationLeaseModel(
                        account_id=account_id,
                        operation=operation,
                        token=token,
                        expires_at=expires,
                        created_at=now,
                        updated_at=now,
                    ))
            session.commit()
    except IntegrityError as exc:
        raise HTTPException(409, "子号刚被其他流程占用，请刷新后重试") from exc


def _release_business_child_operation_claims(token: str) -> None:
    if not token:
        return
    with Session(engine) as session:
        rows = session.exec(
            select(GptProAccountOperationLeaseModel)
            .where(GptProAccountOperationLeaseModel.token == token)
        ).all()
        for row in rows:
            session.delete(row)
        if rows:
            session.commit()


def _transfer_business_child_operation_claims(
    account_ids: List[int],
    *,
    from_token: str,
    to_token: str,
    operation: str,
) -> None:
    """Atomically hand pre-snapshot child reservations to the claimed worker."""
    ids = sorted({int(value) for value in account_ids if int(value) > 0})
    if not ids:
        return
    now = _utcnow()
    expires = now + timedelta(seconds=ALLOCATION_LEASE_SECONDS)
    with Session(engine) as session:
        result = session.exec(
            update(GptProAccountOperationLeaseModel)
            .where(GptProAccountOperationLeaseModel.account_id.in_(ids))  # type: ignore[union-attr]
            .where(GptProAccountOperationLeaseModel.token == str(from_token))
            .values(
                token=str(to_token),
                operation=str(operation),
                expires_at=expires,
                updated_at=now,
            )
        )
        if int(getattr(result, "rowcount", 0) or 0) != len(ids):
            session.rollback()
            raise HTTPException(409, {
                "code": "gpt_pro_account_claim_lost",
                "message": "子号预留已变化，未发送远程邀请",
            })
        session.commit()


def _business_pool_child_claim_ids(
    account_id: int,
    *,
    pro_account_id: Optional[int] = None,
    email: str = "",
    operation_id: str = "",
    remote_user_id: str = "",
) -> List[int]:
    """解析 remove/revoke 恢复请求对应的池选子号；手动邮箱返回空。"""
    if pro_account_id is not None:
        return [int(pro_account_id)]
    normalized_email = str(email or "").strip().lower()
    with Session(engine) as session:
        membership = None
        if operation_id:
            membership = session.exec(
                select(GptBusinessChildMembershipModel).where(
                    GptBusinessChildMembershipModel.operation_id == str(operation_id)
                )
            ).first()
        if membership is None and remote_user_id:
            membership = session.exec(
                select(GptBusinessChildMembershipModel)
                .where(GptBusinessChildMembershipModel.business_account_id == account_id)
                .where(GptBusinessChildMembershipModel.remote_user_id == str(remote_user_id))
                .where(GptBusinessChildMembershipModel.ended_at.is_(None))  # type: ignore[union-attr]
            ).first()
        if membership is None and normalized_email:
            membership = _active_membership(session, account_id, email=normalized_email)
        if (
            membership
            and int(membership.business_account_id) == int(account_id)
            and membership.pro_account_id is not None
            and str(membership.source or "").strip().lower() == "pool"
        ):
            return [int(membership.pro_account_id)]
    return []


def _is_business_child_candidate(
    acc: GptProAccountModel,
    busy_account_ids: Optional[set[int]] = None,
) -> bool:
    """BUSINESS 可选子号必须是干净、启用、未分配的 GPT PRO 普通账号。"""
    extra = _json_dict(acc.extra_json)
    raw_alerts = str(getattr(acc, "pending_alerts_json", "[]") or "").strip()
    try:
        parsed_alerts = json.loads(raw_alerts or "[]")
        has_pending_deactivation_alert = (
            not isinstance(parsed_alerts, list) or bool(parsed_alerts)
        )
    except (TypeError, ValueError, json.JSONDecodeError):
        # The bell queue only contains deactivation alerts. Corrupt queue
        # state is unknown health, not an empty/healthy queue.
        has_pending_deactivation_alert = True
    delivery_exhaustion = (
        extra.get("delivery_exhaustion")
        if isinstance(extra.get("delivery_exhaustion"), dict)
        else {}
    )
    catalog_category = str(
        getattr(acc, "catalog_category", "") or ""
    ).strip().lower()
    plan_type = str(getattr(acc, "plan_type", "") or "").strip().lower()
    source_pool = str(getattr(acc, "source_pool", "") or "").strip().lower()
    return bool(
        (acc.email or "").strip()
        and bool(acc.enabled)
        and not bool(acc.dangerous)
        and not bool(getattr(acc, "policy_warning", False))
        and not has_pending_deactivation_alert
        and not bool(acc.is_pro)
        # The authoritative plan table also contains PLUS/GO/PRO members and
        # BUSINESS mother catalogue rows.  ``is_pro=False`` alone no longer
        # means "ordinary child candidate" after the pool cutover.
        and catalog_category in {"", "regular"}
        and plan_type in {"", "free", "chatgptfreeplan"}
        and source_pool != "gpt_business"
        and not str(acc.refund_status or "").strip()
        and getattr(acc, "business_parent_id", None) is None
        # A released/manual account can still retain an exact Sub2API remote
        # identity or an uncertain upload intent.  Reusing it under another
        # BUSINESS parent would make the old device linkage cross tenant scope.
        # Only the exact-delete/confirmed-absence path may clear these fields.
        and not str(extra.get("sub2api_remote_account_id") or "").strip()
        and not bool(extra.get("sub2api_sync_pending"))
        # A mother-first manual device replacement deliberately releases the
        # workspace membership before deleting the old remote credential.  A
        # durable quarantine prevents that just-released child from being
        # selected by another mother during a crash/retry window.
        and not isinstance(extra.get("delivery_replacement_pending"), dict)
        # Only the literal provider-confirmed boolean excludes an account.  Do
        # not infer exhaustion from strings, percentages, stale errors or an
        # unknown snapshot.  The cleanup flow clears/updates this durable fact
        # only after a new usable credential lifecycle is established.
        and delivery_exhaustion.get("limit_reached") is not True
        and (
            busy_account_ids is None
            or acc.id is None
            or int(acc.id) not in busy_account_ids
        )
    )


